(window.BOOKS=window.BOOKS||[]).push({"id": "mission", "num": 4, "color": "#E07B24", "title": "مأموریت فضایی", "sub": "کتابچه راهنمای طراحی، ساخت، پرتاب و بازیابی برای تیم‌های دانش‌آموزی", "motto": "طراحی کن، بساز، بیازما، پرتاب کن، بازیابی کن", "aud": "دوره‌های اول و دوم متوسطه — تیم ۲ یا ۳ نفره", "chapters": [{"t": "سخنی با شما، مهندسان جوان هوافضا", "n": "", "h": "<h2>سخنی با شما، مهندسان جوان هوافضا</h2><p class=\"lead\">سه، دو، یک، پرتاب! در اتاق کنترل هر مأموریت فضایی، این چند ثانیه حاصل ماه‌ها طراحی، محاسبه و آزمون است. پرتابگر باید پایدار اوج بگیرد، بوسترها در لحظه درست جدا شوند، محموله سالم به مقصد برسد و در پایان، کپسول مأموریت با چتر یا سامانه‌ای دیگر آرام و سالم به زمین بازگردد. یک خطای کوچک در هر مرحله می‌تواند کل مأموریت را ناکام بگذارد؛ و همین است که مهندسی فضا را هیجان‌انگیز می‌کند.</p><p>در این گرایش، شما و هم‌تیمی‌هایتان یک <b>تیم مأموریت</b> هستید. مأموریت شما این است: یک محموله حساس، یعنی <b>تخم‌مرغ خام</b>، را درون کپسول مأموریت با یک <b>پرتابگر آبی</b> به آسمان بفرستید و آن را سالم بازیابی کنید. در این مسیر، خلاصه‌ای از دانش مهندسی هوافضا را تجربه می‌کنید: فیزیک پیشرانش، پایداری پرواز، سازه، جداسازی مراحل، چترهای بازیابی، حسگرها و تحلیل داده.</p><p>لازم نیست از پیش چیزی درباره موشک بدانید. هر موضوع از پایه، با مثال و شکل توضیح داده شده است. ریاضیات کتاب در حد کتاب‌های درسی است و بخش‌هایی که ریاضیات بیشتری لازم دارند، با «برای دوره دوم» مشخص شده‌اند. پرتابگر آبی به فضا نمی‌رود؛ اما تصمیم‌هایی که شما می‌گیرید، همان تصمیم‌های مهندسان فضاست.</p><h2>سخنی با معلمان و مربیان پژوهش‌سراها</h2><p>این کتابچه بر پایه فصل ۴ («مأموریت فضایی») از بخش دوم شیوه‌نامه هشتمین دوره نوشته شده است و به گونه‌ای تنظیم شده که بتوان بر پایه فصل‌های آن یک دوره آموزشی برگزار کرد. هر فصل با اهداف و زمان پیشنهادی آغاز می‌شود و با خلاصه، پرسش‌ها و یک فعالیت عملی پایان می‌یابد. پاسخ پرسش‌ها در پیوست ۱ آمده است.</p><p>دوره دو مسیر دارد: <b>مسیر پایه</b> (فصل‌های ۱ تا ۱۰ و ۱۵ و ۱۶) که برای اجرای مأموریت الزامی کافی است و هر تیم مدرسه‌ای، حتی در دوره اول متوسطه، می‌تواند آن را کامل کند؛ و <b>ماژول‌های پیشرفته</b> (فصل‌های ۱۱ تا ۱۴) که انتخابی و امتیازآورند. دست شما باز است: بسته به امکانات پژوهش‌سرا، علاقه تیم‌ها و زمان، هر ترکیبی از ماژول‌ها را انتخاب کنید.</p><h2>نشانه‌های این کتابچه</h2><div class=\"row2\"><div class=\"box tip\"><div class=\"box-t\">نکته</div><div>راهنمایی کاربردی برای ساخت یا پرتاب بهتر.</div></div><div class=\"box warn\"><div class=\"box-t\">هشدار ایمنی</div><div>موارد ایمنی و اشتباه‌های خطرناک.</div></div></div><div class=\"row2\"><div class=\"box out\"><div class=\"box-t\">پیوند با شیوه‌نامه و داوری</div><div>آنچه در این بخش یاد می‌گیرید، کدام الزام یا معیار داوری را پوشش می‌دهد.</div></div><div class=\"box why\"><div class=\"box-t\">برای کنجکاوها و دوره دوم</div><div>مطالب عمیق‌تر یا محاسبات پیشرفته‌تر؛ خواندن آن‌ها الزامی نیست.</div></div></div>"}, {"t": "شیوه‌نامه گرایش مأموریت فضایی در یک نگاه", "n": "", "h": "<h2>شیوه‌نامه گرایش مأموریت فضایی در یک نگاه</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:22%\">موضوع</th><th style=\"width:78%\">آنچه شیوه‌نامه می‌خواهد</th></tr><tr><td class=\"l\">شرکت‌کنندگان</td><td class=\"l\">دانش‌آموزان دوره‌های اول و دوم متوسطه، تیم دو یا سه‌نفره، از یک منطقه، یک دوره و هم‌جنس.</td></tr><tr><td class=\"l\">مأموریت پایه (الزامی)</td><td class=\"l\">یک تخم‌مرغ خام درون کپسول مأموریت با پرتابگر آبی به ارتفاع می‌رسد و با سامانه بازیابی سالم به زمین بازمی‌گردد.</td></tr><tr><td class=\"l\">پرتابگر</td><td class=\"l\">بدنه از بطری PET نوشابه گازدار سالم؛ پیشران فقط آب و هوای فشرده؛ دارای بالک و پایداری پروازی.</td></tr><tr><td class=\"l\">کپسول مأموریت</td><td class=\"l\">دو بخش مجزا (محموله و تجهیزات)؛ درِ مهارشده؛ ضربه‌گیری با طراحی داخلی؛ پوشاندن مستقیم تخم‌مرغ ممنوع.</td></tr><tr><td class=\"l\">سامانه بازیابی</td><td class=\"l\">چتر، نوار کندکننده، سازه جاذب انرژی یا هر سامانه کاهنده سرعت؛ سرعت فرود ۳ تا ۶ متر بر ثانیه توصیه می‌شود.</td></tr><tr><td class=\"l\">سکوی پرتاب</td><td class=\"l\">پایدار و مقاوم، با فشارسنج، ضامن ایمنی و رهاساز از راه دور.</td></tr><tr><td class=\"l\">سنجش عملکرد</td><td class=\"l\">برآورد ارتفاع اوج و زمان پرواز با روشی مستند.</td></tr><tr><td class=\"l\">ماژول‌های تکمیلی</td><td class=\"l\">بوستر، جداسازی بوسترها یا مراحل، جداسازی کپسول، سنجش ارتفاع، مأموریت علمی کپسول (کن‌ست)، شبیه‌سازی؛ انتخابی و امتیازآور.</td></tr><tr><td class=\"l\">ایمنی (بندهای حذف‌کننده)</td><td class=\"l\">فشار حداکثر ۵ بار؛ فقط بطری PET نوشابه گازدار سالم؛ پر کردن هوا و رهاسازی از دست‌کم ۱٫۵ متر با شلنگ بلند و رهاساز از راه دور (این کتاب ۵ متر را توصیه می‌کند) و تماشاگران دست‌کم ۱۰ متر دورتر.</td></tr><tr><td class=\"l\">مستندات</td><td class=\"l\">نمون‌برگ ۱، پرونده مأموریت PDF (حداکثر ۲۰ صفحه)، فیلم ۵ تا ۸ دقیقه، ویدئوی پیوسته پرواز رسمی، کاربرگ ثبت پرواز با امضای مربی و ....</td></tr><tr><td class=\"l\">سفر یادگیری</td><td class=\"l\">سفر یادگیری همین گرایش را در برنامه آسمان‌نما بگذرانید. نمره کارنامه آن (۰ تا ۱۰)، پس از راستی‌آزمایی کد QR، آخرین ردیف نمون‌برگ داوری است و در آثار تیمی میانگین نمره اعضا حساب می‌شود. ارسال کارنامه اختیاری است، اما بدون آن این ۱۰ امتیاز از دست می‌رود.</td></tr><tr><td class=\"l\">هوش مصنوعی</td><td class=\"l\">در طراحی، برنامه‌نویسی یا نگارش با ذکر صریح و ارسال پرامپت‌ها بلامانع است؛ داده‌های آزمون‌ها و پرواز، کاربرگ ثبت پرواز و ویدئوی پرواز باید واقعی باشد.</td></tr></table></div><h2>جدول داوری و فصل‌های مرتبط</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:46%\">معیار داوری</th><th style=\"width:10%\">امتیاز</th><th style=\"width:44%\">فصل‌ها</th></tr><tr><td class=\"l\">۱. تعریف مأموریت</td><td class=\"l\">۷</td><td class=\"l\">فصل ۲</td></tr><tr><td class=\"l\">۲. طراحی و محاسبات</td><td class=\"l\">۹</td><td class=\"l\">فصل‌های ۳ تا ۶، ۹ و ۱۰</td></tr><tr><td class=\"l\">۳. آزمون و بهبود</td><td class=\"l\">۱۱</td><td class=\"l\">فصل ۱۵</td></tr><tr><td class=\"l\">۴. پرتابگر</td><td class=\"l\">۷</td><td class=\"l\">فصل‌های ۵ و ۷</td></tr><tr><td class=\"l\">۵. سکوی پرتاب</td><td class=\"l\">۶</td><td class=\"l\">فصل ۸</td></tr><tr><td class=\"l\">۶. سامانه بازیابی</td><td class=\"l\">۱۰</td><td class=\"l\">فصل ۱۰</td></tr><tr><td class=\"l\">۷. سلامت محموله</td><td class=\"l\">۹</td><td class=\"l\">فصل ۹</td></tr><tr><td class=\"l\">۸. سنجش عملکرد (برآورد ارتفاع اوج و زمان پرواز)</td><td class=\"l\">۴</td><td class=\"l\">فصل ۶</td></tr><tr><td class=\"l\">۹. بوستر</td><td class=\"l\">۷</td><td class=\"l\">فصل ۱۱ (و سکوی چهاربوستری در فصل ۸)</td></tr><tr><td class=\"l\">۱۰. جداسازی بوسترها یا مراحل</td><td class=\"l\">۵</td><td class=\"l\">فصل‌های ۱۱ و ۱۲</td></tr><tr><td class=\"l\">۱۱. جداسازی کپسول</td><td class=\"l\">۶</td><td class=\"l\">فصل ۱۲</td></tr><tr><td class=\"l\">۱۲. ثبت ارتفاع با حسگر</td><td class=\"l\">۴</td><td class=\"l\">فصل‌های ۶ و ۱۳</td></tr><tr><td class=\"l\">۱۳. مأموریت علمی کپسول</td><td class=\"l\">۴</td><td class=\"l\">فصل ۱۳</td></tr><tr><td class=\"l\">۱۴. شبیه‌سازی</td><td class=\"l\">۳</td><td class=\"l\">فصل ۱۴</td></tr><tr><td class=\"l\">۱۵. پرونده مأموریت و فیلم</td><td class=\"l\">۵</td><td class=\"l\">فصل ۱۶</td></tr><tr><td class=\"l\">۱۶. تسلط و کار تیمی</td><td class=\"l\">۴</td><td class=\"l\">همه فصل‌ها؛ فصل ۱۶</td></tr><tr><td class=\"l\">۱۷. سفر یادگیری آسمان‌نما</td><td class=\"l\">۱۰</td><td class=\"l\">برنامه آسمان‌نما (قطب کشوری)</td></tr></table></div><div class=\"box out\"><div class=\"box-t\">دو قاعده مهم داوری</div><div>جمع امتیاز ماژول‌های ۹ تا ۱۴ حداکثر ۱۸ است؛ تیمی که دو یا سه ماژول را به‌خوبی اجرا کند، می‌تواند امتیاز کامل این بخش را بگیرد. <b>ارتفاع اوج فقط تا ۳ امتیاز دارد</b>؛ در ردیف ۴، ارتفاع اوج پرواز رسمی کمتر از ۵ متر ۱، ۵ تا ۱۰ متر ۲ و بیشتر از ۱۰ متر ۳ امتیاز دارد، به شرط آن‌که روش سنجش در کاربرگ ثبت پرواز آمده و با ویدئو سازگار باشد. آنچه بیشتر ارزش دارد، اجرای ایمن و هماهنگ مأموریت، بازگشت سالم محموله و نزدیکی نتیجه به پیش‌بینی است.</div></div>"}, {"t": "برنامه پیشنهادی دوره آموزشی", "n": "", "h": "<h2>برنامه پیشنهادی دوره آموزشی</h2><p>برنامه زیر برای ۱۶ جلسه ۹۰ دقیقه‌ای طراحی شده است. جلسه‌های پایه برای همه تیم‌ها و جلسه‌های ماژول برای تیم‌هایی است که ماژول‌های پیشرفته را انتخاب کرده‌اند. اگر وقت کمتری دارید، می‌توانید جلسه‌های ۱۱ تا ۱۴ را به کار تیمی آزاد تبدیل کنید تا هر تیم فقط فصل ماژول انتخابی خود را بخواند.</p><div class=\"tbl wide\"><table class=\"wt\"><tr><th style=\"width:8%\">جلسه</th><th style=\"width:9%\">فصل</th><th style=\"width:38%\">موضوع</th><th style=\"width:33%\">فعالیت عملی</th><th style=\"width:12%\">مسیر</th></tr><tr><td class=\"l\">۱</td><td class=\"l\">۱</td><td class=\"l\">یک مأموریت فضایی از آغاز تا پایان</td><td class=\"l\">تماشای ویدئوی یک پرتاب و نام‌گذاری مراحل</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۲</td><td class=\"l\">۲</td><td class=\"l\">تعریف مأموریت و مهندسی سامانه</td><td class=\"l\">تشکیل تیم، تقسیم نقش، انتخاب ماژول‌ها</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۳</td><td class=\"l\">۳</td><td class=\"l\">فیزیک پرواز موشک</td><td class=\"l\">آزمایش بادکنک-موشک روی نخ</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۴</td><td class=\"l\">۴</td><td class=\"l\">فشار، هوای فشرده و ایمنی</td><td class=\"l\">آزمون فشار بطری پر از آب پشت حفاظ</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۵</td><td class=\"l\">۵</td><td class=\"l\">پایداری پرواز؛ مرکز جرم و مرکز فشار</td><td class=\"l\">یافتن CG و CP و آزمون چرخش</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۶</td><td class=\"l\">۶</td><td class=\"l\">پیش‌بینی و اندازه‌گیری ارتفاع</td><td class=\"l\">ساخت زاویه‌سنج و اندازه‌گیری ارتفاع ساختمان</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۷</td><td class=\"l\">۷</td><td class=\"l\">ساخت پرتابگر</td><td class=\"l\">ساخت بدنه، دماغه و بالک‌ها</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۸</td><td class=\"l\">۸</td><td class=\"l\">ساخت سکوی پرتاب</td><td class=\"l\">ساخت رهاساز بست کمربندی و مسیر هوا</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۹</td><td class=\"l\">۹</td><td class=\"l\">کپسول مأموریت و محافظت از تخم‌مرغ</td><td class=\"l\">آزمون رهاسازی کپسول از ارتفاع</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۱۰</td><td class=\"l\">۱۰</td><td class=\"l\">سامانه بازیابی و چتر</td><td class=\"l\">ساخت چتر و آزمون سرعت فرود</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۱۱</td><td class=\"l\">۱۱</td><td class=\"l\">بوسترها و پرتابگر چندمرحله‌ای</td><td class=\"l\">ساخت بوستر و سکوی چهاربوستری</td><td class=\"l\">ماژول</td></tr><tr><td class=\"l\">۱۲</td><td class=\"l\">۱۲</td><td class=\"l\">سازوکارهای جداسازی</td><td class=\"l\">ساخت و آزمون سازوکار جداسازی کپسول</td><td class=\"l\">ماژول</td></tr><tr><td class=\"l\">۱۳</td><td class=\"l\">۱۳</td><td class=\"l\">ارتفاع‌سنج و مأموریت علمی کپسول</td><td class=\"l\">ثبت ارتفاع با حسگر فشار</td><td class=\"l\">ماژول</td></tr><tr><td class=\"l\">۱۴</td><td class=\"l\">۱۴</td><td class=\"l\">شبیه‌سازی و پیش‌بینی</td><td class=\"l\">ساخت برگه شبیه‌سازی صفحه‌گسترده</td><td class=\"l\">ماژول</td></tr><tr><td class=\"l\">۱۵</td><td class=\"l\">۱۵</td><td class=\"l\">آزمون‌های زمینی، روز پرتاب و ایمنی</td><td class=\"l\">تمرین روز پرتاب با فهرست بررسی</td><td class=\"l\">پایه</td></tr><tr><td class=\"l\">۱۶</td><td class=\"l\">۱۶</td><td class=\"l\">تحلیل پس از پرواز، پرونده و فیلم</td><td class=\"l\">نوشتن تحلیل یک پرواز</td><td class=\"l\">پایه</td></tr></table></div><div class=\"box tip\"><div class=\"box-t\">تجهیزات کلاس</div><div>برای دوره، یک سکوی پرتاب مشترک (یا قطعات ساخت آن)، یک پمپ دوچرخه با فشارسنج، چند بطری نوشابه گازدار ۱٫۵ لیتری سالم، عینک ایمنی، یک حفاظ (مثلاً جعبه چوبی یا پلاستیکی محکم) برای آزمون فشار، متر نواری، زمان‌سنج و نوار چسب و مقوا آماده کنید. محل پرتاب باید فضای باز بزرگی مانند زمین ورزش باشد.</div></div>"}, {"t": "یک مأموریت فضایی از آغاز تا پایان", "n": "فصل ۱", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>مراحل یک مأموریت فضایی واقعی: پرتاب، جدایش، رساندن محموله و بازگشت</li><li>چرا موشک‌ها بوستر و چند مرحله دارند</li><li>کپسول‌های بازگشتی چگونه سالم فرود می‌آیند</li><li>پرتابگر آبی شما چه شباهتی به یک مأموریت واقعی دارد</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱<br>۹۰ دقیقه</div></div>\n<p>پیش از ساختن هر چیز، باید بدانید یک مأموریت فضایی واقعی چگونه اجرا می‌شود. در این فصل یک مأموریت را از لحظه روشن شدن موتورها تا فرود کپسول دنبال می‌کنیم و می‌بینیم هر مرحله آن، در پرتابگر آبی شما چه همتایی دارد.</p><h2>سه، دو، یک، پرتاب!</h2><p>در ۴ اکتبر ۱۹۵۷، موشک R-7 شوروی نخستین ماهواره مصنوعی، اسپوتنیک ۱، را به مدار برد. نکته جالب این است که همین موشک، چهار <b>بوستر</b> جانبی داشت که دور بدنه اصلی بسته شده بودند. نوادگان همان موشک، یعنی موشک‌های «سایوز»، هنوز با همان چهار بوستر فضانوردان را به فضا می‌برند. ایران هم در ۱۴ بهمن ۱۳۸۷ با پرتابگر دومرحله‌ای «سفیر»، ماهواره «امید» را در مدار قرار داد و پس از آن پرتابگرهایی مانند «سیمرغ» را ساخت.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 320\" xmlns=\"http://www.w3.org/2000/svg\"><defs><lineargradient id=\"sk\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#cfe6fb\"></stop><stop offset=\"1\" stop-color=\"#f4f9ff\"></stop></lineargradient></defs><rect fill=\"url(#sk)\" height=\"320\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#b8d69a\" height=\"38\" width=\"690\" x=\"0\" y=\"282\"></rect><path d=\"M620,280 Q520,10 360,50\" fill=\"none\" stroke=\"#9fb0c6\" stroke-dasharray=\"6 5\" stroke-width=\"2\"></path><g transform=\"rotate(0 620 280)\"><rect fill=\"#e8f1fb\" height=\"46.8\" rx=\"4.2\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"12.1\" x=\"614.0\" y=\"225.0\"></rect><path d=\"M614.0,227.2 Q620.0,206.3 626.0,227.2 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"8.2\" width=\"4.4\" x=\"617.8\" y=\"271.8\"></rect><path d=\"M614.0,260.8 L605.2,275.6 L614.0,271.8 Z\" fill=\"#1B2A4A\"></path><path d=\"M626.0,260.8 L634.8,275.6 L626.0,271.8 Z\" fill=\"#1B2A4A\"></path></g><g transform=\"rotate(-25 555 175)\"><rect fill=\"#e8f1fb\" height=\"46.8\" rx=\"4.2\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"12.1\" x=\"549.0\" y=\"120.0\"></rect><path d=\"M549.0,122.2 Q555.0,101.3 561.0,122.2 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"8.2\" width=\"4.4\" x=\"552.8\" y=\"166.8\"></rect><path d=\"M549.0,155.8 L540.2,170.6 L549.0,166.8 Z\" fill=\"#1B2A4A\"></path><path d=\"M561.0,155.8 L569.8,170.6 L561.0,166.8 Z\" fill=\"#1B2A4A\"></path></g><g transform=\"rotate(-55 470 95)\"><rect fill=\"#e8f1fb\" height=\"46.8\" rx=\"4.2\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"12.1\" x=\"463.9\" y=\"40.0\"></rect><path d=\"M463.9,42.2 Q470.0,21.3 476.1,42.2 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"8.2\" width=\"4.4\" x=\"467.8\" y=\"86.8\"></rect><path d=\"M463.9,75.8 L455.1,90.6 L463.9,86.8 Z\" fill=\"#1B2A4A\"></path><path d=\"M476.1,75.8 L484.9,90.6 L476.1,86.8 Z\" fill=\"#1B2A4A\"></path></g><rect fill=\"#8a97ab\" height=\"34\" rx=\"3\" transform=\"rotate(-18 507 220)\" width=\"9\" x=\"507\" y=\"205\"></rect><rect fill=\"#8a97ab\" height=\"34\" rx=\"3\" transform=\"rotate(18 543 220)\" width=\"9\" x=\"543\" y=\"205\"></rect><g transform=\"rotate(-90 360 62)\"><rect fill=\"#e8f1fb\" height=\"42.5\" rx=\"3.8\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"11.0\" x=\"354.5\" y=\"12.0\"></rect><path d=\"M354.5,14.0 Q360.0,-5.0 365.5,14.0 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"7.5\" width=\"4.0\" x=\"358.0\" y=\"54.5\"></rect><path d=\"M354.5,44.5 L346.5,58.0 L354.5,54.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M365.5,44.5 L373.5,58.0 L365.5,54.5 Z\" fill=\"#1B2A4A\"></path></g><rect fill=\"#C0392B\" height=\"22\" rx=\"3\" width=\"16\" x=\"300\" y=\"72\"></rect><path d=\"M214,110 Q240,78.8 266,110 Q253.0,104 240,110 Q227.0,104 214,110 Z\" fill=\"#E0A93B\" stroke=\"#9a6b10\"></path><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"214.0\" x2=\"240.0\" y1=\"110.0\" y2=\"140.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"266.0\" x2=\"240.0\" y1=\"110.0\" y2=\"140.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"240.0\" x2=\"240.0\" y1=\"110.0\" y2=\"140.0\"></line><rect fill=\"#C0392B\" height=\"22\" rx=\"3\" width=\"16\" x=\"232\" y=\"140\"></rect><path d=\"M80,215 Q110,179.0 140,215 Q125.0,209 110,215 Q95.0,209 80,215 Z\" fill=\"#E0A93B\" stroke=\"#9a6b10\"></path><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"80.0\" x2=\"110.0\" y1=\"215.0\" y2=\"248.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"140.0\" x2=\"110.0\" y1=\"215.0\" y2=\"248.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"110.0\" x2=\"110.0\" y1=\"215.0\" y2=\"248.0\"></line><rect fill=\"#C0392B\" height=\"26\" rx=\"3\" width=\"18\" x=\"101\" y=\"248\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"620\" y=\"305\">۱. پرتاب</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"545\" y=\"252\">۲. جدایش بوسترها</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"470\" y=\"128\">۳. پرواز آزاد</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"360\" y=\"30\">۴. اوج و جدایش کپسول</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"240\" y=\"185\">۵. باز شدن چتر</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"110\" y=\"305\">۶. فرود و بازیابی</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"11\" font-weight=\"normal\" text-anchor=\"middle\" x=\"345\" y=\"140\">مراحل پیشرفته (اختیاری): ۲ و جدایش در ۴</text></svg><figcaption>شکل ۱-۱: مراحل مأموریت پرتابگر آبی؛ همانند یک مأموریت فضایی واقعی.</figcaption></figure><h2>مراحل یک مأموریت فضایی</h2><ol class=\"steps\"><li><span class=\"sn\">۱</span><div><b>پرتاب:</b> موتورها روشن می‌شوند و نیروی رانش، موشک را از سکو جدا می‌کند. موشک باید پایدار و راست بالا برود.</div></li><li><span class=\"sn\">۲</span><div><b>جدایش بوسترها:</b> بوسترهای جانبی که سوختشان زودتر تمام می‌شود، جدا می‌شوند تا موشک وزن اضافه حمل نکند.</div></li><li><span class=\"sn\">۳</span><div><b>جدایش مراحل:</b> مرحله اول پس از تمام شدن سوخت جدا می‌شود و موتور مرحله بعد روشن می‌شود.</div></li><li><span class=\"sn\">۴</span><div><b>جدا شدن پوشش دماغه:</b> وقتی موشک از جو غلیظ بیرون رفت، پوشش محافظ دماغه دو نیم می‌شود و کنار می‌رود.</div></li><li><span class=\"sn\">۵</span><div><b>رساندن محموله:</b> ماهواره یا فضاپیما در مدار یا مسیر موردنظر رها می‌شود.</div></li><li><span class=\"sn\">۶</span><div><b>انجام مأموریت و ارسال داده:</b> محموله اندازه‌گیری‌ها را انجام می‌دهد و داده‌ها را به ایستگاه زمینی می‌فرستد.</div></li><li><span class=\"sn\">۷</span><div><b>بازگشت و فرود:</b> در مأموریت‌های سرنشین‌دار یا نمونه‌برداری، کپسول به جو بازمی‌گردد و با چتر آرام فرود می‌آید.</div></li></ol><h2>چرا بوستر و چند مرحله؟</h2><p>موشک باید سوخت خود را هم با خود ببرد. هرچه سوخت بیشتر، موشک سنگین‌تر و هرچه سنگین‌تر، سوخت بیشتری لازم است! راه‌حل مهندسان این است: <b>وزن اضافه را در طول مسیر دور بریز</b>. وقتی سوخت یک مخزن تمام شد، مخزن خالی و موتورش فقط وزن مرده‌اند؛ پس جدا می‌شوند تا بقیه موشک سبک‌تر شود و با همان سوخت باقی‌مانده، سرعت بیشتری بگیرد.</p><div class=\"tbl\"><table class=\"kv\"><tr><td>بوستر</td><td>موتور یا مخزنی که در کنار بدنه اصلی بسته می‌شود و هم‌زمان با آن روشن می‌شود تا در لحظه‌های اول، که موشک از همه وقت سنگین‌تر است، رانش بیشتری بدهد.</td></tr><tr><td>مرحله</td><td>بخشی از موشک که روی بخش دیگر قرار گرفته است. مراحل به ترتیب، یکی پس از دیگری کار می‌کنند.</td></tr></table></div><div class=\"box why\"><div class=\"box-t\">برای کنجکاوها: بوسترهایی که برمی‌گردند</div><div>در سال ۲۰۱۸، دو بوستر جانبی موشک «فالکون هوی» پس از جدایش، به زمین بازگشتند و هم‌زمان کنار هم روی سکو نشستند. در موشک سایوز، چهار بوستر هنگام جدایش به شکل یک صلیب از هم باز می‌شوند. موشک اروپایی «آریان ۶» هم بسته به وزن محموله، با دو یا چهار بوستر پرواز می‌کند.</div></div><h2>بازگشت سالم</h2><p>کپسول بازگشتی با سرعتی چند برابر گلوله وارد جو می‌شود. سپر حرارتی آن را از گرمای اصطکاک هوا محافظت می‌کند و جو سرعتش را کم می‌کند. سپس چترها باز می‌شوند. کپسول سایوز با چتر اصلی به سرعت حدود ۶ تا ۷ متر بر ثانیه می‌رسد و درست پیش از برخورد با زمین، موتورهای کوچکی روشن می‌شوند تا سرعت را به حدود ۱٫۵ متر بر ثانیه برسانند. صندلی فضانوردان هم ضربه‌گیر دارد. یعنی برای سالم ماندن سرنشینان، <b>چند لایه محافظت</b> طراحی شده است؛ همان کاری که شما برای تخم‌مرغ انجام می‌دهید.</p><h2>پرتابگر آبی: یک مأموریت فضایی کوچک</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"250\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#f0f4fa\" height=\"160\" rx=\"6\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"28\" x=\"136\" y=\"40\"></rect><path d=\"M136,44 Q150,0 164,44 Z\" fill=\"#dfe6f0\" stroke=\"#1B2A4A\"></path><rect fill=\"#f0f4fa\" height=\"90\" rx=\"5\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"18\" x=\"115\" y=\"110\"></rect><path d=\"M115,112 Q124,88 133,112 Z\" fill=\"#dfe6f0\" stroke=\"#1B2A4A\"></path><rect fill=\"#f0f4fa\" height=\"90\" rx=\"5\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"18\" x=\"167\" y=\"110\"></rect><path d=\"M167,112 Q176,88 185,112 Z\" fill=\"#dfe6f0\" stroke=\"#1B2A4A\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"150\" y=\"230\">پرتابگر واقعی با چهار بوستر</text><g transform=\"rotate(0 520 205)\"><rect fill=\"#e8f1fb\" height=\"110.5\" rx=\"10.0\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"28.6\" x=\"505.7\" y=\"75.0\"></rect><path d=\"M505.7,80.2 Q520.0,30.8 534.3,80.2 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"19.5\" width=\"10.4\" x=\"514.8\" y=\"185.5\"></rect><path d=\"M505.7,159.5 L484.9,194.6 L505.7,185.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M534.3,159.5 L555.1,194.6 L534.3,185.5 Z\" fill=\"#1B2A4A\"></path></g><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"230\">پرتابگر آبی</text><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"70\">هر دو با قانون سوم نیوتن پرواز می‌کنند</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"middle\" x=\"345\" y=\"95\">گاز داغ ⟵ پیشران ⟶ آب</text></svg><figcaption>شکل ۱-۲: پرتابگر واقعی و پرتابگر آبی.</figcaption></figure><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:34%\">مأموریت واقعی</th><th style=\"width:66%\">مأموریت شما</th></tr><tr><td class=\"l\">موتور و سوخت</td><td class=\"l\">آب و هوای فشرده درون بطری</td></tr><tr><td class=\"l\">سکوی پرتاب و برج کنترل</td><td class=\"l\">سکوی پرتاب با فشارسنج، ضامن ایمنی و رهاساز از راه دور</td></tr><tr><td class=\"l\">بوسترهای جانبی</td><td class=\"l\">دو تا چهار بطری جانبی (ماژول انتخابی)</td></tr><tr><td class=\"l\">جدایش مراحل و بوسترها</td><td class=\"l\">جدا شدن بوسترها یا مرحله اول در پرواز (ماژول انتخابی)</td></tr><tr><td class=\"l\">ماهواره یا فضاپیما</td><td class=\"l\">کپسول مأموریت با تخم‌مرغ و تجهیزات</td></tr><tr><td class=\"l\">ارسال داده به زمین</td><td class=\"l\">ارتفاع‌سنج و حسگرهای علمی (ماژول انتخابی)</td></tr><tr><td class=\"l\">چترهای کپسول بازگشتی</td><td class=\"l\">چتر نجات، نوار کندکننده یا سازه جاذب انرژی</td></tr><tr><td class=\"l\">سرنشین</td><td class=\"l\">تخم‌مرغ خام!</td></tr><tr><td class=\"l\">تحلیل پس از پرواز</td><td class=\"l\">مقایسه پیش‌بینی با نتیجه در پرونده مأموریت</td></tr></table></div><h2>کن‌ست: ماهواره‌ای به اندازه قوطی نوشابه</h2><p>بخش علمی کپسول در این گرایش از مسابقه بین‌المللی <b>کن‌ست</b> (CanSat) آژانس فضایی اروپا الهام گرفته است. در کن‌ست، دانش‌آموزان یک ماهواره کوچک به اندازه قوطی نوشابه می‌سازند که با موشک به ارتفاع حدود یک کیلومتر برده می‌شود و پس از جدا شدن، در حین فرود با چتر، داده‌های علمی مانند دما و فشار را اندازه می‌گیرد و به ایستگاه زمینی می‌فرستد. در فصل ۱۳ با این ماژول آشنا می‌شوید.</p><div class=\"box out\"><div class=\"box-t\">پیوند با شیوه‌نامه</div><div>در این گرایش، معیار موفقیت بیشترین ارتفاع نیست؛ اجرای ایمن و هماهنگ مأموریت و بازگشت سالم محموله است.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>مأموریت فضایی مراحل پرتاب، جدایش، رساندن محموله، ارسال داده و بازگشت را دارد.</li><li>بوسترها و مراحل، با دور ریختن وزن مرده، موشک را کارآمدتر می‌کنند.</li><li>کپسول‌های بازگشتی با چند لایه محافظت (چتر، موتور فرود، ضربه‌گیر) سالم فرود می‌آیند.</li><li>هر مرحله مأموریت پرتابگر آبی، همتایی در مأموریت‌های واقعی دارد.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>هفت مرحله یک مأموریت فضایی را به ترتیب نام ببرید.</li><li>با زبان خودتان توضیح دهید چرا موشک‌ها مخزن‌های خالی را دور می‌اندازند.</li><li>تفاوت «بوستر» و «مرحله» چیست؟</li><li>کپسول سایوز از چند راه سرنشینان را در فرود محافظت می‌کند؟</li><li>در مأموریت شما، تخم‌مرغ نقش چه چیزی را دارد؟ چرا تخم‌مرغ خام انتخاب شده است؟</li><li>چرا در این گرایش، ارتفاع اوج فقط تا ۳ امتیاز دارد و رقابت ارتفاع هدف نیست؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>ویدئوی یک پرتاب واقعی (مثلاً سایوز یا فالکون هوی) را با تیم تماشا کنید و زمان هر مرحله (پرتاب، جدایش بوسترها، جدایش مرحله، جدا شدن پوشش دماغه) را یادداشت کنید.</div></div>"}, {"t": "تعریف مأموریت و مهندسی سامانه", "n": "فصل ۲", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>نوشتن هدف، الزامات و معیارهای موفقیت مأموریت</li><li>معماری سامانه و زیرسامانه‌های پرتابگر آبی</li><li>انتخاب ماژول‌های تکمیلی بر پایه توان و زمان تیم</li><li>نقش‌های تیم و پرونده مأموریت</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۲<br>۹۰ دقیقه<br>معیار داوری ۱ (۷ امتیاز)</div></div>\n<p>مهندسان ناسا و آژانس‌های فضایی پیش از ساختن یک پیچ، ماه‌ها درباره این فکر می‌کنند که «دقیقاً چه می‌خواهیم و چگونه می‌فهمیم موفق شده‌ایم». این کار را <b>تعریف مأموریت</b> می‌گویند و نخستین بخش پرونده مأموریت شماست.</p><h2>سه جزء تعریف مأموریت</h2><div class=\"tbl\"><table class=\"kv\"><tr><td>هدف</td><td>یک یا دو جمله که می‌گوید مأموریت چه می‌خواهد انجام دهد. نمونه: «رساندن یک تخم‌مرغ خام به ارتفاع حدود ۲۵ متر با پرتابگر آبی دارای دو بوستر و بازگرداندن سالم آن با چتر.»</td></tr><tr><td>الزامات</td><td>جمله‌هایی که می‌گویند سامانه «باید» چه ویژگی‌ای داشته باشد. هر الزام باید قابل بررسی باشد. نمونه: «فشار پرتاب باید کمتر از ۵ بار باشد»؛ «سرعت فرود کپسول باید بین ۳ و ۶ متر بر ثانیه باشد».</td></tr><tr><td>معیارهای موفقیت</td><td>نتیجه‌های عددی یا قابل مشاهده‌ای که نشان می‌دهند مأموریت موفق بوده است. نمونه: «تخم‌مرغ سالم بماند»؛ «چتر پیش از رسیدن کپسول به نیمه راه فرود باز شود»؛ «ارتفاع ثبت‌شده با پیش‌بینی کمتر از ۲۰ درصد اختلاف داشته باشد».</td></tr></table></div><div class=\"box tip\"><div class=\"box-t\">معیار موفقیت چندسطحی</div><div>مهندسان فضا معیارها را سطح‌بندی می‌کنند: <b>حداقل موفقیت</b> (مثلاً «تخم‌مرغ سالم بماند») و <b>موفقیت کامل</b> (مثلاً «همه ماژول‌ها درست کار کنند»). این کار به شما کمک می‌کند حتی اگر یک ماژول کار نکرد، بتوانید درباره موفقیت بخش‌های دیگر دقیق گزارش دهید.</div></div><h2>مهندسی سامانه و معماری</h2><p>پرتابگر شما مجموعه‌ای از <b>زیرسامانه‌ها</b>ست که باید با هم کار کنند. بهترین چتر دنیا اگر در لحظه درست باز نشود، بی‌فایده است. <b>مهندسی سامانه</b> یعنی نگاه به کل مأموریت و اطمینان از اینکه همه بخش‌ها با هم هماهنگ‌اند.</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:24%\">زیرسامانه</th><th style=\"width:46%\">وظیفه</th><th style=\"width:30%\">فصل</th></tr><tr><td class=\"l\">پرتابگر (بدنه، دماغه، بالک)</td><td class=\"l\">تولید رانش و پرواز پایدار</td><td class=\"l\">فصل‌های ۳ تا ۵ و ۷</td></tr><tr><td class=\"l\">سکوی پرتاب</td><td class=\"l\">نگه‌داشتن، پر کردن هوا و رهاسازی ایمن</td><td class=\"l\">فصل ۸</td></tr><tr><td class=\"l\">کپسول مأموریت</td><td class=\"l\">حمل و محافظت از محموله و تجهیزات</td><td class=\"l\">فصل ۹</td></tr><tr><td class=\"l\">سامانه بازیابی</td><td class=\"l\">کاهش سرعت فرود</td><td class=\"l\">فصل ۱۰</td></tr><tr><td class=\"l\">سنجش عملکرد</td><td class=\"l\">برآورد ارتفاع و زمان پرواز</td><td class=\"l\">فصل ۶</td></tr><tr><td class=\"l\">ماژول‌های تکمیلی</td><td class=\"l\">بوستر، جداسازی، ارتفاع‌سنج، کن‌ست، شبیه‌سازی</td><td class=\"l\">فصل‌های ۱۱ تا ۱۴</td></tr></table></div><p>یک <b>نمودار معماری</b> ساده بکشید که هر زیرسامانه در آن یک جعبه باشد و نشان دهد چه چیزی به چه چیزی وصل است؛ مثلاً «سازوکار جداسازی ← در کپسول ← چتر».</p><h2>انتخاب ماژول‌ها</h2><p>ساخت بوستر به همه تیم‌ها توصیه می‌شود؛ اما نبود هیچ‌یک از ماژول‌ها مانع شرکت در این گرایش نیست. جدول زیر به شما کمک می‌کند با توجه به امکانات و زمان، ماژول‌ها را انتخاب کنید:</p><div class=\"tbl wide\"><table class=\"wt\"><tr><th style=\"width:24%\">ماژول</th><th style=\"width:9%\">امتیاز</th><th style=\"width:14%\">دشواری</th><th style=\"width:30%\">نیاز ویژه</th><th style=\"width:23%\">پیشنهاد</th></tr><tr><td class=\"l\">بوستر</td><td class=\"l\">۷</td><td class=\"l\">متوسط</td><td class=\"l\">سکوی چندتایی و رهاساز هم‌زمان</td><td class=\"l\">به همه تیم‌ها</td></tr><tr><td class=\"l\">جداسازی بوسترها یا مراحل</td><td class=\"l\">۵</td><td class=\"l\">زیاد</td><td class=\"l\">بوستر؛ طراحی اتصال</td><td class=\"l\">پس از بوستر</td></tr><tr><td class=\"l\">جداسازی کپسول</td><td class=\"l\">۶</td><td class=\"l\">متوسط</td><td class=\"l\">سازوکار مکانیکی یا الکترونیکی</td><td class=\"l\">بسیار مناسب</td></tr><tr><td class=\"l\">سنجش ارتفاع</td><td class=\"l\">۴</td><td class=\"l\">کم تا متوسط</td><td class=\"l\">حسگر فشار و میکروکنترلر</td><td class=\"l\">دوره دوم یا آشنا با آردوینو</td></tr><tr><td class=\"l\">مأموریت علمی کپسول</td><td class=\"l\">۴</td><td class=\"l\">متوسط</td><td class=\"l\">حسگرها و ثبت داده</td><td class=\"l\">همراه با سنجش ارتفاع</td></tr><tr><td class=\"l\">شبیه‌سازی</td><td class=\"l\">۳</td><td class=\"l\">کم تا متوسط</td><td class=\"l\">صفحه‌گسترده یا نرم‌افزار</td><td class=\"l\">دوره دوم</td></tr></table></div><div class=\"box out\"><div class=\"box-t\">پیوند با داوری</div><div>جمع امتیاز ماژول‌ها حداکثر ۱۸ است. دو یا سه ماژول را خوب اجرا کنید؛ بهتر از این است که پنج ماژول را نیمه‌کاره رها کنید. سادگی و قابلیت اطمینان، به اندازه پیچیدگی ارزشمند است.</div></div><h2>بودجه جرم</h2><p>جرم همه اجزا را در یک جدول بنویسید و با ترازوی آشپزخانه بسنجید. جرم بر ارتفاع، پایداری و اندازه چتر اثر دارد و در محاسبه‌های فصل‌های بعد به کارتان می‌آید.</p><div class=\"ex\"><div class=\"ex-t\">نمونه بودجه جرم</div><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:60%\">جزء</th><th style=\"width:40%\">جرم (گرم)</th></tr><tr><td class=\"l\">بطری ۱٫۵ لیتری خالی</td><td class=\"l\">۴۵</td></tr><tr><td class=\"l\">بالک‌ها (سه عدد)</td><td class=\"l\">۳۰</td></tr><tr><td class=\"l\">دماغه نرم</td><td class=\"l\">۲۰</td></tr><tr><td class=\"l\">کپسول (بدنه و ضربه‌گیر)</td><td class=\"l\">۶۰</td></tr><tr><td class=\"l\">تخم‌مرغ</td><td class=\"l\">۶۰</td></tr><tr><td class=\"l\">چتر و نخ‌ها</td><td class=\"l\">۱۵</td></tr><tr><td class=\"l\"><b>جمع (بدون آب)</b></td><td class=\"l\"><b>۲۳۰</b></td></tr></table></div></div><h2>نقش‌های تیم</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:26%\">نقش</th><th style=\"width:74%\">مسئولیت</th></tr><tr><td class=\"l\">مدیر مأموریت</td><td class=\"l\">برنامه زمانی، هماهنگی، شمارش معکوس روز پرتاب، پرونده مأموریت</td></tr><tr><td class=\"l\">مهندس پرتابگر و سکو</td><td class=\"l\">بدنه، بالک‌ها، پایداری، سکوی پرتاب و ایمنی فشار</td></tr><tr><td class=\"l\">مهندس کپسول و بازیابی</td><td class=\"l\">کپسول، ضربه‌گیر، چتر و سازوکار جداسازی؛ داده و حسگرها</td></tr></table></div><p class=\"hint\">در تیم دونفره، هر عضو بیش از یک نقش دارد. همه اعضا باید بر کل مأموریت مسلط باشند؛ داوران در مصاحبه از هر عضو درباره هر بخش می‌پرسند.</p><h2>پرونده مأموریت</h2><p>از همین امروز پرونده مأموریت را آغاز کنید. این پرونده (حداکثر ۲۰ صفحه) پنج بخش دارد: تعریف مأموریت، طراحی، آزمون‌های زمینی، پروازها و تحلیل پس از پرواز. هر تصمیم، آزمون و اصلاح را با تاریخ و عکس یادداشت کنید.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 170\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"170\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><circle cx=\"640\" cy=\"60\" fill=\"#1B2A4A\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"640\" y=\"68\">۱</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"640\" y=\"112\">تعریف مأموریت</text><line stroke=\"#2A9DAE\" stroke-dasharray=\"4 3\" stroke-width=\"2\" x1=\"612.0\" x2=\"570.0\" y1=\"60.0\" y2=\"60.0\"></line><circle cx=\"542\" cy=\"60\" fill=\"#1B2A4A\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"542\" y=\"68\">۲</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"542\" y=\"112\">طراحی و محاسبه</text><line stroke=\"#2A9DAE\" stroke-dasharray=\"4 3\" stroke-width=\"2\" x1=\"514.0\" x2=\"472.0\" y1=\"60.0\" y2=\"60.0\"></line><circle cx=\"444\" cy=\"60\" fill=\"#1B2A4A\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"444\" y=\"68\">۳</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"444\" y=\"112\">ساخت</text><line stroke=\"#2A9DAE\" stroke-dasharray=\"4 3\" stroke-width=\"2\" x1=\"416.0\" x2=\"374.0\" y1=\"60.0\" y2=\"60.0\"></line><circle cx=\"346\" cy=\"60\" fill=\"#1B2A4A\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"346\" y=\"68\">۴</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"346\" y=\"112\">آزمون زمینی</text><line stroke=\"#2A9DAE\" stroke-dasharray=\"4 3\" stroke-width=\"2\" x1=\"318.0\" x2=\"276.0\" y1=\"60.0\" y2=\"60.0\"></line><circle cx=\"248\" cy=\"60\" fill=\"#1B2A4A\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"248\" y=\"68\">۵</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"248\" y=\"112\">پرواز آزمایشی</text><line stroke=\"#2A9DAE\" stroke-dasharray=\"4 3\" stroke-width=\"2\" x1=\"220.0\" x2=\"178.0\" y1=\"60.0\" y2=\"60.0\"></line><circle cx=\"150\" cy=\"60\" fill=\"#C0392B\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"150\" y=\"68\">۶</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"150\" y=\"112\">پرواز رسمی</text><line stroke=\"#2A9DAE\" stroke-dasharray=\"4 3\" stroke-width=\"2\" x1=\"122.0\" x2=\"80.0\" y1=\"60.0\" y2=\"60.0\"></line><circle cx=\"52\" cy=\"60\" fill=\"#1B2A4A\" r=\"26\" stroke=\"#E0A93B\" stroke-width=\"3\"></circle><text fill=\"#fff\" font-family=\"Vazirmatn\" font-size=\"18\" font-weight=\"bold\" text-anchor=\"middle\" x=\"52\" y=\"68\">۷</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"52\" y=\"112\">تحلیل</text><path d=\"M100,130 Q345,165 590,130\" fill=\"none\" stroke=\"#2A9DAE\" stroke-dasharray=\"5 4\" stroke-width=\"2\"></path><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"normal\" text-anchor=\"middle\" x=\"345\" y=\"160\">بازگشت و بهبود پس از هر آزمون</text></svg><figcaption>شکل ۲-۱: مسیر مهندسی مأموریت؛ پس از هر آزمون، بازگشت و بهبود.</figcaption></figure><div class=\"ws-h\">کاربرگ ۲-۱: تعریف مأموریت تیم ما</div><div class=\"tbl\"><table class=\"wh\"><tr><td>نام تیم و دوره تحصیلی:</td><td>اعضا و نقش‌ها:</td></tr><tr><td colspan=\"2\" style=\"height:14mm\">هدف مأموریت:</td></tr><tr><td colspan=\"2\" style=\"height:14mm\">ماژول‌های انتخابی و دلیل انتخاب:</td></tr><tr><td colspan=\"2\" style=\"height:22mm\">الزامات (دست‌کم ۵ الزام قابل بررسی):</td></tr><tr><td colspan=\"2\" style=\"height:18mm\">معیارهای موفقیت (حداقل و کامل):</td></tr></table></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>تعریف مأموریت سه جزء دارد: هدف، الزامات و معیارهای موفقیت.</li><li>پرتابگر از زیرسامانه‌هایی ساخته شده که باید با هم هماهنگ باشند.</li><li>ماژول‌ها را بر پایه توان و زمان تیم انتخاب کنید؛ دو یا سه ماژول خوب کافی است.</li><li>بودجه جرم و پرونده مأموریت را از روز اول آغاز کنید.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>تفاوت «هدف» و «معیار موفقیت» را با یک مثال توضیح دهید.</li><li>کدام یک الزام قابل بررسی است؟ الف) «پرتابگر باید خوب پرواز کند.» ب) «پرتابگر باید در پرواز کمتر از ۱۵ درجه از راستای قائم منحرف شود.»</li><li>برای سامانه بازیابی دو الزام و برای کپسول دو الزام بنویسید.</li><li>چرا معیار موفقیت را سطح‌بندی می‌کنیم؟</li><li>تیمی فقط ۶ هفته وقت دارد و آشنایی با آردوینو ندارد. چه ماژول‌هایی را پیشنهاد می‌کنید؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>کاربرگ ۲-۱ را کامل کنید، نقش‌ها را تقسیم کنید و نمودار معماری و جدول بودجه جرم اولیه را بکشید. این‌ها نخستین صفحه‌های پرونده مأموریت شما هستند.</div></div>"}, {"t": "فیزیک پرواز موشک", "n": "فصل ۳", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>نیرو، جرم، وزن و قانون‌های نیوتن</li><li>رانش: چرا آب پرتابگر را به بالا می‌راند</li><li>مراحل پرواز: پیشرانش، پرواز آزاد، اوج و فرود</li><li>نیروی پسا و اثر آن</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۳<br>۹۰ دقیقه<br>بخشی از معیار ۲</div></div>\n<p>چرا موشک بالا می‌رود؟ چرا پس از چند ثانیه می‌ایستد و برمی‌گردد؟ پاسخ این پرسش‌ها در سه قانون ساده نهفته است که آیزاک نیوتن بیش از ۳۰۰ سال پیش نوشت. با این قانون‌ها می‌توانید پرواز پرتابگرتان را درک و پیش‌بینی کنید.</p><h2>نیرو، جرم و وزن</h2><div class=\"tbl\"><table class=\"kv\"><tr><td>جرم</td><td>مقدار ماده یک جسم؛ با کیلوگرم یا گرم سنجیده می‌شود و هر جا بروید، ثابت است.</td></tr><tr><td>نیرو</td><td>هل دادن یا کشیدن؛ با <b>نیوتن</b> (N) سنجیده می‌شود.</td></tr><tr><td>وزن</td><td>نیرویی که زمین با آن جسم را به سوی خود می‌کشد: وزن = جرم × g. g شتاب گرانش و حدود ۹٫۸ متر بر مجذور ثانیه است. پرتابگری به جرم ۰٫۲ کیلوگرم، وزنی حدود ۲ نیوتن دارد.</td></tr></table></div><h2>سه قانون نیوتن</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:18%\">قانون</th><th style=\"width:42%\">بیان ساده</th><th style=\"width:40%\">در پرتابگر آبی</th></tr><tr><td class=\"l\">اول (لختی)</td><td class=\"l\">جسم ساکن، ساکن می‌ماند و جسم متحرک به حرکت ادامه می‌دهد، مگر نیرویی بر آن اثر کند.</td><td class=\"l\">پس از تمام شدن آب، پرتابگر به دلیل لختی تا اوج بالا می‌رود.</td></tr><tr><td class=\"l\">دوم</td><td class=\"l\">شتاب = نیروی کل ÷ جرم؛ نیروی بیشتر شتاب بیشتر و جرم بیشتر شتاب کمتر.</td><td class=\"l\">پرتابگر سبک‌تر با همان رانش شتاب بیشتری می‌گیرد.</td></tr><tr><td class=\"l\">سوم (کنش و واکنش)</td><td class=\"l\">هر کنشی، واکنشی برابر و در خلاف جهت دارد.</td><td class=\"l\">پرتابگر آب را به پایین می‌راند و آب پرتابگر را به بالا.</td></tr></table></div><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 250\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"ra\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#C0392B\"></path></marker></defs><defs><marker id=\"rt\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#2A9DAE\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"250\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><g transform=\"rotate(0 345 150)\"><rect fill=\"#e8f1fb\" height=\"102.0\" rx=\"9.2\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"26.4\" x=\"331.8\" y=\"30.0\"></rect><path d=\"M331.8,34.8 Q345.0,-10.8 358.2,34.8 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"18.0\" width=\"9.6\" x=\"340.2\" y=\"132.0\"></rect><path d=\"M331.8,108.0 L312.6,140.4 L331.8,132.0 Z\" fill=\"#1B2A4A\"></path><path d=\"M358.2,108.0 L377.4,140.4 L358.2,132.0 Z\" fill=\"#1B2A4A\"></path></g><circle cx=\"351.9\" cy=\"160.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"4.0\"></circle><circle cx=\"337.7\" cy=\"169.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"4.3\"></circle><circle cx=\"354.1\" cy=\"178.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"4.6\"></circle><circle cx=\"339.8\" cy=\"187.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"4.9\"></circle><circle cx=\"339.7\" cy=\"196.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"5.2\"></circle><circle cx=\"347.5\" cy=\"205.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"5.5\"></circle><circle cx=\"350.9\" cy=\"214.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"5.8\"></circle><circle cx=\"341.5\" cy=\"223.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"6.1\"></circle><circle cx=\"339.5\" cy=\"232.0\" fill=\"#5fb3e6\" opacity=\"0.80\" r=\"6.4\"></circle><line marker-end=\"url(#rt)\" stroke=\"#2A9DAE\" stroke-width=\"4\" x1=\"345.0\" x2=\"345.0\" y1=\"45.0\" y2=\"18\"></line><line marker-end=\"url(#ra)\" stroke=\"#C0392B\" stroke-width=\"4\" x1=\"395.0\" x2=\"395.0\" y1=\"160.0\" y2=\"235.0\"></line><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"405\" y=\"205\">آب با فشار به پایین رانده می‌شود (کنش)</text><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"330\" y=\"40\">پرتابگر به بالا رانده می‌شود (واکنش)</text></svg><figcaption>شکل ۳-۱: کنش و واکنش در پرتابگر آبی.</figcaption></figure><h2>رانش: چرا آب؟</h2><p>هوای فشرده درون بطری، آب را با سرعت زیاد از دهانه بطری (<b>نازل</b>) بیرون می‌راند. طبق قانون سوم، آب هم بطری را با نیرویی به همان اندازه به بالا هل می‌دهد؛ به این نیرو <b>رانش</b> می‌گویند. چرا آب و نه فقط هوا؟ چون آب حدود ۸۰۰ برابر هوا چگال‌تر است. رانش به «جرمی که در هر ثانیه بیرون رانده می‌شود» و «سرعت آن» بستگی دارد؛ آب جرم بسیار بیشتری را در زمان کوتاه بیرون می‌راند و رانش بسیار بیشتری می‌دهد. بطری‌ای که فقط هوا دارد، فقط چند متر بالا می‌رود.</p><div class=\"box tip\"><div class=\"box-t\">آزمایش بادکنک-موشک</div><div>یک نخ را میان دو صندلی محکم ببندید و یک نی از آن رد کنید. بادکنکی باد کرده را (بدون گره زدن) با چسب به نی بچسبانید و رها کنید. بادکنک هوا را به عقب می‌راند و خودش به جلو می‌رود. سپس دو بادکنک را با هم بچسبانید (مانند بوستر) و نتیجه را مقایسه کنید.</div></div><h2>مراحل پرواز</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 260\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"f1\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#2A9DAE\"></path></marker></defs><defs><marker id=\"f2\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#C0392B\"></path></marker></defs><defs><marker id=\"f3\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#E0A93B\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"260\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><g transform=\"rotate(0 560 175)\"><rect fill=\"#e8f1fb\" height=\"76.5\" rx=\"6.9\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"19.8\" x=\"550.1\" y=\"85.0\"></rect><path d=\"M550.1,88.6 Q560.0,54.4 569.9,88.6 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"13.5\" width=\"7.2\" x=\"556.4\" y=\"161.5\"></rect><path d=\"M550.1,143.5 L535.7,167.8 L550.1,161.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M569.9,143.5 L584.3,167.8 L569.9,161.5 Z\" fill=\"#1B2A4A\"></path></g><line marker-end=\"url(#f2)\" stroke=\"#C0392B\" stroke-width=\"3\" x1=\"592.0\" x2=\"592.0\" y1=\"120.0\" y2=\"200.0\"></line><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"600\" y=\"185\">وزن</text><line marker-end=\"url(#f1)\" stroke=\"#2A9DAE\" stroke-width=\"4\" x1=\"528.0\" x2=\"528.0\" y1=\"150.0\" y2=\"60.0\"></line><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"520\" y=\"80\">رانش</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"560\" y=\"245\">سوختن پیشران</text><g transform=\"rotate(0 350 175)\"><rect fill=\"#e8f1fb\" height=\"76.5\" rx=\"6.9\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"19.8\" x=\"340.1\" y=\"85.0\"></rect><path d=\"M340.1,88.6 Q350.0,54.4 359.9,88.6 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"13.5\" width=\"7.2\" x=\"346.4\" y=\"161.5\"></rect><path d=\"M340.1,143.5 L325.7,167.8 L340.1,161.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M359.9,143.5 L374.3,167.8 L359.9,161.5 Z\" fill=\"#1B2A4A\"></path></g><line marker-end=\"url(#f2)\" stroke=\"#C0392B\" stroke-width=\"3\" x1=\"382.0\" x2=\"382.0\" y1=\"120.0\" y2=\"200.0\"></line><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"390\" y=\"185\">وزن</text><line marker-end=\"url(#f3)\" stroke=\"#E0A93B\" stroke-width=\"3\" x1=\"318.0\" x2=\"318.0\" y1=\"70.0\" y2=\"130.0\"></line><text fill=\"#9a6b10\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"310\" y=\"115\">پسا</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"350\" y=\"245\">پرواز آزاد</text><path d=\"M106,80 Q140,39.2 174,80 Q157.0,74 140,80 Q123.0,74 106,80 Z\" fill=\"#E0A93B\" stroke=\"#9a6b10\"></path><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"106.0\" x2=\"140.0\" y1=\"80.0\" y2=\"130.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"174.0\" x2=\"140.0\" y1=\"80.0\" y2=\"130.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1\" x1=\"140.0\" x2=\"140.0\" y1=\"80.0\" y2=\"130.0\"></line><rect fill=\"#C0392B\" height=\"30\" rx=\"4\" width=\"22\" x=\"129\" y=\"130\"></rect><line marker-end=\"url(#f2)\" stroke=\"#C0392B\" stroke-width=\"3\" x1=\"172.0\" x2=\"172.0\" y1=\"120.0\" y2=\"200.0\"></line><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"180\" y=\"185\">وزن</text><line marker-end=\"url(#f3)\" stroke=\"#E0A93B\" stroke-width=\"4\" x1=\"100.0\" x2=\"100.0\" y1=\"160.0\" y2=\"100.0\"></line><text fill=\"#9a6b10\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"92\" y=\"120\">پسا</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"140\" y=\"245\">فرود با چتر</text></svg><figcaption>شکل ۳-۲: نیروهای وارد بر پرتابگر در سه مرحله پرواز.</figcaption></figure><ol class=\"steps\"><li><span class=\"sn\">۱</span><div><b>پیشرانش (کمتر از نیم ثانیه):</b> آب با فشار بیرون می‌رود و رانش، بسیار بیشتر از وزن است. پرتابگر شتاب زیادی می‌گیرد. پس از آب، هوای باقی‌مانده هم با یک «فوت» کوتاه کمی رانش می‌دهد.</div></li><li><span class=\"sn\">۲</span><div><b>پرواز آزاد:</b> رانش تمام شده است. وزن و نیروی مقاومت هوا (پسا) پرتابگر را کند می‌کنند، اما لختی آن را بالا می‌برد.</div></li><li><span class=\"sn\">۳</span><div><b>اوج:</b> لحظه‌ای که سرعت عمودی صفر می‌شود و پرتابگر بالاترین ارتفاع را دارد. بهترین لحظه برای جدا شدن کپسول یا باز شدن چتر.</div></li><li><span class=\"sn\">۴</span><div><b>فرود:</b> پرتابگر به سوی زمین برمی‌گردد. بدون چتر، سرعتش زیاد و برخوردش ویرانگر است؛ با چتر، پسا با وزن برابر می‌شود و سرعت ثابت و کم می‌ماند.</div></li></ol><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 640 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#fff\" height=\"270\" rx=\"10\" stroke=\"#d9e2ee\" width=\"640\"></rect><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"225.0\" y2=\"225.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"229.0\">0</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"156.7\" y2=\"156.7\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"160.7\">10</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"88.3\" y2=\"88.3\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"92.3\">20</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"20.0\" y2=\"20.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"24.0\">30</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"70.0\" y=\"241\">0</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"161.7\" y=\"241\">1</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"253.3\" y=\"241\">2</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"345.0\" y=\"241\">3</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"436.7\" y=\"241\">4</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"528.3\" y=\"241\">5</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"620.0\" y=\"241\">6</text><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"620\" y1=\"225\" y2=\"225\"></line><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"70\" y1=\"20\" y2=\"225\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"264\">زمان (ثانیه)</text><text fill=\"#1B2A4A\" font-family=\"BNazanin\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" transform=\"rotate(-90 16 122.5)\" x=\"16\" y=\"122.5\">ارتفاع (متر)</text><polyline fill=\"none\" points=\"70.0,225.0 79.2,220.0 88.3,206.3 97.5,191.9 106.7,178.2 115.8,165.2 125.0,152.9 134.2,141.2 143.3,130.2 152.5,119.8 161.7,110.1 170.8,101.1 180.0,92.8 189.2,85.1 198.3,78.1 207.5,71.8 216.7,66.1 225.8,61.2 235.0,56.8 244.2,53.2 253.3,50.2 262.5,47.9 271.7,46.3 280.8,45.3 290.0,45.0 299.2,45.4 308.3,46.4 317.5,48.1 326.7,50.5 335.8,53.5 345.0,57.2 354.2,61.6 363.3,66.7 372.5,72.4 381.7,78.8 390.8,85.9 400.0,93.6 409.2,102.0 418.3,111.1 427.5,120.8 436.7,131.2 445.8,142.3 455.0,154.1 464.2,166.5 473.3,179.6 482.5,193.4 491.7,207.8 500.8,222.9\" stroke=\"#2A9DAE\" stroke-width=\"2.5\"></polyline><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"290\" y=\"40\">اوج</text></svg><figcaption>شکل ۳-۳: نمودار ارتفاع-زمان یک پرتابگر آبی بدون چتر (مدل ساده بدون مقاومت هوا).</figcaption></figure><h2>نیروی پسا</h2><p><b>پسا</b> نیروی مقاومت هواست که همیشه خلاف جهت حرکت اثر می‌کند. پسا با <b>مجذور سرعت</b> زیاد می‌شود: اگر سرعت دو برابر شود، پسا چهار برابر می‌شود. پسا به سطح روبه‌روی جسم و شکل آن هم بستگی دارد. دماغه گرد و صاف و بالک‌های نازک، پسای پرتابگر را کم می‌کنند؛ و چتر با سطح بزرگش، پسای زیادی می‌سازد تا سرعت فرود کم شود.</p><div class=\"ex\"><div class=\"ex-t\">مثال ۳-۱: قانون دوم نیوتن در لحظه پرتاب</div><p>در لحظه پرتاب، رانش پرتابگری حدود ۱۵۰ نیوتن است. جرم کل (پرتابگر ۰٫۲ کیلوگرم + آب ۰٫۵ کیلوگرم) ۰٫۷ کیلوگرم است.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>وزن</td><td dir=\"ltr\">0.7 × 9.8 ≈ 6.9 N</td></tr><tr><td>نیروی کل رو به بالا</td><td dir=\"ltr\">150 − 6.9 ≈ 143 N</td></tr><tr><td>شتاب</td><td dir=\"ltr\">a = 143 ÷ 0.7 ≈ 204 m/s² ≈ 21 g</td></tr></table></div><p>یعنی در لحظه پرتاب، پرتابگر با شتابی حدود ۲۰ برابر شتاب گرانش بالا می‌رود! به همین دلیل همه اجزا، به‌ویژه کپسول و تخم‌مرغ، باید محکم بسته شوند.</p></div><div class=\"box why\"><div class=\"box-t\">برای دوره دوم: رانش و سرعت خروج آب</div><div><p>سرعت خروج آب از رابطه برنولی تقریباً v = √(2P ÷ ρ) و رانش تقریباً F ≈ 2 × P × A است؛ P فشار نسبی (پاسکال)، ρ چگالی آب (۱۰۰۰) و A مساحت دهانه نازل است.</p><p>برای P = ۴ بار = ۴ × ۱۰⁵ پاسکال و دهانه ۲۲ میلی‌متری (A ≈ ۳٫۸ × ۱۰⁻⁴ متر مربع): v ≈ √(۸۰۰) ≈ ۲۸ متر بر ثانیه و F ≈ ۲ × ۴ × ۱۰⁵ × ۳٫۸ × ۱۰⁻⁴ ≈ ۳۰۰ نیوتن در لحظه آغاز. با خروج آب، فشار و رانش به‌سرعت کم می‌شوند.</p></div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>وزن = جرم × g؛ نیرو با نیوتن سنجیده می‌شود.</li><li>پرتابگر طبق قانون سوم نیوتن، با راندن آب به پایین، به بالا رانده می‌شود.</li><li>آب چون چگال است، رانش بسیار بیشتری از هوای تنها می‌دهد.</li><li>مراحل پرواز: پیشرانش، پرواز آزاد، اوج و فرود.</li><li>پسا با مجذور سرعت زیاد می‌شود و خلاف جهت حرکت است.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>وزن یک تخم‌مرغ ۶۰ گرمی چند نیوتن است؟</li><li>سه قانون نیوتن را با یک مثال از پرتابگر آبی بیان کنید.</li><li>چرا بطری‌ای که فقط هوای فشرده دارد، تقریباً پرواز نمی‌کند؟</li><li>در کدام لحظه پرواز سرعت عمودی پرتابگر صفر است؟ چرا این لحظه برای باز شدن چتر مناسب است؟</li><li>اگر سرعت کپسول از ۳ به ۶ متر بر ثانیه برسد، پسای چتر چند برابر می‌شود؟</li><li>رانشی ۱۰۰ نیوتنی به پرتابگری با جرم کل ۰٫۵ کیلوگرم وارد می‌شود. شتاب آن (با در نظر گرفتن وزن) چقدر است؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>آزمایش بادکنک-موشک را با یک و دو بادکنک انجام دهید و مسافت طی‌شده را بسنجید. نتیجه را با قانون دوم نیوتن توضیح دهید.</div></div>"}, {"t": "فشار، هوای فشرده و ایمنی محفظه", "n": "فصل ۴", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>فشار چیست و با چه یکاهایی سنجیده می‌شود</li><li>فشار نسبی و مطلق؛ کار با فشارسنج</li><li>قانون بویل و مقدار بهینه آب</li><li>بطری مناسب، آزمون فشار و مرز ۵ بار</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۴<br>۹۰ دقیقه<br>الزامات ایمنی ستاره‌دار</div></div>\n<p>موتور پرتابگر شما هوای فشرده است. همین هوای فشرده، اگر بدون آگاهی و احتیاط به کار رود، می‌تواند خطرناک باشد. در این فصل می‌آموزید فشار چیست، چگونه انرژی را ذخیره می‌کند و چرا شیوه‌نامه مرز ۵ بار را تعیین کرده است.</p><h2>فشار یعنی چه؟</h2><p><b>فشار</b> نیرویی است که بر هر واحد سطح وارد می‌شود: فشار = نیرو ÷ مساحت. ذرات هوای درون بطری مدام به دیواره‌ها برخورد می‌کنند؛ هرچه هوای بیشتری را در بطری بفشارید، برخوردها بیشتر و فشار بیشتر می‌شود.</p><div class=\"fm\" dir=\"ltr\">P = F ÷ A</div><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:22%\">یکا</th><th style=\"width:40%\">معادل</th><th style=\"width:38%\">کجا می‌بینید</th></tr><tr><td class=\"l\">پاسکال (Pa)</td><td class=\"l\">۱ نیوتن بر متر مربع</td><td class=\"l\">یکای علمی</td></tr><tr><td class=\"l\">کیلوپاسکال (kPa)</td><td class=\"l\">۱۰۰۰ پاسکال</td><td class=\"l\">برخی فشارسنج‌ها</td></tr><tr><td class=\"l\">بار (bar)</td><td class=\"l\">۱۰۰٬۰۰۰ پاسکال؛ تقریباً فشار هوا در سطح دریا</td><td class=\"l\">فشارسنج پمپ‌ها</td></tr><tr><td class=\"l\">PSI</td><td class=\"l\">پوند بر اینچ مربع؛ ۱ بار ≈ ۱۴٫۵ PSI</td><td class=\"l\">پمپ‌های دوچرخه و باد لاستیک</td></tr></table></div><div class=\"ex\"><div class=\"ex-t\">مثال ۴-۱: تبدیل یکا</div><div class=\"tbl\"><table class=\"calc\"><tr><td>۵ بار به PSI</td><td dir=\"ltr\">5 × 14.5 = 72.5 PSI</td></tr><tr><td>۶۰ PSI به بار</td><td dir=\"ltr\">60 ÷ 14.5 ≈ 4.1 bar</td></tr><tr><td>۴ بار به پاسکال</td><td dir=\"ltr\">4 × 100,000 = 400,000 Pa</td></tr></table></div></div><h2>فشار نسبی و فشار مطلق</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 230\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"230\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><circle cx=\"200\" cy=\"120\" fill=\"#fff\" r=\"85\" stroke=\"#1B2A4A\" stroke-width=\"4\"></circle><line stroke=\"#1B2A4A\" stroke-width=\"2.5\" x1=\"144.1\" x2=\"152.6\" y1=\"175.9\" y2=\"167.4\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"163\" y=\"162\">0</text><line stroke=\"#1B2A4A\" stroke-width=\"2.5\" x1=\"124.9\" x2=\"136.3\" y1=\"144.4\" y2=\"140.7\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"150\" y=\"141\">1</text><line stroke=\"#1B2A4A\" stroke-width=\"2.5\" x1=\"122.0\" x2=\"133.8\" y1=\"107.6\" y2=\"109.5\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"148\" y=\"117\">2</text><line stroke=\"#1B2A4A\" stroke-width=\"2.5\" x1=\"136.1\" x2=\"145.8\" y1=\"73.6\" y2=\"80.6\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"157\" y=\"94\">3</text><line stroke=\"#1B2A4A\" stroke-width=\"2.5\" x1=\"164.1\" x2=\"169.6\" y1=\"49.6\" y2=\"60.3\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"176\" y=\"78\">4</text><line stroke=\"#1B2A4A\" stroke-width=\"2.5\" x1=\"200.0\" x2=\"200.0\" y1=\"41.0\" y2=\"53.0\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"200\" y=\"72\">5</text><line stroke=\"#C0392B\" stroke-width=\"2.5\" x1=\"235.9\" x2=\"230.4\" y1=\"49.6\" y2=\"60.3\"></line><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"224\" y=\"78\">6</text><line stroke=\"#C0392B\" stroke-width=\"2.5\" x1=\"263.9\" x2=\"254.2\" y1=\"73.6\" y2=\"80.6\"></line><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"243\" y=\"94\">7</text><line stroke=\"#C0392B\" stroke-width=\"2.5\" x1=\"278.0\" x2=\"266.2\" y1=\"107.6\" y2=\"109.5\"></line><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"252\" y=\"117\">8</text><line stroke=\"#C0392B\" stroke-width=\"2.5\" x1=\"275.1\" x2=\"263.7\" y1=\"144.4\" y2=\"140.7\"></line><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"250\" y=\"141\">9</text><line stroke=\"#C0392B\" stroke-width=\"2.5\" x1=\"255.9\" x2=\"247.4\" y1=\"175.9\" y2=\"167.4\"></line><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"12\" text-anchor=\"middle\" x=\"237\" y=\"162\">10</text><line stroke=\"#C0392B\" stroke-width=\"3\" x1=\"200.0\" x2=\"176.8\" y1=\"120.0\" y2=\"61.4\"></line><circle cx=\"200.0\" cy=\"120.0\" fill=\"#1B2A4A\" opacity=\"1.00\" r=\"6.0\"></circle><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"13\" text-anchor=\"middle\" x=\"200\" y=\"165\">bar</text><path d=\"M200.0,37.0 A83,83 0 0 1 258.7,178.7\" fill=\"none\" opacity=\".5\" stroke=\"#C0392B\" stroke-width=\"6\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"start\" x=\"650\" y=\"60\">فشارسنج «فشار نسبی» را نشان می‌دهد:</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"start\" x=\"650\" y=\"85\">فشار اضافه بر فشار هوای بیرون</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"13.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"650\" y=\"125\">بیشینه مجاز: ۵ بار (حدود ۷۲ PSI)</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"650\" y=\"150\">ناحیه قرمز = ممنوع</text></svg><figcaption>شکل ۴-۱: فشارسنج و ناحیه ممنوع.</figcaption></figure><p>هوای اطراف ما هم فشار دارد (حدود ۱ بار در سطح دریا). فشارسنج پمپ، فشار <b>اضافه</b> بر هوای بیرون را نشان می‌دهد که به آن <b>فشار نسبی</b> می‌گویند. وقتی فشارسنج «۴ بار» نشان می‌دهد، فشار <b>مطلق</b> درون بطری حدود ۵ بار است. در شیوه‌نامه و این کتابچه، منظور از فشار، همیشه فشار نسبی (عدد فشارسنج) است.</p><h2>انرژی ذخیره‌شده در هوای فشرده</h2><p>هوای فشرده مانند فنری جمع‌شده، انرژی ذخیره می‌کند. هرچه فشار بیشتر، انرژی بیشتر. اگر بطری بترکد، این انرژی ناگهان آزاد می‌شود و تکه‌های پلاستیک را با سرعت به اطراف پرتاب می‌کند. به همین دلیل:</p><div class=\"box warn\"><div class=\"box-t\">الزامات ایمنی ستاره‌دار شیوه‌نامه (نقض = حذف اثر)</div><div><ul class=\"ul\"><li>حداکثر فشار مجاز در هر محفظه <b>۵ بار</b> (حدود ۷۲ PSI) است؛ فشارسنج سالم روی سکو الزامی است.</li><li>فقط <b>بطری PET نوشابه گازدار سالم</b>. بطری آسیب‌دیده، شیشه، فلز، محفظه دست‌ساز و هر ماده شیمیایی، آتش‌زا یا محترقه ممنوع است.</li><li>پر کردن هوا و رهاسازی از فاصله دست‌کم ۱٫۵ متر با شلنگ بلند و رهاساز از راه دور (توصیه این کتاب: ۵ متر)؛<b></b> تماشاگران دست‌کم <b>۱۰ متر</b> دورتر و پشت اپراتور. نزدیک شدن به پرتابگر تحت فشار ممنوع است.</li></ul></div></div><h2>چرا بطری نوشابه گازدار؟</h2><p>بطری‌های نوشابه گازدار برای نگه‌داشتن گاز تحت فشار ساخته شده‌اند و دیواره و ته آن‌ها (با پایه‌های گلبرگی) مقاوم‌تر است. بطری آب معدنی یا روغن چنین مقاومتی ندارد. فشار ترکیدن بطری نو چند برابر ۵ بار است؛ اما این مقاومت با خراش، ضربه، گرما، کهنگی و برخی چسب‌ها و حلال‌ها کم می‌شود.</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:60%\">بررسی بطری پیش از هر استفاده</th><th style=\"width:40%\">اگر چنین بود</th></tr><tr><td class=\"l\">خراش عمیق، فرورفتگی یا ترک</td><td class=\"l\">کنار بگذارید</td></tr><tr><td class=\"l\">سفید شدن یا تغییر رنگ پلاستیک</td><td class=\"l\">کنار بگذارید</td></tr><tr><td class=\"l\">تماس با آب داغ، آتش یا آفتاب طولانی</td><td class=\"l\">کنار بگذارید</td></tr><tr><td class=\"l\">چسب‌کاری با چسب‌های حلال‌دار روی بدنه</td><td class=\"l\">کنار بگذارید</td></tr><tr><td class=\"l\">بیش از ۲۰ تا ۳۰ بار پرتاب یا یک برخورد شدید</td><td class=\"l\">جایگزین کنید</td></tr></table></div><h2>قانون بویل</h2><p>اگر دما ثابت بماند، حاصل‌ضرب فشار مطلق و حجم یک مقدار گاز ثابت است. یعنی اگر حجم هوا دو برابر شود، فشارش نصف می‌شود.</p><div class=\"fm\" dir=\"ltr\">P₁ × V₁ = P₂ × V₂</div><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 230\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"230\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#fff\" height=\"160\" rx=\"22\" stroke=\"#1B2A4A\" stroke-width=\"2.5\" width=\"90\" x=\"475\" y=\"30\"></rect><rect fill=\"#7fc3ee\" height=\"51.333333333333336\" width=\"86\" x=\"477\" y=\"136.66666666666669\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"100\">هوا</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"120\">۶ بار مطلق</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"215\">پیش از پرتاب</text><rect fill=\"#fff\" height=\"160\" rx=\"22\" stroke=\"#1B2A4A\" stroke-width=\"2.5\" width=\"90\" x=\"175\" y=\"30\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"220\" y=\"100\">هوا</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"220\" y=\"120\">۴ بار مطلق</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"220\" y=\"215\">پایان خروج آب</text><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"85\">آب بیرون می‌رود ⟵</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"middle\" x=\"345\" y=\"110\">حجم هوا ۱ ⟵ ۱٫۵ لیتر</text></svg><figcaption>شکل ۴-۲: با خروج آب، حجم هوا زیاد و فشار آن کم می‌شود.</figcaption></figure><div class=\"ex\"><div class=\"ex-t\">مثال ۴-۲: فشار پس از خروج آب</div><p>بطری ۱٫۵ لیتری با ۰٫۵ لیتر آب و فشار نسبی ۵ بار (فشار مطلق ۶ بار) پرتاب می‌شود. وقتی همه آب بیرون رفت، فشار هوا چقدر است؟</p><div class=\"tbl\"><table class=\"calc\"><tr><td>پیش از پرتاب</td><td dir=\"ltr\">P₁ = 6 bar , V₁ = 1.0 L</td></tr><tr><td>پس از خروج آب</td><td dir=\"ltr\">V₂ = 1.5 L</td></tr><tr><td>فشار مطلق نهایی</td><td dir=\"ltr\">P₂ = 6 × 1.0 ÷ 1.5 = 4 bar</td></tr><tr><td>فشار نسبی نهایی</td><td dir=\"ltr\">4 − 1 = 3 bar</td></tr></table></div><p>هنوز ۳ بار فشار باقی است و هوا هم با یک «فوت» کوتاه کمی رانش می‌دهد. در واقع چون هوا هنگام انبساط سریع سرد می‌شود، فشار کمی کمتر از این است.</p></div><h2>چقدر آب؟</h2><p>اگر آب خیلی کم باشد، رانش زود تمام می‌شود؛ اگر خیلی زیاد باشد، هوای کافی برای راندن آن نیست و پرتابگر سنگین است. آزمایش‌ها نشان می‌دهند بهترین مقدار آب حدود <b>یک‌سوم حجم بطری</b> است (برای بطری ۱٫۵ لیتری، حدود ۵۰۰ میلی‌لیتر). این مقدار را با چند پرواز آزمایشی برای پرتابگر خودتان پیدا کنید.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 640 260\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#fff\" height=\"260\" rx=\"10\" stroke=\"#d9e2ee\" width=\"640\"></rect><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"215.0\" y2=\"215.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"219.0\">0</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"170.7\" y2=\"170.7\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"174.7\">25</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"126.4\" y2=\"126.4\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"130.4\">50</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"82.0\" y2=\"82.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"86.0\">75</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"37.7\" y2=\"37.7\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"41.7\">100</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"70.0\" y=\"231\">0</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"207.5\" y=\"231\">0.25</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"345.0\" y=\"231\">0.5</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"482.5\" y=\"231\">0.75</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"620.0\" y=\"231\">1</text><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"620\" y1=\"215\" y2=\"215\"></line><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"70\" y1=\"20\" y2=\"215\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"254\">سهم آب از حجم بطری</text><text fill=\"#1B2A4A\" font-family=\"BNazanin\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" transform=\"rotate(-90 16 117.5)\" x=\"16\" y=\"117.5\">ارتفاع نسبی (درصد)</text><polyline fill=\"none\" points=\"70.0,215.0 97.5,168.3 125.0,129.4 152.5,97.8 180.0,73.2 207.5,55.2 235.0,43.3 262.5,37.0 290.0,36.1 317.5,39.9 345.0,47.9 372.5,59.7 400.0,74.7 427.5,92.2 455.0,111.7 482.5,132.3 510.0,153.3 537.5,173.6 565.0,192.1 592.5,207.0 620.0,215.0\" stroke=\"#2A9DAE\" stroke-width=\"2.5\"></polyline></svg><figcaption>شکل ۴-۳: ارتفاع نسبی بر حسب سهم آب (طرح کیفی).</figcaption></figure><h2>آزمون فشار</h2><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>بطری را <b>کاملاً پر از آب</b> کنید (آب تراکم‌پذیر نیست و اگر بطری بترکد، انرژی کمی آزاد می‌شود).</div></li><li><span class=\"sn\">۲</span><div>بطری را روی سکو و درون یک حفاظ محکم بگذارید.</div></li><li><span class=\"sn\">۳</span><div>از فاصله دست‌کم ۵ متر، آرام فشار را تا ۵ بار بالا ببرید.</div></li><li><span class=\"sn\">۴</span><div>یک دقیقه صبر کنید؛ نشتی، تغییر شکل غیرعادی یا افت فشار را بررسی کنید.</div></li><li><span class=\"sn\">۵</span><div>فشار را با شیر تخلیه آرام خالی کنید.</div></li><li><span class=\"sn\">۶</span><div>نتیجه را با تاریخ و عکس در پرونده مأموریت ثبت کنید. هر بطری (از جمله بوسترها) باید جداگانه آزمون شود.</div></li></ol><div class=\"box out\"><div class=\"box-t\">پیوند با داوری</div><div>آزمون فشار یکی از آزمون‌های زمینی مستندی است که شیوه‌نامه از شما می‌خواهد (دست‌کم سه آزمون). معیار «آزمون و بهبود» ۱۱ امتیاز دارد.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>فشار = نیرو ÷ مساحت؛ ۱ بار ≈ ۱۴٫۵ PSI ≈ ۱۰۰ کیلوپاسکال.</li><li>فشارسنج، فشار نسبی (اضافه بر هوای بیرون) را نشان می‌دهد.</li><li>هوای فشرده انرژی ذخیره می‌کند؛ مرز ۵ بار و بطری PET نوشابه گازدار سالم الزامی است.</li><li>قانون بویل: P₁V₁ = P₂V₂ (فشار مطلق).</li><li>مقدار بهینه آب حدود یک‌سوم حجم بطری است؛ آزمون فشار با بطری پر از آب انجام می‌شود.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>۳٫۵ بار چند PSI و چند کیلوپاسکال است؟</li><li>فشارسنج ۴٫۵ بار نشان می‌دهد. فشار مطلق درون بطری چقدر است؟</li><li>چرا آزمون فشار را با بطری کاملاً پر از آب انجام می‌دهیم؟</li><li>بطری ۲ لیتری با ۰٫۷ لیتر آب در فشار نسبی ۴ بار پرتاب می‌شود. فشار نسبی پس از خروج کامل آب چقدر است؟</li><li>سه نشانه که می‌گویند یک بطری نباید استفاده شود، نام ببرید.</li><li>چرا بطری آب معدنی برای پرتابگر مناسب نیست؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>بطری‌های تیم را با جدول بررسی این فصل وارسی و شماره‌گذاری کنید. زیر نظر مربی، آزمون فشار را برای همه بطری‌ها انجام دهید و نتیجه را با عکس در پرونده ثبت کنید.</div></div>"}, {"t": "پایداری پرواز: مرکز جرم و مرکز فشار", "n": "فصل ۵", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>چرا برخی پرتابگرها راست می‌روند و برخی معلق می‌زنند</li><li>مرکز جرم (CG) و مرکز فشار (CP)</li><li>یافتن CG و CP و حاشیه پایداری</li><li>طراحی بالک‌ها و آزمون چرخش</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۵<br>۹۰ دقیقه<br>معیارهای ۲ و ۴</div></div>\n<p>پرتابگری که راست و پایدار پرواز نکند، به هر سو می‌چرخد، ارتفاع نمی‌گیرد و ممکن است به سوی تماشاگران برود. پایداری، مهم‌ترین ویژگی طراحی پرتابگر است و خوشبختانه با یک قاعده ساده به دست می‌آید.</p><h2>تیر و پیکان</h2><p>چرا تیر و کمان یا دارت، همیشه با نوک به جلو پرواز می‌کنند؟ چون وزن بیشتر در جلو (نوک فلزی) و «پر» در عقب است. اگر نوک تیر کمی منحرف شود، هوا به پرهای عقب فشار می‌آورد و آن‌ها را به عقب برمی‌گرداند؛ مثل بادنمایی که همیشه رو به باد می‌ایستد. پرتابگر شما هم باید همین‌گونه باشد: <b>سنگینی در جلو، بالک‌ها در عقب</b>.</p><h2>دو نقطه کلیدی</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 230\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"cc\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"230\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><path d=\"M120,89.0 Q50,115 120,141.0 Z\" fill=\"#C0392B\"></path><rect fill=\"#e8f1fb\" height=\"52\" rx=\"16\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"420\" x=\"120\" y=\"89.0\"></rect><path d=\"M430,89.0 L520,34.0 L540,34.0 L540,89.0 Z\" fill=\"#1B2A4A\"></path><path d=\"M430,141.0 L520,196.0 L540,196.0 L540,141.0 Z\" fill=\"#1B2A4A\"></path><circle cx=\"300\" cy=\"115\" fill=\"#fff\" r=\"12\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><path d=\"M300,103 A12,12 0 0 1 312,115 L300,115 Z M300,127 A12,12 0 0 1 288,115 L300,115 Z\" fill=\"#1B2A4A\"></path><circle cx=\"430\" cy=\"115\" fill=\"#C0392B\" r=\"10\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"300\" y=\"40\">مرکز جرم (CG)</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"430\" y=\"40\">مرکز فشار (CP)</text><line stroke=\"#1B2A4A\" stroke-dasharray=\"3 3\" stroke-width=\"1\" x1=\"300.0\" x2=\"300.0\" y1=\"52.0\" y2=\"85.0\"></line><line stroke=\"#C0392B\" stroke-dasharray=\"3 3\" stroke-width=\"1\" x1=\"430.0\" x2=\"430.0\" y1=\"52.0\" y2=\"85.0\"></line><line marker-end=\"url(#cc)\" stroke=\"#2A9DAE\" stroke-width=\"2\" x1=\"300.0\" x2=\"430.0\" y1=\"205.0\" y2=\"205.0\"></line><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"365\" y=\"222\">حاشیه پایداری: ۱ تا ۲ برابر قطر بدنه</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"60\" y=\"120\">جلو</text></svg><figcaption>شکل ۵-۱: مرکز جرم، مرکز فشار و حاشیه پایداری.</figcaption></figure><div class=\"tbl\"><table class=\"kv\"><tr><td>مرکز جرم (CG)</td><td>نقطه‌ای که اگر پرتابگر را از آن آویزان کنید یا روی انگشت بگذارید، تعادل می‌ماند. پرتابگر در هوا به دور این نقطه می‌چرخد.</td></tr><tr><td>مرکز فشار (CP)</td><td>نقطه‌ای که می‌توان فرض کرد همه نیروی هوا (هنگامی که پرتابگر کمی کج شده) بر آن اثر می‌کند. بالک‌های بزرگ در عقب، CP را به عقب می‌برند.</td></tr></table></div><div class=\"box out\"><div class=\"box-t\">قاعده طلایی پایداری</div><div><b>مرکز جرم باید جلوتر از مرکز فشار باشد</b>؛ بهتر است فاصله آن‌ها (حاشیه پایداری) ۱ تا ۲ برابر قطر بدنه باشد. حاشیه خیلی کم، پرواز ناپایدار و حاشیه خیلی زیاد، پرتابگر را بیش از حد رو به باد می‌چرخاند.</div></div><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 220\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"wc\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#E0A93B\"></path></marker></defs><defs><marker id=\"wt\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#2A9DAE\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"220\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><g transform=\"rotate(20 520 150)\"><rect fill=\"#e8f1fb\" height=\"76.5\" rx=\"6.9\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"19.8\" x=\"510.1\" y=\"60.0\"></rect><path d=\"M510.1,63.6 Q520.0,29.4 529.9,63.6 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"13.5\" width=\"7.2\" x=\"516.4\" y=\"136.5\"></rect><path d=\"M510.1,118.5 L495.7,142.8 L510.1,136.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M529.9,118.5 L544.3,142.8 L529.9,136.5 Z\" fill=\"#1B2A4A\"></path></g><path d=\"M560,60 A60,60 0 0 0 530,45\" fill=\"none\" marker-end=\"url(#wt)\" stroke=\"#2A9DAE\" stroke-width=\"2.5\"></path><line stroke=\"#9fb0c6\" stroke-width=\"1\" x1=\"460.0\" x2=\"580.0\" y1=\"200.0\" y2=\"200.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"205\">پایدار: CG جلوتر از CP؛ دماغه به مسیر برمی‌گردد</text><g transform=\"rotate(20 190 150)\"><rect fill=\"#e8f1fb\" height=\"76.5\" rx=\"6.9\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"19.8\" x=\"180.1\" y=\"60.0\"></rect><path d=\"M180.1,63.6 Q190.0,29.4 199.9,63.6 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"13.5\" width=\"7.2\" x=\"186.4\" y=\"136.5\"></rect><path d=\"M180.1,118.5 L165.7,142.8 L180.1,136.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M199.9,118.5 L214.3,142.8 L199.9,136.5 Z\" fill=\"#1B2A4A\"></path></g><path d=\"M210,45 A60,60 0 0 1 245,75\" fill=\"none\" stroke=\"#C0392B\" stroke-width=\"2.5\"></path><line stroke=\"#9fb0c6\" stroke-width=\"1\" x1=\"130.0\" x2=\"250.0\" y1=\"200.0\" y2=\"200.0\"></line><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"190\" y=\"205\">ناپایدار: CP جلوتر؛ پرتابگر معلق می‌زند</text></svg><figcaption>شکل ۵-۲: پرتابگر پایدار و ناپایدار.</figcaption></figure><h2>یافتن مرکز جرم</h2><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>پرتابگر را <b>کاملاً آماده پرواز</b> کنید: با کپسول، تخم‌مرغ (یا وزنه هم‌جرم)، چتر و <b>آب</b> به مقدار پرواز (درِ بطری را ببندید).</div></li><li><span class=\"sn\">۲</span><div>پرتابگر را افقی روی لبه یک خط‌کش یا انگشت بگذارید و جابه‌جا کنید تا تعادل بماند.</div></li><li><span class=\"sn\">۳</span><div>آن نقطه را با ماژیک علامت بزنید: CG.</div></li><li><span class=\"sn\">۴</span><div>CG را یک بار هم بدون آب پیدا کنید؛ چون پس از خروج آب، CG به جلو می‌رود و پایداری بیشتر می‌شود. حالت با آب، حالت بحرانی‌تر است.</div></li></ol><h2>یافتن مرکز فشار: روش مقوا</h2><p>یک روش ساده و محتاطانه: شکل نیم‌رخ پرتابگر (بدنه، دماغه و یک بالک) را با اندازه واقعی روی مقوا بکشید و ببرید. سپس نقطه تعادل این برش مقوایی را پیدا کنید؛ آن نقطه، تقریبی از CP است. این روش CP را کمی جلوتر از واقع نشان می‌دهد؛ یعنی اگر با این روش پایدار باشید، در واقع کمی پایدارتر هستید.</p><div class=\"box why\"><div class=\"box-t\">برای دوره دوم: محاسبه دقیق‌تر</div><div>روش‌های محاسباتی دقیق‌تری (مانند روش «باروومن») وجود دارند که CP را از روی شکل دماغه و ابعاد بالک‌ها محاسبه می‌کنند. نرم‌افزار رایگان OpenRocket این محاسبه را خودکار انجام می‌دهد: ابعاد بدنه، دماغه و بالک‌ها را وارد کنید تا جای CG و CP و حاشیه پایداری را نشان دهد (فصل ۱۴).</div></div><h2>آزمون چرخش</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 240\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"sw\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#2A9DAE\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"240\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><circle cx=\"345.0\" cy=\"40.0\" fill=\"#1B2A4A\" opacity=\"1.00\" r=\"6.0\"></circle><line stroke=\"#555\" stroke-width=\"1.5\" x1=\"345.0\" x2=\"470.0\" y1=\"40.0\" y2=\"170.0\"></line><ellipse cx=\"345\" cy=\"175\" fill=\"none\" rx=\"150\" ry=\"40\" stroke=\"#9fb0c6\" stroke-dasharray=\"5 5\"></ellipse><g transform=\"rotate(-100 470 172)\"><rect fill=\"#e8f1fb\" height=\"59.5\" rx=\"5.4\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"15.4\" x=\"462.3\" y=\"102.0\"></rect><path d=\"M462.3,104.8 Q470.0,78.2 477.7,104.8 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"10.5\" width=\"5.6\" x=\"467.2\" y=\"161.5\"></rect><path d=\"M462.3,147.5 L451.1,166.4 L462.3,161.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M477.7,147.5 L488.9,166.4 L477.7,161.5 Z\" fill=\"#1B2A4A\"></path></g><path d=\"M230,205 A150,40 0 0 0 460,212\" fill=\"none\" marker-end=\"url(#sw)\" stroke=\"#2A9DAE\" stroke-width=\"2\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"355\" y=\"30\">نخ در محل مرکز جرم بسته می‌شود</text><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"232\">اگر دماغه همیشه رو به جلوی حرکت بماند، پرتابگر پایدار است</text></svg><figcaption>شکل ۵-۳: آزمون چرخش.</figcaption></figure><p>نخی محکم به طول حدود ۲ متر را در محل CG پرتابگر آماده پرواز ببندید (با نوار چسب تا نلغزد). در فضای باز، پرتابگر را به دور سر خود بچرخانید. اگر دماغه همیشه رو به جلوی حرکت بماند، پرتابگر پایدار است. اگر معلق بزند یا عقب‌عقب برود، ناپایدار است. <b>مراقب اطرافیان باشید.</b></p><h2>چگونه پایداری را بیشتر کنیم؟</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:30%\">راه</th><th style=\"width:70%\">اثر</th></tr><tr><td class=\"l\">افزودن وزنه به دماغه (خمیر، گِل، سکه در دماغه نرم)</td><td class=\"l\">CG را به جلو می‌برد؛ اما جرم را زیاد می‌کند.</td></tr><tr><td class=\"l\">بالک‌های بزرگ‌تر یا عقب‌تر</td><td class=\"l\">CP را به عقب می‌برد؛ اما پسا و جرم را زیاد می‌کند.</td></tr><tr><td class=\"l\">بدنه بلندتر (مثلاً با کپسول یا لوله در جلو)</td><td class=\"l\">فاصله CG و CP را بیشتر می‌کند.</td></tr></table></div><h2>بالک‌ها</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 200\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"200\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#e8f1fb\" height=\"110\" stroke=\"#1B2A4A\" width=\"14\" x=\"625\" y=\"40\"></rect><path d=\"M0,0 L50,-60 L80,-60 L80,0 Z\" fill=\"#1B2A4A\" transform=\"translate(545,150)\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"595\" y=\"185\">ذوزنقه‌ای</text><rect fill=\"#e8f1fb\" height=\"110\" stroke=\"#1B2A4A\" width=\"14\" x=\"465\" y=\"40\"></rect><path d=\"M0,0 L80,-60 L80,0 Z\" fill=\"#1B2A4A\" transform=\"translate(385,150)\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"435\" y=\"185\">مثلثی</text><rect fill=\"#e8f1fb\" height=\"110\" stroke=\"#1B2A4A\" width=\"14\" x=\"305\" y=\"40\"></rect><path d=\"M0,0 Q20,-70 80,-60 L80,0 Z\" fill=\"#1B2A4A\" transform=\"translate(225,150)\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"275\" y=\"185\">بیضوی</text><rect fill=\"#e8f1fb\" height=\"110\" stroke=\"#1B2A4A\" width=\"14\" x=\"145\" y=\"40\"></rect><path d=\"M0,0 L70,-55 L95,-40 L80,0 Z\" fill=\"#1B2A4A\" transform=\"translate(65,150)\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"115\" y=\"185\">عقب‌رفته</text></svg><figcaption>شکل ۵-۴: چند شکل رایج بالک.</figcaption></figure><ul class=\"ul\"><li>تعداد: سه یا چهار بالک با فاصله مساوی (۱۲۰ یا ۹۰ درجه). سه بالک سبک‌تر و چهار بالک ساده‌تر برای تراز کردن است.</li><li>جنس: مقوای پلاستیکی (کارتن‌پلاست)، فوم سخت یا پلاستیک نازک؛ سبک، محکم و غیرفلزی، با لبه‌های بدون تیزی (الزام ایمنی).</li><li>جای نصب: هرچه عقب‌تر، بهتر؛ اما لبه پایینی بالک نباید مانع نشستن بطری روی سکو و رهاساز شود.</li><li>راستا: بالک‌ها باید کاملاً موازی محور بدنه باشند؛ بالک کج، پرتابگر را می‌چرخاند و منحرف می‌کند.</li><li>اندازه: برای بطری ۱٫۵ لیتری، هر بالک با مساحتی حدود ۸۰ تا ۱۲۰ سانتی‌متر مربع، نقطه شروع خوبی است؛ سپس با آزمون CG/CP و آزمون چرخش تنظیم کنید.</li></ul><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>پرتابگر پایدار، مانند تیر، با دماغه رو به جلو پرواز می‌کند.</li><li>مرکز جرم باید ۱ تا ۲ برابر قطر بدنه جلوتر از مرکز فشار باشد.</li><li>CG را با تعادل روی لبه و CP را با روش مقوا یا نرم‌افزار پیدا کنید.</li><li>آزمون چرخش، پایداری را پیش از پرواز نشان می‌دهد.</li><li>وزنه در دماغه CG را جلو و بالک‌های عقب CP را عقب می‌برد.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>چرا تیر همیشه با نوک به جلو پرواز می‌کند؟</li><li>CG پرتابگری ۳۵ سانتی‌متر و CP آن ۴۵ سانتی‌متر از نوک دماغه است. قطر بدنه ۹ سانتی‌متر است. حاشیه پایداری چند برابر قطر است؟ پایدار است؟</li><li>چرا CG را با آب پیدا می‌کنیم؟</li><li>پرتابگری در آزمون چرخش معلق می‌زند. دو راه برای اصلاح آن پیشنهاد کنید.</li><li>چرا بالک کج خطرناک است؟</li><li>افزودن کپسول سنگین به دماغه چه اثری بر پایداری دارد؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>CG و CP پرتابگر طراحی‌شده تیم را (با روش مقوا) پیدا کنید، حاشیه پایداری را حساب کنید و پس از ساخت، آزمون چرخش را انجام دهید و از آن فیلم بگیرید.</div></div>"}, {"t": "پیش‌بینی و اندازه‌گیری ارتفاع و زمان پرواز", "n": "فصل ۶", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>برآورد ساده ارتفاع اوج و زمان پرواز</li><li>اندازه‌گیری ارتفاع با زاویه‌سنج از فاصله معلوم</li><li>تحلیل ویدئوی پرواز</li><li>مقایسه پیش‌بینی با اندازه‌گیری</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۶<br>۹۰ دقیقه<br>الزام «سنجش عملکرد» (معیار ۸) و معیار ۱۲</div></div>\n<p>شیوه‌نامه از شما می‌خواهد ارتفاع اوج و زمان پرواز را «با روشی مستند» برآورد کنید. مهندسان فضا همیشه پیش از پرواز پیش‌بینی می‌کنند و پس از پرواز اندازه می‌گیرند؛ فاصله این دو، نشان می‌دهد چقدر سامانه خود را می‌شناسند.</p><h2>ارتفاع از سرعت</h2><p>پس از پایان پیشرانش، پرتابگر با سرعت v بالا می‌رود و گرانش هر ثانیه ۹٫۸ متر بر ثانیه از سرعتش می‌کاهد. اگر مقاومت هوا را نادیده بگیریم:</p><div class=\"fm\" dir=\"ltr\">t (تا اوج) = v ÷ g ,   h = v² ÷ (2g)</div><div class=\"ex\"><div class=\"ex-t\">مثال ۶-۱: برآورد ساده</div><p>پرتابگری در پایان پیشرانش به سرعت ۲۲ متر بر ثانیه رسیده است.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>زمان تا اوج</td><td dir=\"ltr\">t = 22 ÷ 9.8 ≈ 2.2 s</td></tr><tr><td>ارتفاع اوج (بدون پسا)</td><td dir=\"ltr\">h = 22² ÷ (2 × 9.8) ≈ 24.7 m</td></tr></table></div><p>در واقع پسا ارتفاع را کمتر می‌کند؛ معمولاً ۱۰ تا ۳۰ درصد. ارتفاع معمول پرتابگرهای آبی تک‌بطری در فشار ۴ تا ۵ بار، ۱۵ تا ۳۵ متر است.</p></div><h2>ارتفاع از زمان</h2><p>اگر زمان اوج را از ویدئو بخوانید (t)، می‌توانید ارتفاع را تخمین بزنید: h ≈ ½ g t² ≈ ۴٫۹ t². مثلاً اگر اوج در ۲٫۳ ثانیه پس از پرتاب باشد، h ≈ ۴٫۹ × ۲٫۳² ≈ ۲۶ متر. این روش هم به دلیل پسا کمی بیشتر از واقع برآورد می‌کند.</p><h2>روش زاویه‌سنج</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 260\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"an\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><defs><lineargradient id=\"sk\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#cfe6fb\"></stop><stop offset=\"1\" stop-color=\"#f4f9ff\"></stop></lineargradient></defs><rect fill=\"url(#sk)\" height=\"260\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#b8d69a\" height=\"38\" width=\"690\" x=\"0\" y=\"222\"></rect><g transform=\"rotate(0 560 60)\"><rect fill=\"#e8f1fb\" height=\"42.5\" rx=\"3.8\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"11.0\" x=\"554.5\" y=\"10.0\"></rect><path d=\"M554.5,12.0 Q560.0,-7.0 565.5,12.0 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"7.5\" width=\"4.0\" x=\"558.0\" y=\"52.5\"></rect><path d=\"M554.5,42.5 L546.5,56.0 L554.5,52.5 Z\" fill=\"#1B2A4A\"></path><path d=\"M565.5,42.5 L573.5,56.0 L565.5,52.5 Z\" fill=\"#1B2A4A\"></path></g><line stroke=\"#8a97ab\" stroke-dasharray=\"4 4\" stroke-width=\"1.2\" x1=\"560.0\" x2=\"560.0\" y1=\"222.0\" y2=\"40.0\"></line><circle cx=\"140\" cy=\"194\" fill=\"#1B2A4A\" r=\"7\"></circle><line stroke=\"#1B2A4A\" stroke-width=\"3\" x1=\"140.0\" x2=\"140.0\" y1=\"201.0\" y2=\"222.0\"></line><line stroke=\"#E0A93B\" stroke-width=\"2\" x1=\"140.0\" x2=\"560.0\" y1=\"194.0\" y2=\"40.0\"></line><line stroke=\"#5a6b82\" stroke-dasharray=\"5 4\" stroke-width=\"1.2\" x1=\"140.0\" x2=\"560.0\" y1=\"194.0\" y2=\"194.0\"></line><path d=\"M200,194 A60,60 0 0 0 196,172\" fill=\"none\" stroke=\"#C0392B\" stroke-width=\"2\"></path><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"15\" font-style=\"italic\" text-anchor=\"middle\" x=\"218\" y=\"188\">θ</text><line marker-end=\"url(#an)\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" x1=\"140.0\" x2=\"560.0\" y1=\"242.0\" y2=\"242.0\"></line><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"14\" font-style=\"italic\" text-anchor=\"middle\" x=\"350\" y=\"238\">d</text><text fill=\"#1B2A4A\" font-family=\"DejaVu Serif\" font-size=\"15\" font-style=\"italic\" text-anchor=\"middle\" x=\"576\" y=\"130\">h</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"start\" x=\"128\" y=\"220\">ارتفاع چشم</text><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"15\" text-anchor=\"middle\" x=\"345\" y=\"35\">h = d × tan θ + ارتفاع چشم</text></svg><figcaption>شکل ۶-۱: اندازه‌گیری ارتفاع با زاویه‌سنج.</figcaption></figure><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>یک زاویه‌سنج بسازید: نقاله‌ای با یک نی روی لبه صاف و یک نخ و وزنه در مرکز (همان ربع؛ فصل ۵ کتابچه نجوم رصدی).</div></li><li><span class=\"sn\">۲</span><div>یک نفر در فاصله معلوم d (مثلاً ۳۰ متر) از سکو، در جهتی عمود بر جهت باد بایستد.</div></li><li><span class=\"sn\">۳</span><div>در لحظه اوج، پرتابگر را از درون نی نشانه بگیرد و نخ را روی نقاله نگه دارد.</div></li><li><span class=\"sn\">۴</span><div>زاویه θ را بخوانید و ارتفاع را حساب کنید: h = d × tan θ + ارتفاع چشم.</div></li></ol><div class=\"ex\"><div class=\"ex-t\">مثال ۶-۲: محاسبه ارتفاع</div><div class=\"tbl\"><table class=\"calc\"><tr><td>فاصله از سکو</td><td dir=\"ltr\">d = 30 m</td></tr><tr><td>زاویه در اوج</td><td dir=\"ltr\">θ = 40°</td></tr><tr><td>tan 40°</td><td dir=\"ltr\">≈ 0.84</td></tr><tr><td>ارتفاع</td><td dir=\"ltr\">h = 30 × 0.84 + 1.5 ≈ 26.7 m</td></tr></table></div><p>برای دوره اول که هنوز تانژانت نخوانده‌اند: جدول تانژانت پیوست را به کار ببرید، یا روی کاغذ شطرنجی مثلثی با همان زاویه و مقیاس بکشید و ارتفاع را با خط‌کش بخوانید.</p></div><div class=\"box tip\"><div class=\"box-t\">دو ناظر بهتر از یکی است</div><div>باد پرتابگر را جابه‌جا می‌کند و اگر پرتابگر به سمت ناظر یا دور از او برود، زاویه خطا دارد. دو ناظر در دو طرف سکو (مثلاً یکی در شمال و یکی در شرق) بگذارید و میانگین دو نتیجه را بگیرید.</div></div><div class=\"tbl wide\"><table class=\"wt\"><tr><th style=\"width:15%\">θ</th><th style=\"width:15%\">tan θ</th><th style=\"width:15%\">θ</th><th style=\"width:15%\">tan θ</th><th style=\"width:15%\">θ</th><th style=\"width:25%\">tan θ</th></tr><tr><td class=\"l\">۱۰°</td><td class=\"l\">۰٫۱۸</td><td class=\"l\">۳۵°</td><td class=\"l\">۰٫۷۰</td><td class=\"l\">۵۵°</td><td class=\"l\">۱٫۴۳</td></tr><tr><td class=\"l\">۱۵°</td><td class=\"l\">۰٫۲۷</td><td class=\"l\">۴۰°</td><td class=\"l\">۰٫۸۴</td><td class=\"l\">۶۰°</td><td class=\"l\">۱٫۷۳</td></tr><tr><td class=\"l\">۲۰°</td><td class=\"l\">۰٫۳۶</td><td class=\"l\">۴۵°</td><td class=\"l\">۱٫۰۰</td><td class=\"l\">۶۵°</td><td class=\"l\">۲٫۱۴</td></tr><tr><td class=\"l\">۲۵°</td><td class=\"l\">۰٫۴۷</td><td class=\"l\">۵۰°</td><td class=\"l\">۱٫۱۹</td><td class=\"l\">۷۰°</td><td class=\"l\">۲٫۷۵</td></tr><tr><td class=\"l\">۳۰°</td><td class=\"l\">۰٫۵۸</td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr></table></div><h2>تحلیل ویدئو</h2><p>ویدئوی پرواز داده ارزشمندی است. با یک برنامه پخش ویدئو که فریم‌به‌فریم جلو می‌رود (یا نرم‌افزار رایگان تحلیل حرکت مانند Tracker)، زمان پرتاب، اوج، باز شدن چتر و فرود را با دقت حدود یک‌سی‌ام ثانیه پیدا کنید. اگر دوربین ثابت و دور باشد و جسمی با ارتفاع معلوم (مثلاً یک تیر چراغ) در تصویر باشد، می‌توانید ارتفاع را هم با تناسب تخمین بزنید.</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:40%\">رویداد</th><th style=\"width:30%\">زمان از ویدئو (ثانیه)</th><th style=\"width:30%\">توضیح</th></tr><tr><td class=\"l\">جدا شدن از سکو</td><td class=\"l\">۰٫۰۰</td><td class=\"l\">مبدأ زمان</td></tr><tr><td class=\"l\">پایان پیشرانش</td><td class=\"l\">۰٫۱۵</td><td class=\"l\"></td></tr><tr><td class=\"l\">اوج و جدایش کپسول</td><td class=\"l\">۲٫۳</td><td class=\"l\"></td></tr><tr><td class=\"l\">باز شدن کامل چتر</td><td class=\"l\">۳٫۱</td><td class=\"l\"></td></tr><tr><td class=\"l\">فرود کپسول</td><td class=\"l\">۹٫۸</td><td class=\"l\">زمان کل پرواز کپسول</td></tr></table></div><h2>سرعت فرود</h2><p>سرعت فرود کپسول با چتر را هم می‌توان از ویدئو به دست آورد: اگر کپسول با چتر باز از ارتفاع حدود ۲۰ متر در ۵ ثانیه پایین آمده باشد، سرعت متوسط فرود ۴ متر بر ثانیه است. شیوه‌نامه سرعت ۳ تا ۶ متر بر ثانیه را توصیه کرده است.</p><h2>پیش‌بینی و مقایسه</h2><p>پیش از هر پرواز، ارتفاع را پیش‌بینی و در کاربرگ ثبت پرواز بنویسید؛ پس از پرواز، اندازه‌گیری را کنارش بنویسید. با چند پرواز، می‌توانید «ضریب اصلاح» پسا را برای پرتابگر خود پیدا کنید و پیش‌بینی‌های بعدی را دقیق‌تر کنید. در ماژول «سنجش ارتفاع»، نزدیکی ارتفاع ثبت‌شده به پیش‌بینی امتیاز دارد.</p><div class=\"fm\" dir=\"ltr\">درصد اختلاف = |اندازه‌گیری − پیش‌بینی| ÷ پیش‌بینی × ۱۰۰</div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>بدون پسا: زمان تا اوج = v ÷ g و ارتفاع = v² ÷ 2g؛ پسا ارتفاع واقعی را کمتر می‌کند.</li><li>ارتفاع با زاویه‌سنج: h = d × tan θ + ارتفاع چشم؛ دو ناظر خطای باد را کم می‌کنند.</li><li>تحلیل فریم‌به‌فریم ویدئو، زمان رویدادها را دقیق نشان می‌دهد.</li><li>پیش‌بینی پیش از پرواز و مقایسه پس از آن، بخش مهم پرونده مأموریت است.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>پرتابگری با سرعت ۱۸ متر بر ثانیه پیشرانش را تمام می‌کند. ارتفاع اوج بدون پسا و زمان تا اوج چقدر است؟</li><li>ناظری در فاصله ۲۵ متری، زاویه اوج را ۴۵ درجه می‌خواند. ارتفاع چشم ۱٫۵ متر است. ارتفاع اوج چقدر است؟</li><li>در ویدئو، اوج در ۲٫۰ ثانیه است. ارتفاع تقریبی چقدر است؟ چرا این عدد احتمالاً بیشتر از واقع است؟</li><li>چرا ناظر باید عمود بر جهت باد بایستد؟</li><li>کپسولی با چتر در ۶ ثانیه از ارتفاع ۲۱ متری فرود آمده است. سرعت متوسط فرود چقدر است؟ در بازه توصیه‌شده است؟</li><li>پیش‌بینی ۲۵ متر و اندازه‌گیری ۲۱ متر بوده است. درصد اختلاف چقدر است؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>یک زاویه‌سنج بسازید و ارتفاع یک ساختمان یا تیر بلند را از دو فاصله مختلف اندازه بگیرید. نتیجه را با ارتفاع واقعی (یا تخمین طبقه‌ها) مقایسه کنید.</div></div>"}, {"t": "ساخت پرتابگر", "n": "فصل ۷", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>اجزای پرتابگر آبی و مواد مناسب</li><li>ساخت دماغه نرم، بالک‌ها و محفظه کپسول</li><li>اتصال اجزا بدون آسیب به بطری</li><li>کنترل کیفیت ساخت</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۷<br>۹۰ دقیقه<br>معیار داوری ۴ (۷ امتیاز)</div></div>\n<p>اکنون نوبت ساختن است. پرتابگر خوب سبک، محکم، متقارن و پایدار است و همه اجزای آن پس از ده‌ها پرتاب هم سالم می‌مانند. در این فصل، ساخت یک پرتابگر تک‌بطری با کپسول مأموریت را گام‌به‌گام می‌بینیم.</p><h2>اجزای پرتابگر</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 330\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"330\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><path d=\"M295.0,110 Q330,5 365.0,110 Z\" fill=\"#C0392B\"></path><rect fill=\"#fde9c8\" height=\"60\" stroke=\"#1B2A4A\" width=\"70\" x=\"295.0\" y=\"110\"></rect><rect fill=\"#e8f1fb\" height=\"120\" rx=\"10\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"70\" x=\"295.0\" y=\"170\"></rect><rect fill=\"#7fc3ee\" height=\"58\" width=\"66\" x=\"297.0\" y=\"230\"></rect><rect fill=\"#9fb0c6\" height=\"12\" width=\"18\" x=\"321\" y=\"290\"></rect><path d=\"M295.0,220 L250.0,292 L295.0,280 Z\" fill=\"#1B2A4A\"></path><path d=\"M365.0,220 L410.0,292 L365.0,280 Z\" fill=\"#1B2A4A\"></path><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"369.0\" x2=\"450.0\" y1=\"70.0\" y2=\"70.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"456\" y=\"74\">دماغه نرم</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"369.0\" x2=\"450.0\" y1=\"140.0\" y2=\"140.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"456\" y=\"144\">کپسول مأموریت (محموله و تجهیزات)</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"369.0\" x2=\"450.0\" y1=\"195.0\" y2=\"195.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"456\" y=\"199\">بدنه تحت فشار (بطری PET)</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"369.0\" x2=\"450.0\" y1=\"260.0\" y2=\"260.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"456\" y=\"264\">آب (پیشران)</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"369.0\" x2=\"450.0\" y1=\"298.0\" y2=\"298.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"456\" y=\"302\">نازل (دهانه بطری)</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"265.0\" x2=\"180.0\" y1=\"265.0\" y2=\"265.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"174\" y=\"269\">بالک‌ها</text></svg><figcaption>شکل ۷-۱: اجزای پرتابگر آبی با کپسول مأموریت.</figcaption></figure><h2>مواد و ابزار</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:22%\">جزء</th><th style=\"width:48%\">مواد پیشنهادی</th><th style=\"width:30%\">نکته</th></tr><tr><td class=\"l\">بدنه تحت فشار</td><td class=\"l\">بطری PET نوشابه گازدار ۱٫۵ یا ۲ لیتری سالم</td><td class=\"l\">تنها جزء تحت فشار؛ دست‌کاری نشود</td></tr><tr><td class=\"l\">دماغه</td><td class=\"l\">توپ پلاستیکی نرم، فوم، نیمه بطری با سر نرم شده با فوم یا اسفنج</td><td class=\"l\">نرم و غیرنوک‌تیز (الزام ایمنی)</td></tr><tr><td class=\"l\">بالک</td><td class=\"l\">کارتن‌پلاست (ورق پلاستیکی کنگره‌ای)، فوم سخت، پلاستیک نازک</td><td class=\"l\">سبک، غیرفلزی، لبه بدون تیزی</td></tr><tr><td class=\"l\">محفظه کپسول</td><td class=\"l\">بخش بالایی بطری دیگر، لوله مقوایی، ظرف پلاستیکی سبک</td><td class=\"l\">روی بطری فشار سوار می‌شود، نه درون آن</td></tr><tr><td class=\"l\">اتصال</td><td class=\"l\">نوار چسب پهن، چسب حرارتی (فقط روی قطعات غیر تحت فشار)، بست کمربندی</td><td class=\"l\">چسب حرارتی و حلال‌ها بطری فشار را ضعیف می‌کنند</td></tr><tr><td class=\"l\">ابزار</td><td class=\"l\">قیچی، کاتر (زیر نظر بزرگ‌تر)، خط‌کش، ماژیک، ترازو</td><td class=\"l\"></td></tr></table></div><div class=\"box warn\"><div class=\"box-t\">به بطری تحت فشار دست نزنید</div><div>بطری تحت فشار را سوراخ، داغ، بریده یا با چسب‌های حلال‌دار چسب‌کاری نکنید. اجزا را با نوار چسب به آن ببندید. اگر به اتصال محکم‌تر نیاز دارید، یک «پوسته» (مثلاً بطری بریده‌شده دیگر یا حلقه مقوایی) دور بطری بکشید و بالک‌ها را به آن بچسبانید.</div></div><h2>گام‌های ساخت</h2><h3>۱. محفظه بالک و بالک‌ها</h3><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>یک الگوی کاغذی برای بالک بکشید (شکل‌های فصل ۵) و سه یا چهار بالک یکسان از کارتن‌پلاست ببرید. کنگره‌های کارتن‌پلاست باید موازی محور بدنه باشند تا بالک خم نشود.</div></li><li><span class=\"sn\">۲</span><div>لبه چسباندن هر بالک را ۱ تا ۲ سانتی‌متر تا بزنید تا «پایه» داشته باشد.</div></li><li><span class=\"sn\">۳</span><div>با یک نوار کاغذی دور بطری، محیط را اندازه بگیرید و جای بالک‌ها را با فاصله مساوی علامت بزنید (برای سه بالک، محیط ÷ ۳).</div></li><li><span class=\"sn\">۴</span><div>بالک‌ها را با نوار چسب پهن، کاملاً موازی محور بطری بچسبانید. از بالا نگاه کنید: بالک‌ها باید مانند پره‌های ستاره‌ای منظم باشند.</div></li><li><span class=\"sn\">۵</span><div>بالک‌ها را طوری نصب کنید که لبه پایینی آن‌ها کمی بالاتر از دهانه بطری باشد تا روی سکو و رهاساز گیر نکنند.</div></li></ol><h3>۲. محفظه کپسول</h3><p>ته بطری فشار (که در پرواز رو به بالاست) جای سوار شدن کپسول است. یک لوله یا ظرف سبک با قطر نزدیک به بطری را روی ته بطری قرار دهید و با نوار چسب ببندید. اگر ماژول جداسازی کپسول را دارید، کپسول نباید چسبانده شود؛ باید به‌گونه‌ای بنشیند که سازوکار جداسازی بتواند آن را آزاد کند (فصل ۱۲).</p><h3>۳. دماغه</h3><p>دماغه بالای کپسول قرار می‌گیرد. شکل گرد یا بیضوی، پسای کمی دارد. دماغه باید <b>نرم</b> باشد: یک توپ پلاستیکی نیم‌شده، یک مخروط کاغذی با سر فومی، یا نیمه بالایی یک بطری که سر آن با اسفنج پوشانده شده است. اگر به وزنه برای پایداری نیاز دارید، آن را درون دماغه و محکم قرار دهید.</p><h3>۴. تراز و تقارن</h3><ul class=\"ul\"><li>پرتابگر را عمودی روی میز بگذارید و از چند جهت نگاه کنید؛ دماغه باید درست روی محور باشد.</li><li>پرتابگر را افقی روی دو انگشت بچرخانید؛ نباید یک طرف سنگین‌تر باشد.</li><li>جرم نهایی را بسنجید و در بودجه جرم ثبت کنید.</li></ul><h2>کنترل کیفیت</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:70%\">بررسی</th><th style=\"width:30%\">تأیید</th></tr><tr><td class=\"l\">بطری فشار سالم، بدون خراش و بدون چسب حلال‌دار است.</td><td class=\"l\">☐</td></tr><tr><td class=\"l\">بالک‌ها موازی، متقارن و محکم‌اند و لبه تیز ندارند.</td><td class=\"l\">☐</td></tr><tr><td class=\"l\">دماغه نرم و محکم است.</td><td class=\"l\">☐</td></tr><tr><td class=\"l\">کپسول مهار شده و در پرتاب جدا نمی‌شود (یا سازوکار جداسازی آزموده شده است).</td><td class=\"l\">☐</td></tr><tr><td class=\"l\">CG جلوتر از CP است و آزمون چرخش موفق بوده است.</td><td class=\"l\">☐</td></tr><tr><td class=\"l\">هیچ جزء فلزی یا سنگین بیرونی وجود ندارد.</td><td class=\"l\">☐</td></tr></table></div><div class=\"box tip\"><div class=\"box-t\">پرتابگر یدک</div><div>از هر جزء یک نسخه یدک بسازید. در روز پرتاب، یک بالک شکسته یا دماغه آسیب‌دیده نباید مأموریت را متوقف کند. همچنین تذکر شیوه‌نامه را به یاد داشته باشید: سازه باید از نظر ابعاد و استحکام، قابلیت حمل یا ارسال به مراحل بالاتر را داشته باشد.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>تنها جزء تحت فشار بطری PET است و نباید سوراخ، داغ یا با حلال چسب‌کاری شود.</li><li>بالک‌ها سبک، غیرفلزی، موازی محور و متقارن نصب می‌شوند.</li><li>دماغه نرم و غیرنوک‌تیز است و کپسول روی ته بطری سوار می‌شود.</li><li>کنترل کیفیت و ساخت قطعات یدک، بخشی از کار مهندسی است.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>چرا نباید روی بطری فشار از چسب حرارتی استفاده کرد؟</li><li>محیط بطری ۲۸ سانتی‌متر است. برای سه بالک، فاصله آن‌ها روی محیط چقدر است؟ برای چهار بالک؟</li><li>چرا کنگره‌های کارتن‌پلاست باید موازی محور بدنه باشند؟</li><li>چرا لبه پایینی بالک‌ها نباید هم‌تراز با دهانه بطری باشد؟</li><li>سه مورد از کنترل کیفیت را که به ایمنی مربوط‌اند، نام ببرید.</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>پرتابگر تیم را بسازید، جرم و CG و CP آن را بسنجید و فهرست کنترل کیفیت را کامل کنید. از مراحل ساخت عکس بگیرید.</div></div>"}, {"t": "ساخت سکوی پرتاب", "n": "فصل ۸", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>اجزای سکوی پرتاب و الزامات شیوه‌نامه</li><li>ساخت سکوی تک‌پرتابگر با رهاساز بست کمربندی</li><li>مسیر هوا: پمپ، شیر یک‌طرفه، فشارسنج و شیر تخلیه</li><li>ساخت سکوی چهاربوستری با رهاساز هم‌زمان</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۸<br>۹۰ دقیقه + کار عملی<br>معیار داوری ۵ (۶ امتیاز) و ۹</div></div>\n<p>سکوی پرتاب، پرتابگر را راست نگه می‌دارد، اجازه می‌دهد آن را از راه دور پر از هوا کنید و در لحظه دلخواه رها کنید. شیوه‌نامه سکویی <b>پایدار و مقاوم، با فشارسنج، ضامن ایمنی و رهاساز از راه دور</b> می‌خواهد. در این فصل دو سکو می‌سازیم: سکوی تک‌پرتابگر و سکوی چهاربوستری.</p><h2>اجزای سکو</h2><div class=\"tbl\"><table class=\"kv\"><tr><td>پایه</td><td>صفحه چوبی ضخیم یا قاب لوله‌ای با سه یا چهار پایه گسترده؛ با میخ یا وزنه به زمین مهار می‌شود تا در باد یا هنگام پرتاب جابه‌جا نشود.</td></tr><tr><td>لوله پرتاب</td><td>لوله‌ای (معمولاً PVC با قطر خارجی حدود ۲۰ میلی‌متر) که از درون دهانه بطری وارد آن می‌شود، بطری را هم‌راستا نگه می‌دارد و هوا را به آن می‌رساند.</td></tr><tr><td>آب‌بندی</td><td>اورینگ (حلقه لاستیکی) دور لوله پرتاب یا یک واشر لاستیکی که دهانه بطری روی آن می‌نشیند تا آب و هوا نشت نکند.</td></tr><tr><td>رهاساز</td><td>سازوکاری که دهانه بطری را نگه می‌دارد و با کشیدن یک طناب از راه دور آزاد می‌کند.</td></tr><tr><td>ضامن ایمنی</td><td>میخ یا گیره‌ای که تا لحظه آخر رهاساز را قفل می‌کند تا کشیده شدن تصادفی طناب، پرتابگر را رها نکند.</td></tr><tr><td>مسیر هوا</td><td>پمپ، شلنگ بلند، شیر یک‌طرفه، شیر تخلیه و فشارسنج.</td></tr></table></div><h2>رهاساز بست کمربندی</h2><p>رایج‌ترین و ارزان‌ترین رهاساز، <b>رهاساز بست کمربندی</b> است. حلقه‌ای از ۸ تا ۱۲ بست کمربندی (بست پلاستیکی) دور لوله پرتاب بسته می‌شود؛ سرِ پهن بست‌ها رو به بالا قرار می‌گیرد و لبه گردن بطری را می‌گیرد. یک لوله کوتاه بزرگ‌تر (غلاف) دور بست‌ها بالا کشیده می‌شود و آن‌ها را بسته نگه می‌دارد. وقتی غلاف با طناب به پایین کشیده شود، بست‌ها از هم باز می‌شوند و بطری آزاد می‌شود.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 330\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"la\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"330\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#c9a26b\" height=\"20\" rx=\"4\" stroke=\"#8a6d3b\" width=\"300\" x=\"120\" y=\"275\"></rect><rect fill=\"#d9e2ee\" height=\"185\" stroke=\"#1B2A4A\" width=\"12\" x=\"264\" y=\"90\"></rect><rect fill=\"#e8f1fb\" height=\"120\" opacity=\".85\" rx=\"20\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"68\" x=\"236\" y=\"60\"></rect><rect fill=\"#b9c6d8\" height=\"16\" stroke=\"#1B2A4A\" width=\"24\" x=\"258\" y=\"175\"></rect><line stroke=\"#333\" stroke-width=\"2\" x1=\"255.0\" x2=\"255.0\" y1=\"192.0\" y2=\"222.0\"></line><line stroke=\"#333\" stroke-width=\"2\" x1=\"265.0\" x2=\"265.0\" y1=\"192.0\" y2=\"222.0\"></line><line stroke=\"#333\" stroke-width=\"2\" x1=\"275.0\" x2=\"275.0\" y1=\"192.0\" y2=\"222.0\"></line><line stroke=\"#333\" stroke-width=\"2\" x1=\"285.0\" x2=\"285.0\" y1=\"192.0\" y2=\"222.0\"></line><rect fill=\"#8fb4d8\" height=\"34\" opacity=\".9\" rx=\"3\" stroke=\"#1B2A4A\" width=\"40\" x=\"250\" y=\"212\"></rect><line stroke=\"#a0522d\" stroke-width=\"2\" x1=\"290.0\" x2=\"520.0\" y1=\"240.0\" y2=\"300.0\"></line><text fill=\"#a0522d\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"525\" y=\"304\">طناب رهاساز (≥ ۵ متر)</text><line stroke=\"#1B2A4A\" stroke-width=\"3\" x1=\"270.0\" x2=\"270.0\" y1=\"275.0\" y2=\"300.0\"></line><path d=\"M270,300 L120,300\" fill=\"none\" stroke=\"#1B2A4A\" stroke-width=\"5\"></path><circle cx=\"80\" cy=\"300\" fill=\"#fff\" r=\"14\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" x=\"80\" y=\"325\">فشارسنج و پمپ</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"230.0\" x2=\"120.0\" y1=\"110.0\" y2=\"110.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"114\" y=\"114\">بطری (پرتابگر)</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"230.0\" x2=\"120.0\" y1=\"150.0\" y2=\"150.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"114\" y=\"154\">لوله پرتاب</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"230.0\" x2=\"120.0\" y1=\"200.0\" y2=\"200.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"114\" y=\"204\">حلقه بست‌های کمربندی</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"230.0\" x2=\"120.0\" y1=\"228.0\" y2=\"228.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"114\" y=\"232\">غلاف رهاساز</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"230.0\" x2=\"120.0\" y1=\"258.0\" y2=\"258.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"114\" y=\"262\">میخ ضامن ایمنی</text><rect fill=\"#C0392B\" height=\"5\" width=\"22\" x=\"290\" y=\"252\"></rect><line stroke=\"#C0392B\" stroke-width=\"1.5\" x1=\"312.0\" x2=\"340.0\" y1=\"254.0\" y2=\"258.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"start\" x=\"600\" y=\"60\">رهاساز بست کمربندی:</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"600\" y=\"85\">سر بست‌ها لبه دهانه بطری را می‌گیرد</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"600\" y=\"107\">و غلاف آن‌ها را بسته نگه می‌دارد.</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"600\" y=\"129\">با کشیدن طناب، غلاف پایین می‌رود</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"600\" y=\"151\">و بست‌ها باز می‌شوند.</text></svg><figcaption>شکل ۸-۱: سکوی تک‌پرتابگر با رهاساز بست کمربندی.</figcaption></figure><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:34%\">قطعه</th><th style=\"width:46%\">مشخصات پیشنهادی</th><th style=\"width:20%\">تعداد</th></tr><tr><td class=\"l\">صفحه پایه</td><td class=\"l\">تخته یا ام‌دی‌اف ضخیم حدود ۴۰ × ۴۰ سانتی‌متر</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">لوله پرتاب</td><td class=\"l\">لوله PVC با قطر خارجی ۲۰ میلی‌متر، طول ۲۵ تا ۳۰ سانتی‌متر</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">اتصالات</td><td class=\"l\">سه‌راهی یا زانویی PVC، بوشن، چسب PVC (فقط برای لوله‌ها)</td><td class=\"l\">به اندازه لازم</td></tr><tr><td class=\"l\">اورینگ</td><td class=\"l\">اندازه‌ای که دور لوله پرتاب بنشیند و درون دهانه بطری آب‌بندی کند</td><td class=\"l\">۲</td></tr><tr><td class=\"l\">بست کمربندی</td><td class=\"l\">طول حدود ۱۵ تا ۲۰ سانتی‌متر</td><td class=\"l\">۸ تا ۱۲</td></tr><tr><td class=\"l\">غلاف رهاساز</td><td class=\"l\">تکه لوله PVC با قطر داخلی کمی بزرگ‌تر از حلقه بست‌ها، طول حدود ۵ سانتی‌متر</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">شیر یک‌طرفه و والو</td><td class=\"l\">والو تیوپ دوچرخه یا خودرو (والو شریدر) و شیر یک‌طرفه هوا</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">شیر تخلیه</td><td class=\"l\">شیر کوچک یا والو قابل باز شدن برای خالی کردن فشار</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">فشارسنج</td><td class=\"l\">فشارسنج با بازه ۰ تا ۷ یا ۱۰ بار</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">شلنگ</td><td class=\"l\">شلنگ پمپ یا شلنگ هوای مقاوم به طول دست‌کم ۵ متر</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">طناب رهاساز</td><td class=\"l\">طناب محکم به طول دست‌کم ۵ متر</td><td class=\"l\">۱</td></tr><tr><td class=\"l\">پمپ</td><td class=\"l\">پمپ پایی یا دستی دوچرخه با فشارسنج</td><td class=\"l\">۱</td></tr></table></div><h3>گام‌های ساخت سکوی تک‌پرتابگر</h3><ol class=\"steps\"><li><span class=\"sn\">۱</span><div><b>پایه:</b> لوله پرتاب را با اتصالات PVC به صفحه پایه وصل کنید؛ لوله باید کاملاً عمود (یا با زاویه دلخواه کمی از قائم) و محکم باشد. انتهای پایینی لوله به مسیر هوا وصل می‌شود.</div></li><li><span class=\"sn\">۲</span><div><b>آب‌بندی:</b> اورینگ را روی لوله پرتاب، در ارتفاعی که دهانه بطری روی آن می‌نشیند، قرار دهید. بطری را روی لوله بکشید؛ باید سفت اما بدون زور وارد شود.</div></li><li><span class=\"sn\">۳</span><div><b>حلقه بست‌ها:</b> بست‌ها را دور لوله، زیر جای گردن بطری، با یک حلقه بست یا نوار چسب به لوله ببندید؛ سر بست‌ها رو به بالا و طوری که وقتی جمع شوند، روی لبه گردن بطری قرار گیرند.</div></li><li><span class=\"sn\">۴</span><div><b>غلاف:</b> غلاف را از پایین روی بست‌ها بکشید تا سر بست‌ها دور گردن بطری جمع شوند. بطری اکنون نباید با کشیدن به بالا آزاد شود.</div></li><li><span class=\"sn\">۵</span><div><b>طناب و ضامن:</b> طناب را به غلاف ببندید و از زیر یک قرقره یا حلقه روی پایه رد کنید تا کشیدن آن، غلاف را به پایین ببرد. یک سوراخ در غلاف و لوله ایجاد کنید و یک میخ ضامن (با نوار رنگی بلند) از آن رد کنید تا غلاف تا لحظه برداشتن ضامن قفل بماند.</div></li><li><span class=\"sn\">۶</span><div><b>مسیر هوا:</b> شلنگ بلند را از انتهای لوله پرتاب به شیر یک‌طرفه، شیر تخلیه و فشارسنج و سپس به پمپ وصل کنید (شکل ۸-۲).</div></li><li><span class=\"sn\">۷</span><div><b>آزمون:</b> بطری پر از آب را روی سکو بگذارید و فشار را تا ۵ بار ببرید؛ نشتی و استحکام را بررسی کنید. سپس فشار را با شیر تخلیه خالی کنید و رهاساز را بدون فشار چند بار امتحان کنید.</div></li></ol><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 190\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"pp\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"190\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#fff\" height=\"44\" rx=\"8\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"90\" x=\"555\" y=\"60\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"600\" y=\"88\">پمپ با فشارسنج</text><line marker-end=\"url(#pp)\" stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"553.0\" x2=\"529.0\" y1=\"82.0\" y2=\"82.0\"></line><rect fill=\"#fff\" height=\"44\" rx=\"8\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"90\" x=\"435\" y=\"60\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"480\" y=\"88\">شلنگ بلند ≥ ۵ متر</text><line marker-end=\"url(#pp)\" stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"433.0\" x2=\"419.0\" y1=\"82.0\" y2=\"82.0\"></line><rect fill=\"#fff\" height=\"44\" rx=\"8\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"90\" x=\"325\" y=\"60\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"370\" y=\"88\">شیر یک‌طرفه</text><line marker-end=\"url(#pp)\" stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"323.0\" x2=\"319.0\" y1=\"82.0\" y2=\"82.0\"></line><rect fill=\"#FDECEA\" height=\"44\" rx=\"8\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"90\" x=\"225\" y=\"60\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"270\" y=\"88\">شیر تخلیه</text><line marker-end=\"url(#pp)\" stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"223.0\" x2=\"219.0\" y1=\"82.0\" y2=\"82.0\"></line><rect fill=\"#fff\" height=\"44\" rx=\"8\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"90\" x=\"125\" y=\"60\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"170\" y=\"88\">فشارسنج سکو</text><line marker-end=\"url(#pp)\" stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"123.0\" x2=\"119.0\" y1=\"82.0\" y2=\"82.0\"></line><rect fill=\"#fff\" height=\"44\" rx=\"8\" stroke=\"#1B2A4A\" stroke-width=\"1.5\" width=\"90\" x=\"25\" y=\"60\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"70\" y=\"88\">لوله پرتاب</text><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"140\">مسیر هوا از پمپ تا پرتابگر</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"middle\" x=\"345\" y=\"165\">شیر تخلیه برای خالی کردن ایمن فشار در صورت لغو پرتاب الزامی است</text></svg><figcaption>شکل ۸-۲: مسیر هوا از پمپ تا پرتابگر.</figcaption></figure><div class=\"box warn\"><div class=\"box-t\">شیر تخلیه را فراموش نکنید</div><div>اگر پرتاب لغو شود (مثلاً رهاساز گیر کند یا باد شدید شود)، نباید به پرتابگر تحت فشار نزدیک شوید. شیر تخلیه که در انتهای شلنگ، کنار اپراتور است، اجازه می‌دهد فشار را از راه دور و آرام خالی کنید. نزدیک شدن به پرتابگر تحت فشار، نقض الزام ستاره‌دار است.</div></div><div class=\"box tip\"><div class=\"box-t\">لوله پرتاب بلندتر، رانش بیشتر</div><div>وقتی بطری روی لوله پرتاب بلندی سوار است، در چند سانتی‌متر اول، هوا از لوله به بطری فشار می‌آورد و آب بیرون نمی‌رود؛ بطری مانند پیستون روی لوله سر می‌خورد و سرعت اولیه بیشتری می‌گیرد. لوله پرتاب ۲۰ تا ۳۰ سانتی‌متری درون بطری، ارتفاع را به‌طور محسوس بیشتر و پرواز اولیه را هم‌راستاتر می‌کند.</div></div><h2>سکوی چهاربوستری</h2><p>اگر ماژول بوستر را انتخاب کرده‌اید، به سکویی نیاز دارید که پرتابگر اصلی و دو تا چهار بوستر را هم‌زمان نگه دارد، با فشار برابر پر کند و <b>دقیقاً هم‌زمان</b> رها کند. اگر یک بوستر حتی کسری از ثانیه دیرتر رها شود، رانش نامتقارن پرتابگر را منحرف می‌کند. ساخت این سکو دقت بیشتری می‌خواهد، اما با همان قطعات سکوی تک‌پرتابگر انجام می‌شود.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 300\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"qp\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"300\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#f3e3c8\" height=\"220\" rx=\"10\" stroke=\"#8a6d3b\" width=\"220\" x=\"90\" y=\"40\"></rect><circle cx=\"200\" cy=\"150\" fill=\"#e8f1fb\" r=\"34\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" x=\"200\" y=\"155\">اصلی</text><circle cx=\"272\" cy=\"150\" fill=\"#fff\" r=\"26\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\" x=\"272\" y=\"154\">بوستر</text><circle cx=\"200\" cy=\"222\" fill=\"#fff\" r=\"26\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\" x=\"200\" y=\"226\">بوستر</text><circle cx=\"128\" cy=\"150\" fill=\"#fff\" r=\"26\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\" x=\"128\" y=\"154\">بوستر</text><circle cx=\"200\" cy=\"78\" fill=\"#fff\" r=\"26\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\" x=\"200\" y=\"82\">بوستر</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"200\" y=\"285\">نمای بالا</text><rect fill=\"#9fb0c6\" height=\"16\" rx=\"6\" width=\"220\" x=\"370\" y=\"142\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"4\" x1=\"380.0\" x2=\"380.0\" y1=\"142.0\" y2=\"80.0\"></line><rect fill=\"#fff\" height=\"20\" rx=\"3\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"20\" x=\"370\" y=\"60\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"4\" x1=\"430.0\" x2=\"430.0\" y1=\"142.0\" y2=\"80.0\"></line><rect fill=\"#fff\" height=\"20\" rx=\"3\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"20\" x=\"420\" y=\"60\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"4\" x1=\"480.0\" x2=\"480.0\" y1=\"142.0\" y2=\"80.0\"></line><rect fill=\"#e8f1fb\" height=\"20\" rx=\"3\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"20\" x=\"470\" y=\"60\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"4\" x1=\"530.0\" x2=\"530.0\" y1=\"142.0\" y2=\"80.0\"></line><rect fill=\"#fff\" height=\"20\" rx=\"3\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"20\" x=\"520\" y=\"60\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"4\" x1=\"580.0\" x2=\"580.0\" y1=\"142.0\" y2=\"80.0\"></line><rect fill=\"#fff\" height=\"20\" rx=\"3\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"20\" x=\"570\" y=\"60\"></rect><line marker-end=\"url(#qp)\" stroke=\"#1B2A4A\" stroke-width=\"4\" x1=\"480.0\" x2=\"480.0\" y1=\"158.0\" y2=\"220.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"490\" y=\"210\">از پمپ</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"480\" y=\"45\">لوله پرتاب: ۴ بوستر + اصلی</text><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"480\" y=\"275\">چندراهه: هوا از یک ورودی به پنج لوله پرتاب؛ فشار همه یکسان</text></svg><figcaption>شکل ۸-۳: جانمایی پنج لوله پرتاب (نمای بالا) و چندراهه هوا.</figcaption></figure><h3>۱. جانمایی</h3><p>لوله پرتاب اصلی در مرکز و چهار لوله پرتاب بوستر در چهار طرف آن با زاویه ۹۰ درجه قرار می‌گیرند. فاصله مرکز هر لوله بوستر از مرکز لوله اصلی، برابر «شعاع بطری اصلی + شعاع بطری بوستر + ۵ تا ۱۰ میلی‌متر» است؛ مثلاً برای دو بطری ۹ سانتی‌متری، حدود ۹٫۵ سانتی‌متر. ابتدا پرتابگر کامل (اصلی و بوسترهای بسته‌شده به آن) را بسازید و فاصله دقیق دهانه‌ها را از روی خود آن اندازه بگیرید؛ سپس جای لوله‌ها را روی صفحه پایه علامت بزنید. برای دو یا سه بوستر، همین کار را با زاویه ۱۸۰ یا ۱۲۰ درجه انجام دهید.</p><h3>۲. چندراهه هوا</h3><p>هر پنج لوله پرتاب باید از یک ورودی هوا تغذیه شوند تا فشار همه یکسان باشد. یک لوله افقی PVC (یا چند سه‌راهی پشت سر هم) زیر صفحه پایه، هوا را به پنج لوله عمودی می‌رساند. همه اتصالات را با چسب PVC محکم کنید و پیش از هر چیز، کل سکو را با بطری‌های پر از آب تا ۵ بار آزمون نشتی کنید.</p><div class=\"box tip\"><div class=\"box-t\">همه بطری‌ها از یک هوا</div><div>چون همه لوله‌ها به هم راه دارند، تا وقتی بطری‌ها روی سکو هستند، فشار همه یکسان است. اما پس از رهاسازی، باید همه هم‌زمان جدا شوند؛ وگرنه هوای بطری‌های باقی‌مانده از لوله‌های باز بیرون می‌زند.</div></div><h3>۳. رهاساز هم‌زمان</h3><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 270\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"sr\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#C0392B\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"270\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#C0392B\" height=\"14\" opacity=\".85\" rx=\"5\" width=\"390\" x=\"150\" y=\"180\"></rect><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"220\">صفحه رهاساز مشترک</text><rect fill=\"#d9e2ee\" height=\"120\" stroke=\"#1B2A4A\" width=\"12\" x=\"184\" y=\"60\"></rect><rect fill=\"#8fb4d8\" height=\"55\" rx=\"3\" stroke=\"#1B2A4A\" width=\"34\" x=\"173\" y=\"125\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"190.0\" x2=\"190.0\" y1=\"194.0\" y2=\"194.0\"></line><rect fill=\"#d9e2ee\" height=\"120\" stroke=\"#1B2A4A\" width=\"12\" x=\"264\" y=\"60\"></rect><rect fill=\"#8fb4d8\" height=\"55\" rx=\"3\" stroke=\"#1B2A4A\" width=\"34\" x=\"253\" y=\"125\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"270.0\" x2=\"270.0\" y1=\"194.0\" y2=\"194.0\"></line><rect fill=\"#d9e2ee\" height=\"120\" stroke=\"#1B2A4A\" width=\"12\" x=\"339\" y=\"60\"></rect><rect fill=\"#8fb4d8\" height=\"55\" rx=\"3\" stroke=\"#1B2A4A\" width=\"34\" x=\"328\" y=\"125\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"345.0\" x2=\"345.0\" y1=\"194.0\" y2=\"194.0\"></line><rect fill=\"#d9e2ee\" height=\"120\" stroke=\"#1B2A4A\" width=\"12\" x=\"414\" y=\"60\"></rect><rect fill=\"#8fb4d8\" height=\"55\" rx=\"3\" stroke=\"#1B2A4A\" width=\"34\" x=\"403\" y=\"125\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"420.0\" x2=\"420.0\" y1=\"194.0\" y2=\"194.0\"></line><rect fill=\"#d9e2ee\" height=\"120\" stroke=\"#1B2A4A\" width=\"12\" x=\"494\" y=\"60\"></rect><rect fill=\"#8fb4d8\" height=\"55\" rx=\"3\" stroke=\"#1B2A4A\" width=\"34\" x=\"483\" y=\"125\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"500.0\" x2=\"500.0\" y1=\"194.0\" y2=\"194.0\"></line><line marker-end=\"url(#sr)\" stroke=\"#a0522d\" stroke-width=\"2.5\" x1=\"345.0\" x2=\"345.0\" y1=\"194.0\" y2=\"255.0\"></line><text fill=\"#a0522d\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"355\" y=\"250\">یک طناب برای همه</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"35\">همه غلاف‌ها به یک صفحه وصل‌اند؛ با یک کشش، هر پنج پرتابگر هم‌زمان رها می‌شوند</text></svg><figcaption>شکل ۸-۴: رهاساز هم‌زمان با صفحه مشترک.</figcaption></figure><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>برای هر لوله پرتاب، یک حلقه بست کمربندی مانند سکوی تک‌پرتابگر بسازید.</div></li><li><span class=\"sn\">۲</span><div>به جای پنج غلاف جداگانه، یک <b>صفحه رهاساز</b> (تخته نازک یا ورق پلاستیکی محکم) با پنج سوراخ بسازید که دور هر حلقه بست، نقش غلاف را داشته باشد؛ یا پنج غلاف کوتاه را به یک صفحه بچسبانید.</div></li><li><span class=\"sn\">۳</span><div>صفحه رهاساز را روی چهار میله راهنما (مثلاً پیچ‌های بلند) سوار کنید تا فقط بالا و پایین برود و کج نشود.</div></li><li><span class=\"sn\">۴</span><div>یک طناب به مرکز صفحه ببندید و از زیر یک قرقره روی پایه رد کنید. با کشیدن طناب، صفحه پایین می‌رود و هر پنج حلقه هم‌زمان باز می‌شوند.</div></li><li><span class=\"sn\">۵</span><div>ضامن ایمنی را از صفحه رهاساز رد کنید تا تا لحظه آخر قفل باشد.</div></li><li><span class=\"sn\">۶</span><div>رهاساز را بدون فشار و با بطری‌های خالی ده‌ها بار آزمون کنید؛ از آن فیلم آهسته بگیرید و ببینید همه بطری‌ها هم‌زمان آزاد می‌شوند.</div></li></ol><div class=\"box out\"><div class=\"box-t\">پیوند با داوری</div><div>معیار «سکوی پرتاب» ۶ امتیاز دارد: پایداری، فشارسنج، ضامن ایمنی و رهاساز از راه دور. معیار «بوستر» (۷ امتیاز) عملکرد هم‌زمان و درست بوسترها را ارزیابی می‌کند؛ رهاساز هم‌زمان، کلید آن است.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>سکو باید پایدار، با فشارسنج، ضامن ایمنی و رهاساز از راه دور باشد.</li><li>رهاساز بست کمربندی ساده، ارزان و قابل اطمینان است.</li><li>مسیر هوا: پمپ، شلنگ ≥ ۵ متر، شیر یک‌طرفه، شیر تخلیه و فشارسنج.</li><li>در سکوی چندبوستری، چندراهه فشار را یکسان و صفحه رهاساز مشترک رهاسازی را هم‌زمان می‌کند.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>چهار جزء الزامی سکو طبق شیوه‌نامه را نام ببرید.</li><li>رهاساز بست کمربندی چگونه کار می‌کند؟ با یک شکل توضیح دهید.</li><li>چرا شیر تخلیه باید کنار اپراتور باشد، نه کنار سکو؟</li><li>قطر بطری اصلی ۱۰ و قطر بوستر ۸ سانتی‌متر است. فاصله مرکز لوله بوستر از لوله اصلی تقریباً چقدر است؟</li><li>چرا در سکوی چهاربوستری همه لوله‌ها باید از یک ورودی هوا بگیرند؟</li><li>اگر یکی از چهار بوستر دیرتر رها شود، چه اتفاقی برای پرواز می‌افتد؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>سکوی تک‌پرتابگر تیم را بسازید و آزمون نشتی و رهاساز را انجام دهید. اگر ماژول بوستر دارید، سکوی چندبوستری را بسازید و رهاسازی هم‌زمان را با فیلم آهسته بیازمایید.</div></div>"}, {"t": "کپسول مأموریت و محافظت از تخم‌مرغ", "n": "فصل ۹", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>الزامات کپسول در شیوه‌نامه</li><li>فیزیک ضربه: سرعت، فاصله توقف و شتاب</li><li>روش‌های ضربه‌گیری و نگه‌داشتن تخم‌مرغ</li><li>آزمون رهاسازی کپسول</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۹<br>۹۰ دقیقه<br>معیار داوری ۷ (۹ امتیاز)</div></div>\n<p>تخم‌مرغ خام سرنشین مأموریت شماست؛ شکننده و بی‌دفاع. کپسول باید آن را در برابر شتاب شدید پرتاب، تکان‌های پرواز، ضربه باز شدن چتر و برخورد با زمین محافظت کند. «سلامت محموله» به‌تنهایی ۱۲ امتیاز دارد.</p><h2>الزامات کپسول</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 300\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"300\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#fff\" height=\"230\" rx=\"18\" stroke=\"#1B2A4A\" stroke-width=\"3\" width=\"140\" x=\"160\" y=\"40\"></rect><line stroke=\"#1B2A4A\" stroke-width=\"3\" x1=\"160.0\" x2=\"300.0\" y1=\"150.0\" y2=\"150.0\"></line><rect fill=\"#fde9c8\" height=\"92\" rx=\"10\" width=\"120\" x=\"170\" y=\"50\"></rect><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"170.0\" x2=\"200.0\" y1=\"60.0\" y2=\"70.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"290.0\" x2=\"260.0\" y1=\"60.0\" y2=\"70.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"170.0\" x2=\"200.0\" y1=\"82.0\" y2=\"92.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"290.0\" x2=\"260.0\" y1=\"82.0\" y2=\"92.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"170.0\" x2=\"200.0\" y1=\"104.0\" y2=\"114.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"290.0\" x2=\"260.0\" y1=\"104.0\" y2=\"114.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"170.0\" x2=\"200.0\" y1=\"126.0\" y2=\"136.0\"></line><line stroke=\"#c9a26b\" stroke-width=\"2\" x1=\"290.0\" x2=\"260.0\" y1=\"126.0\" y2=\"136.0\"></line><ellipse cx=\"230\" cy=\"96\" fill=\"#fffaf0\" rx=\"20\" ry=\"27\" stroke=\"#b08c5a\" stroke-width=\"2\"></ellipse><rect fill=\"#e3ecf7\" height=\"100\" rx=\"8\" width=\"120\" x=\"170\" y=\"160\"></rect><rect fill=\"#2a6f3a\" height=\"30\" rx=\"4\" width=\"80\" x=\"190\" y=\"175\"></rect><rect fill=\"#555\" height=\"35\" rx=\"3\" width=\"40\" x=\"195\" y=\"215\"></rect><rect fill=\"#C0392B\" height=\"14\" rx=\"5\" width=\"160\" x=\"150\" y=\"30\"></rect><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"302.0\" x2=\"370.0\" y1=\"37.0\" y2=\"37.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"376\" y=\"41\">درِ مهارشده</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"302.0\" x2=\"370.0\" y1=\"96.0\" y2=\"96.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"376\" y=\"100\">بخش محموله: تخم‌مرغ معلق در ضربه‌گیر</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"302.0\" x2=\"370.0\" y1=\"190.0\" y2=\"190.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"376\" y=\"194\">بخش تجهیزات: برد الکترونیک</text><line stroke=\"#8a97ab\" stroke-width=\"1\" x1=\"302.0\" x2=\"370.0\" y1=\"232.0\" y2=\"232.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"376\" y=\"236\">باتری یا وزنه معادل</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"middle\" x=\"230\" y=\"290\">برش کپسول مأموریت</text></svg><figcaption>شکل ۹-۱: کپسول مأموریت با دو بخش مجزا.</figcaption></figure><ul class=\"ul\"><li>کپسول دو بخش مجزا دارد: <b>بخش محموله</b> برای تخم‌مرغ و <b>بخش تجهیزات</b> برای الکترونیک، باتری یا وزنه معادل. حتی اگر ماژول الکترونیکی ندارید، بخش تجهیزات با وزنه‌ای هم‌جرم ساخته می‌شود تا کپسول همانند یک کپسول واقعی طراحی شود.</li><li>درِ کپسول در طول پرتاب <b>کاملاً مهار</b> باشد.</li><li>ضربه‌گیری با <b>طراحی داخلی</b> کپسول انجام شود. پوشاندن مستقیم تخم‌مرغ با چسب، رنگ، نوار چسب و مانند آن مجاز نیست.</li><li>پس از فرود، تخم‌مرغ باید بیرون آورده و سالم بودن آن در ویدئوی پیوسته پرواز رسمی نشان داده شود.</li></ul><h2>فیزیک ضربه</h2><p>چرا افتادن تخم‌مرغ روی فرش کمتر خطرناک است تا روی سنگ؟ چون فرش فاصله بیشتری برای توقف می‌دهد. هرچه فاصله توقف بیشتر باشد، <b>شتاب کاهنده</b> کمتر و نیرویی که به تخم‌مرغ وارد می‌شود کمتر است:</p><div class=\"fm\" dir=\"ltr\">a = v² ÷ (2 s) ,   F = m × a</div><p>v سرعت برخورد، s فاصله توقف (مقداری که ضربه‌گیر فشرده می‌شود) و a شتاب کاهنده است.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 640 260\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#fff\" height=\"260\" rx=\"10\" stroke=\"#d9e2ee\" width=\"640\"></rect><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"215.0\" y2=\"215.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"219.0\">0</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"171.7\" y2=\"171.7\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"175.7\">20</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"128.3\" y2=\"128.3\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"132.3\">40</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"85.0\" y2=\"85.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"89.0\">60</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"41.7\" y2=\"41.7\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"45.7\">80</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"70.0\" y=\"231\">0</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"180.0\" y=\"231\">2</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"290.0\" y=\"231\">4</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"400.0\" y=\"231\">6</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"510.0\" y=\"231\">8</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"620.0\" y=\"231\">10</text><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"620\" y1=\"215\" y2=\"215\"></line><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"70\" y1=\"20\" y2=\"215\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"254\">فاصله توقف (سانتی‌متر)</text><text fill=\"#1B2A4A\" font-family=\"BNazanin\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" transform=\"rotate(-90 16 117.5)\" x=\"16\" y=\"117.5\">شتاب کاهنده (برابر g)</text><polyline fill=\"none\" points=\"125.0,38.1 180.0,126.6 235.0,156.0 290.0,170.8 345.0,179.6 400.0,185.5 510.0,192.9 620.0,197.3\" stroke=\"#C0392B\" stroke-width=\"2.5\"></polyline></svg><figcaption>شکل ۹-۲: شتاب کاهنده برای برخورد با سرعت ۴ متر بر ثانیه بر حسب فاصله توقف.</figcaption></figure><div class=\"ex\"><div class=\"ex-t\">مثال ۹-۱: اهمیت فاصله توقف</div><p>کپسول با سرعت ۴ متر بر ثانیه به زمین می‌رسد. جرم تخم‌مرغ ۶۰ گرم است.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>فاصله توقف ۰٫۵ سانتی‌متر (بدون ضربه‌گیر)</td><td dir=\"ltr\">a = 16 ÷ 0.01 = 1600 m/s² ≈ 163 g</td></tr><tr><td>نیرو بر تخم‌مرغ</td><td dir=\"ltr\">F = 0.06 × 1600 = 96 N</td></tr><tr><td>فاصله توقف ۴ سانتی‌متر</td><td dir=\"ltr\">a = 16 ÷ 0.08 = 200 m/s² ≈ 20 g</td></tr><tr><td>نیرو بر تخم‌مرغ</td><td dir=\"ltr\">F = 0.06 × 200 = 12 N</td></tr></table></div><p>با ۴ سانتی‌متر فاصله توقف، نیرو ۸ برابر کمتر می‌شود. نیرو هم باید روی سطح بزرگی از تخم‌مرغ پخش شود، نه روی یک نقطه.</p></div><div class=\"box why\"><div class=\"box-t\">برای کنجکاوها: چرا تخم‌مرغ گاهی سخت است و گاهی شکننده؟</div><div>شکل گنبدی پوسته تخم‌مرغ، فشار آرام و پخش‌شده را بسیار خوب تحمل می‌کند؛ اگر یک تخم‌مرغ را میان کف دو دست از دو سر فشار دهید، به‌سختی می‌شکند. اما ضربه ناگهانی و نقطه‌ای (مانند برخورد با لبه سخت) آن را به‌راحتی می‌شکند. پس ضربه‌گیر باید نیرو را «آهسته» و «پخش‌شده» منتقل کند.</div></div><h2>روش‌های محافظت</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:22%\">روش</th><th style=\"width:46%\">چگونه کار می‌کند</th><th style=\"width:32%\">نکته</th></tr><tr><td class=\"l\">گهواره فومی</td><td class=\"l\">تخم‌مرغ در حفره‌ای از فوم یا اسفنج نرم که شکل آن را گرفته است، می‌نشیند.</td><td class=\"l\">فوم خیلی سخت، مانند سنگ عمل می‌کند</td></tr><tr><td class=\"l\">تعلیق</td><td class=\"l\">تخم‌مرغ در یک توری یا جیب پارچه‌ای با کش‌های لاستیکی از دیواره‌ها آویزان است.</td><td class=\"l\">تخم‌مرغ در ضربه نباید به دیواره بخورد</td></tr><tr><td class=\"l\">منطقه مچاله‌شونده</td><td class=\"l\">کف کپسول از ساختاری ساخته می‌شود که با ضربه له می‌شود: مخروط‌های کاغذی، نی‌های کنار هم، لانه‌زنبوری مقوایی.</td><td class=\"l\">یک‌بار مصرف؛ برای هر پرواز تعویض شود</td></tr><tr><td class=\"l\">کیسه هوا</td><td class=\"l\">بادکنک‌های کوچک یا پلاستیک حباب‌دار دور گهواره.</td><td class=\"l\">سبک؛ ممکن است بترکد</td></tr><tr><td class=\"l\">ترکیبی</td><td class=\"l\">تعلیق یا گهواره در بالا و منطقه مچاله‌شونده در کف.</td><td class=\"l\">بهترین نتیجه</td></tr></table></div><ul class=\"ul\"><li>تخم‌مرغ را <b>عمودی</b> (محور بلند در راستای حرکت) قرار دهید؛ دو سر آن مقاوم‌ترین بخش‌اند.</li><li>تخم‌مرغ باید در هر جهت دست‌کم ۲ تا ۳ سانتی‌متر فاصله از دیواره سخت داشته باشد.</li><li>ضربه‌گیر باید تخم‌مرغ را در شتاب شدید پرتاب هم نگه دارد؛ تخم‌مرغ نباید درون کپسول جابه‌جا شود.</li><li>کپسول سنگین‌تر به چتر بزرگ‌تر نیاز دارد؛ سبکی را فراموش نکنید.</li></ul><h2>درِ کپسول</h2><p>درِ کپسول باید در پرتاب، که شتاب حدود ۲۰ برابر گرانش است، و هنگام باز شدن ناگهانی چتر، باز نشود؛ اما پس از فرود، به‌راحتی باز شود تا تخم‌مرغ نشان داده شود. روش‌های ساده: در پیچی (مانند در ظرف)، در با دو میله قفل‌کننده پلاستیکی که از سوراخ‌های بدنه رد می‌شوند، یا در با کش لاستیکی محکم که روی قلاب‌ها کشیده می‌شود. نوار چسب کاغذی به‌تنهایی قابل اطمینان نیست.</p><h2>آزمون رهاسازی</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 260\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"dt\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><rect fill=\"#F5F8FC\" height=\"260\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#d9c7a8\" height=\"200\" width=\"40\" x=\"80\" y=\"40\"></rect><line stroke=\"#8a6d3b\" stroke-width=\"4\" x1=\"120.0\" x2=\"200.0\" y1=\"60.0\" y2=\"60.0\"></line><rect fill=\"#C0392B\" height=\"40\" rx=\"5\" width=\"30\" x=\"185\" y=\"66\"></rect><line marker-end=\"url(#dt)\" stroke=\"#1B2A4A\" stroke-dasharray=\"5 4\" stroke-width=\"1.5\" x1=\"200.0\" x2=\"200.0\" y1=\"115.0\" y2=\"225.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"210\" y=\"170\">ارتفاع رهاسازی</text><line stroke=\"#6b8a5a\" stroke-width=\"3\" x1=\"40.0\" x2=\"650.0\" y1=\"240.0\" y2=\"240.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"start\" x=\"600\" y=\"80\">آزمون رهاسازی کپسول:</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"600\" y=\"105\">سرعت برخورد بدون چتر از ارتفاع h:</text><text fill=\"#C0392B\" font-family=\"DejaVu Serif\" font-size=\"16\" text-anchor=\"middle\" x=\"480\" y=\"140\">v = √(2 g h)</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"600\" y=\"175\">از ۰٫۸ متر ≈ ۴ متر بر ثانیه</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"600\" y=\"198\">از ۱٫۸ متر ≈ ۶ متر بر ثانیه</text></svg><figcaption>شکل ۹-۳: آزمون رهاسازی کپسول.</figcaption></figure><p>برای آزمودن کپسول بدون پرتاب، آن را از ارتفاعی رها کنید که سرعت برخورد آن برابر سرعت فرود با چتر باشد. چون v = √(2gh)، برای سرعت ۴ متر بر ثانیه ارتفاع رهاسازی حدود ۰٫۸ متر و برای ۶ متر بر ثانیه حدود ۱٫۸ متر است. برای اطمینان، از ارتفاعی بالاتر از سرعت پیش‌بینی‌شده آزمون کنید.</p><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>کپسول را با تخم‌مرغ (ابتدا تخم‌مرغ آب‌پز یا بادکنک آب، سپس تخم‌مرغ خام) آماده کنید.</div></li><li><span class=\"sn\">۲</span><div>از ۱ متر رها کنید؛ کپسول را باز کنید و بررسی کنید.</div></li><li><span class=\"sn\">۳</span><div>ارتفاع را گام‌به‌گام به ۱٫۵، ۲ و ۲٫۵ متر برسانید.</div></li><li><span class=\"sn\">۴</span><div>هر آزمون را با ارتفاع، جنس زمین، جهت برخورد و نتیجه ثبت کنید.</div></li><li><span class=\"sn\">۵</span><div>کپسول را یک بار هم کج (روی لبه) رها کنید؛ در فرود واقعی، کپسول همیشه صاف به زمین نمی‌رسد.</div></li></ol><div class=\"ws-h\">کاربرگ ۹-۱: آزمون رهاسازی کپسول</div><div class=\"tbl wide\"><table class=\"wt blank\"><tr><th style=\"width:8%\">ردیف</th><th style=\"width:13%\">ارتفاع (m)</th><th style=\"width:16%\">سرعت برخورد (m/s)</th><th style=\"width:14%\">جنس زمین</th><th style=\"width:14%\">جهت برخورد</th><th style=\"width:15%\">وضعیت تخم‌مرغ</th><th style=\"width:20%\">اصلاح بعدی</th></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr></table></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>کپسول دو بخش (محموله و تجهیزات) و درِ مهارشده دارد؛ پوشاندن مستقیم تخم‌مرغ مجاز نیست.</li><li>شتاب کاهنده a = v² ÷ 2s؛ فاصله توقف بیشتر، نیروی کمتر.</li><li>گهواره، تعلیق، منطقه مچاله‌شونده و روش‌های ترکیبی، تخم‌مرغ را محافظت می‌کنند.</li><li>آزمون رهاسازی از ارتفاع h، سرعت برخورد √(2gh) را شبیه‌سازی می‌کند.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>سرعت برخورد جسمی که از ۱٫۲۵ متر رها شود چقدر است؟</li><li>کپسول با سرعت ۵ متر بر ثانیه برخورد می‌کند و ضربه‌گیر ۵ سانتی‌متر فشرده می‌شود. شتاب کاهنده چند برابر g است؟</li><li>چرا تخم‌مرغ را عمودی در کپسول قرار می‌دهیم؟</li><li>چرا پوشاندن مستقیم تخم‌مرغ با چسب ممنوع شده است؟ (به هدف مهندسی کپسول فکر کنید.)</li><li>دو روش ساده برای مهار درِ کپسول پیشنهاد کنید.</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>کپسول تیم را بسازید و آزمون رهاسازی را از دست‌کم سه ارتفاع انجام دهید. کاربرگ ۹-۱ را کامل کنید و از آزمون‌ها فیلم بگیرید؛ این یکی از سه آزمون زمینی الزامی است.</div></div>"}, {"t": "سامانه بازیابی و چتر نجات", "n": "فصل ۱۰", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>گزینه‌های بازیابی: چتر، نوار کندکننده و سازه جاذب انرژی</li><li>سرعت حد و محاسبه اندازه چتر</li><li>ساخت، تاکردن و بستن چتر</li><li>فعال‌سازی به‌موقع و آزمون چتر</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۰<br>۹۰ دقیقه<br>معیار داوری ۶ (۱۰ امتیاز)</div></div>\n<p>«سامانه بازیابی» از پرامتیازترین معیارهای داوری است (۱۰ امتیاز). چتری که دیر باز شود، در هم بپیچد یا بیش از حد کوچک باشد، همه زحمات تیم را با یک ضربه از بین می‌برد. در این فصل می‌آموزید چتر را حساب کنید، بسازید و مطمئن شوید در لحظه درست باز می‌شود.</p><h2>گزینه‌های بازیابی</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:22%\">سامانه</th><th style=\"width:46%\">چگونه کار می‌کند</th><th style=\"width:32%\">مناسب برای</th></tr><tr><td class=\"l\">چتر نجات</td><td class=\"l\">سطح بزرگ، پسای زیاد می‌سازد و سرعت را به چند متر بر ثانیه می‌رساند.</td><td class=\"l\">کپسول محموله؛ بهترین گزینه</td></tr><tr><td class=\"l\">نوار کندکننده</td><td class=\"l\">نوار بلند پلاستیکی رنگی که پشت جسم تاب می‌خورد و آن را کند می‌کند.</td><td class=\"l\">بدنه پرتابگر، بوسترها، قطعات سبک</td></tr><tr><td class=\"l\">سازه جاذب انرژی</td><td class=\"l\">ساختاری که با برخورد، خودش له می‌شود و انرژی را می‌گیرد.</td><td class=\"l\">کمک در کنار چتر</td></tr><tr><td class=\"l\">پره‌های چرخان</td><td class=\"l\">پره‌هایی که مانند بالگرد می‌چرخند و فرود را کند می‌کنند.</td><td class=\"l\">تیم‌های خلاق؛ پیچیده‌تر</td></tr></table></div><h2>سرعت حد</h2><p>وقتی کپسول با چتر پایین می‌آید، در ابتدا سرعتش زیاد می‌شود و پسای چتر هم با مجذور سرعت زیاد می‌شود. وقتی پسا با وزن برابر شد، نیروی کل صفر می‌شود و سرعت ثابت می‌ماند. به این سرعت، <b>سرعت حد</b> می‌گویند.</p><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 640 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#fff\" height=\"270\" rx=\"10\" stroke=\"#d9e2ee\" width=\"640\"></rect><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"225.0\" y2=\"225.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"229.0\">0</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"156.7\" y2=\"156.7\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"160.7\">50</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"88.3\" y2=\"88.3\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"92.3\">100</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"20.0\" y2=\"20.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"24.0\">150</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"70.0\" y=\"241\">0</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"180.0\" y=\"241\">2</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"290.0\" y=\"241\">4</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"400.0\" y=\"241\">6</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"510.0\" y=\"241\">8</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"620.0\" y=\"241\">10</text><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"620\" y1=\"225\" y2=\"225\"></line><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"70\" y1=\"20\" y2=\"225\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"264\">سرعت فرود (متر بر ثانیه)</text><text fill=\"#1B2A4A\" font-family=\"BNazanin\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" transform=\"rotate(-90 16 122.5)\" x=\"16\" y=\"122.5\">پسا نسبت به وزن (درصد)</text><polyline fill=\"none\" points=\"70.0,225.0 83.8,224.5 97.5,222.9 111.2,220.2 125.0,216.5 138.8,211.8 152.5,205.9 166.2,199.0 180.0,191.1 193.8,182.1 207.5,172.0 221.2,160.9 235.0,148.7 248.8,135.4 262.5,121.1 276.2,105.8 290.0,89.3 303.8,71.8 317.5,53.3 331.2,33.7 345.0,13.0 358.8,-8.7 372.5,-31.5 386.2,-55.3 400.0,-80.2 413.8,-106.2 427.5,-133.2 441.2,-161.3 455.0,-190.5 468.8,-220.7 482.5,-251.9 496.2,-284.3 510.0,-317.7 523.8,-352.1 537.5,-387.6 551.2,-424.2 565.0,-461.8 578.8,-500.5 592.5,-540.2 606.2,-581.0 620.0,-622.9\" stroke=\"#2A9DAE\" stroke-width=\"2.5\"></polyline><line stroke=\"#E0A93B\" stroke-dasharray=\"6 4\" stroke-width=\"2\" x1=\"70\" x2=\"620\" y1=\"92\" y2=\"92\"></line></svg><figcaption>شکل ۱۰-۱: پسای چتر نسبت به وزن؛ در سرعت حد، پسا برابر وزن است.</figcaption></figure><div class=\"fm\" dir=\"ltr\">D = ½ ρ v² C<sub>d</sub> A    و در سرعت حد: D = m g</div><div class=\"tbl\"><table class=\"kv\"><tr><td>ρ</td><td>چگالی هوا؛ حدود ۱٫۲ کیلوگرم بر متر مکعب (در شهرهای بلند مانند مشهد کمی کمتر، حدود ۱٫۱).</td></tr><tr><td>C<sub>d</sub></td><td>ضریب پسا؛ برای چتر ساده تخت حدود ۰٫۸ و برای چتر گنبدی حدود ۱٫۲ تا ۱٫۵.</td></tr><tr><td>A</td><td>مساحت چتر (متر مربع).</td></tr><tr><td>m</td><td>جرم کل آویزان از چتر (کیلوگرم).</td></tr></table></div><p>از برابری این دو، مساحت لازم برای سرعت حد دلخواه به دست می‌آید:</p><div class=\"fm\" dir=\"ltr\">A = 2 m g ÷ (ρ C<sub>d</sub> v²)</div><div class=\"ex\"><div class=\"ex-t\">مثال ۱۰-۱: اندازه چتر کپسول</div><p>جرم کپسول با تخم‌مرغ ۱۵۰ گرم است و سرعت فرود ۴ متر بر ثانیه می‌خواهیم. چتر تخت با C<sub>d</sub> = ۰٫۸.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>مساحت</td><td dir=\"ltr\">A = 2 × 0.15 × 9.8 ÷ (1.2 × 0.8 × 16) ≈ 0.19 m²</td></tr><tr><td>قطر چتر دایره‌ای</td><td dir=\"ltr\">D = √(4A ÷ π) ≈ 0.49 m ≈ 50 cm</td></tr><tr><td>ضلع چتر شش‌ضلعی هم‌مساحت</td><td dir=\"ltr\">s = √(A ÷ 2.6) ≈ 0.27 m</td></tr></table></div></div><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:25%\">جرم آویزان (گرم)</th><th style=\"width:25%\">قطر چتر برای ۴ m/s</th><th style=\"width:25%\">قطر چتر برای ۵ m/s</th><th style=\"width:25%\">قطر چتر برای ۶ m/s</th></tr><tr><td class=\"l\">۱۰۰</td><td class=\"l\">۴۰ سانتی‌متر</td><td class=\"l\">۳۲ سانتی‌متر</td><td class=\"l\">۲۷ سانتی‌متر</td></tr><tr><td class=\"l\">۱۵۰</td><td class=\"l\">۴۹ سانتی‌متر</td><td class=\"l\">۳۹ سانتی‌متر</td><td class=\"l\">۳۳ سانتی‌متر</td></tr><tr><td class=\"l\">۲۰۰</td><td class=\"l\">۵۷ سانتی‌متر</td><td class=\"l\">۴۵ سانتی‌متر</td><td class=\"l\">۳۸ سانتی‌متر</td></tr><tr><td class=\"l\">۳۰۰</td><td class=\"l\">۷۰ سانتی‌متر</td><td class=\"l\">۵۶ سانتی‌متر</td><td class=\"l\">۴۷ سانتی‌متر</td></tr></table></div><p class=\"hint\">جدول برای چتر تخت (C<sub>d</sub> = ۰٫۸) و ρ = ۱٫۲ است. سرعت واقعی را با آزمون رهاسازی از بلندی (مثلاً طبقه دوم، زیر نظر بزرگ‌تر) و زمان‌سنجی بسنجید.</p><div class=\"box warn\"><div class=\"box-t\">قطعات جداشونده</div><div>شیوه‌نامه می‌خواهد هر قطعه جداشونده (بدنه، بوستر، مرحله) با چتر، نوار کندکننده یا مهار به بدنه، با سرعت <b>کمتر از ۱۰ متر بر ثانیه</b> فرود آید. اگر کپسول جدا می‌شود، بدنه پرتابگر هم سامانه بازیابی خودش را لازم دارد.</div></div><h2>ساخت چتر</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 280\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"280\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><polygon fill=\"#FBF1DC\" points=\"295.3,195.0 200.0,250.0 104.7,195.0 104.7,85.0 200.0,30.0 295.3,85.0\" stroke=\"#9a6b10\" stroke-width=\"2\"></polygon><circle cx=\"200\" cy=\"140\" fill=\"#fff\" r=\"12\" stroke=\"#9a6b10\"></circle><circle cx=\"295.3\" cy=\"195.0\" fill=\"#C0392B\" opacity=\"1.00\" r=\"5.0\"></circle><circle cx=\"200.0\" cy=\"250.0\" fill=\"#C0392B\" opacity=\"1.00\" r=\"5.0\"></circle><circle cx=\"104.7\" cy=\"195.0\" fill=\"#C0392B\" opacity=\"1.00\" r=\"5.0\"></circle><circle cx=\"104.7\" cy=\"85.0\" fill=\"#C0392B\" opacity=\"1.00\" r=\"5.0\"></circle><circle cx=\"200.0\" cy=\"30.0\" fill=\"#C0392B\" opacity=\"1.00\" r=\"5.0\"></circle><circle cx=\"295.3\" cy=\"85.0\" fill=\"#C0392B\" opacity=\"1.00\" r=\"5.0\"></circle><line stroke=\"#1B2A4A\" stroke-dasharray=\"4 3\" stroke-width=\"1\" x1=\"104.7\" x2=\"295.3\" y1=\"140.0\" y2=\"140.0\"></line><text fill=\"#9a6b10\" font-family=\"Vazirmatn\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" x=\"200\" y=\"122\">سوراخ تخلیه</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"200\" y=\"275\">الگوی شش‌ضلعی</text><path d=\"M420,70 Q500,-26.0 580,70 Q540.0,64 500,70 Q460.0,64 420,70 Z\" fill=\"#E0A93B\" stroke=\"#9a6b10\"></path><rect fill=\"#C0392B\" height=\"36\" rx=\"5\" width=\"28\" x=\"486\" y=\"215\"></rect><line stroke=\"#6a5a3a\" stroke-width=\"1.2\" x1=\"420.0\" x2=\"500.0\" y1=\"70.0\" y2=\"215.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1.2\" x1=\"460.0\" x2=\"500.0\" y1=\"70.0\" y2=\"215.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1.2\" x1=\"500.0\" x2=\"500.0\" y1=\"70.0\" y2=\"215.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1.2\" x1=\"540.0\" x2=\"500.0\" y1=\"70.0\" y2=\"215.0\"></line><line stroke=\"#6a5a3a\" stroke-width=\"1.2\" x1=\"580.0\" x2=\"500.0\" y1=\"70.0\" y2=\"215.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"592\" y=\"150\">طول نخ‌ها ≈ ۱ تا ۱٫۵ برابر قطر</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"325\" y=\"70\">نقطه‌های قرمز: محل اتصال نخ</text></svg><figcaption>شکل ۱۰-۲: الگوی چتر شش‌ضلعی و نمای کناری.</figcaption></figure><ol class=\"steps\"><li><span class=\"sn\">۱</span><div><b>پارچه:</b> نایلون سبک (پارچه چتری)، کیسه زباله ضخیم یا پلاستیک نازک محکم. پارچه نایلونی بادوام‌تر است.</div></li><li><span class=\"sn\">۲</span><div><b>الگو:</b> یک شش‌ضلعی یا هشت‌ضلعی منتظم با ضلع حساب‌شده بکشید (شش‌ضلعی را با پرگار: شعاع دایره برابر ضلع است؛ شش بار شعاع را روی دایره جدا کنید). ببرید.</div></li><li><span class=\"sn\">۳</span><div><b>سوراخ تخلیه:</b> در مرکز سوراخی به قطر حدود ۱۰ درصد قطر چتر ببرید. این سوراخ هوای زیر چتر را آرام بیرون می‌دهد و از تاب خوردن شدید چتر جلوگیری می‌کند.</div></li><li><span class=\"sn\">۴</span><div><b>تقویت گوشه‌ها:</b> روی هر گوشه یک تکه نوار چسب پارچه‌ای یا حلقه تقویتی بچسبانید و سوراخ کنید.</div></li><li><span class=\"sn\">۵</span><div><b>نخ‌ها:</b> شش (یا هشت) نخ محکم و هم‌طول ببندید؛ طول هر نخ حدود ۱ تا ۱٫۵ برابر قطر چتر. سر دیگر نخ‌ها را با هم به یک حلقه یا قلاب گردان ببندید.</div></li><li><span class=\"sn\">۶</span><div><b>اتصال:</b> حلقه را با یک بند (نوار محکم) به کپسول وصل کنید. بند باید به بدنه سازه کپسول بسته شود، نه به در.</div></li></ol><h2>تا کردن و بستن</h2><p>چتری که بد تا شده باشد، ممکن است باز نشود یا نخ‌هایش به هم بپیچند. روش رایج: چتر را از مرکز بگیرید تا گوشه‌ها آویزان شوند، آن را مانند چتر بسته جمع کنید، از درازا دو بار تا کنید، نخ‌ها را بدون گره دور آن بپیچید و آن را آرام در محفظه چتر بگذارید. کمی پودر تالک روی پلاستیک از چسبیدن لایه‌ها جلوگیری می‌کند. محفظه چتر نباید تنگ باشد.</p><h2>فعال‌سازی به‌موقع</h2><p>بهترین لحظه باز شدن چتر، <b>نزدیک اوج</b> است؛ جایی که سرعت پرتابگر کمترین است و چتر با کمترین ضربه باز می‌شود. اگر چتر در حال بالا رفتن با سرعت زیاد باز شود، ممکن است پاره شود؛ و اگر خیلی دیر باز شود، فرصت پر شدن پیش از رسیدن به زمین را ندارد. چتر کوچک معمولاً در حدود ۱ تا ۲ ثانیه و ۵ تا ۱۰ متر پایین آمدن کاملاً باز می‌شود. سازوکارهای فعال‌سازی در فصل ۱۲ آمده‌اند.</p><div class=\"ex\"><div class=\"ex-t\">مثال ۱۰-۲: زمان فرود</div><p>اوج ۲۵ متر است، چتر ۵ متر پایین‌تر از اوج کاملاً باز می‌شود و سرعت حد ۴ متر بر ثانیه است.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>ارتفاع فرود با چتر باز</td><td dir=\"ltr\">25 − 5 = 20 m</td></tr><tr><td>زمان فرود با چتر</td><td dir=\"ltr\">20 ÷ 4 = 5 s</td></tr></table></div><p>این زمان را با ویدئو مقایسه کنید.</p></div><div class=\"box out\"><div class=\"box-t\">پیوند با داوری</div><div>معیار «سامانه بازیابی» ۱۰ امتیاز دارد و «فعال‌سازی به‌موقع و فرود کنترل‌شده محموله» را ارزیابی می‌کند. باز شدن چتر را در آزمون زمینی (مثلاً رهاسازی از بلندی) و پروازهای آزمایشی بیازمایید و ثبت کنید.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>چتر، نوار کندکننده، سازه جاذب انرژی و پره‌های چرخان، سرعت فرود را کم می‌کنند.</li><li>در سرعت حد، پسا با وزن برابر است: A = 2mg ÷ (ρ C<sub>d</sub> v²).</li><li>چتر شش‌ضلعی با سوراخ تخلیه، نخ‌های هم‌طول و تای درست، مطمئن باز می‌شود.</li><li>چتر باید نزدیک اوج باز شود؛ قطعات جداشونده سرعتی کمتر از ۱۰ متر بر ثانیه داشته باشند.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>سرعت حد چیست؟ چرا سرعت کپسول با چتر از حدی بیشتر نمی‌شود؟</li><li>برای کپسولی ۲۵۰ گرمی و سرعت فرود ۵ متر بر ثانیه، مساحت و قطر چتر تخت را حساب کنید.</li><li>اگر قطر چتر دو برابر شود، سرعت حد چند برابر می‌شود؟ (راهنمایی: مساحت ۴ برابر می‌شود.)</li><li>سوراخ تخلیه چه کاری انجام می‌دهد؟</li><li>چرا باز شدن چتر هنگام بالا رفتن سریع پرتابگر خطرناک است؟</li><li>اوج ۳۰ متر است و چتر ۶ متر پایین‌تر از اوج باز می‌شود. با سرعت حد ۵ متر بر ثانیه، فرود چقدر طول می‌کشد؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>چتر کپسول را حساب و بسازید. آن را با کپسول از بلندی امن (زیر نظر مربی) رها کنید، سرعت فرود را با زمان‌سنج بسنجید و با پیش‌بینی مقایسه کنید. این آزمون، یکی از آزمون‌های زمینی است.</div></div>"}, {"t": "ماژول بوستر و پرتابگر چندمرحله‌ای", "n": "فصل ۱۱", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>بوستر چه کمکی به پرتابگر می‌کند</li><li>چیدمان متقارن دو تا چهار بوستر</li><li>ساخت بوستر و اتصال آن به پرتابگر اصلی</li><li>جدایش غیرفعال بوسترها و پرتابگر دومرحله‌ای</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۱ (ماژول)<br>۹۰ دقیقه + کار عملی<br>معیارهای ۹ و ۱۰ (۷ + ۵ امتیاز)</div></div>\n<p>دیدن پرتابگری که با چهار بوستر از سکو بلند می‌شود و بوسترها یکی‌یکی از آن جدا می‌شوند، هیجان‌انگیزترین لحظه این گرایش است. ساخت بوستر به همه تیم‌ها توصیه می‌شود؛ اما دقت در تقارن، اتصال و رهاسازی هم‌زمان، شرط موفقیت آن است.</p><h2>چرا بوستر؟</h2><p>هر بوستر، یک بطری دیگر با آب و هوای فشرده است که هم‌زمان با پرتابگر اصلی رانش تولید می‌کند. با بوسترها، در لحظه‌های اول پرواز که پرتابگر سنگین‌ترین است، رانش کل چند برابر می‌شود. اگر بوسترها پس از تمام شدن رانش جدا شوند، پرتابگر اصلی وزن آن‌ها را حمل نمی‌کند و پرواز را ادامه می‌دهد؛ درست مانند موشک‌های واقعی.</p><div class=\"box tip\"><div class=\"box-t\">هدف، ارتفاع نیست</div><div>بوسترها ممکن است ارتفاع را زیاد کنند، اما به یاد داشته باشید که ارتفاع اوج فقط تا ۳ امتیاز (ردیف ۴) دارد. امتیاز بوستر برای «عملکرد هم‌زمان و درست» و امتیاز جداسازی برای «جداسازی در پرواز و بازیابی ایمن قطعات» است.</div></div><h2>چیدمان</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 200\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"200\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><circle cx=\"540\" cy=\"90\" fill=\"#e8f1fb\" r=\"28\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><circle cx=\"540\" cy=\"38\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><circle cx=\"540\" cy=\"142\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"540\" y=\"180\">۲ بوستر</text><circle cx=\"340\" cy=\"90\" fill=\"#e8f1fb\" r=\"28\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><circle cx=\"340\" cy=\"38\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><circle cx=\"295\" cy=\"116\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><circle cx=\"385\" cy=\"116\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"340\" y=\"180\">۳ بوستر</text><circle cx=\"140\" cy=\"90\" fill=\"#e8f1fb\" r=\"28\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><circle cx=\"140\" cy=\"38\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><circle cx=\"88\" cy=\"90\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><circle cx=\"140\" cy=\"142\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><circle cx=\"192\" cy=\"90\" fill=\"#fff\" r=\"20\" stroke=\"#2A9DAE\" stroke-width=\"2\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"140\" y=\"180\">۴ بوستر</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"middle\" x=\"345\" y=\"22\">نمای بالا؛ بوسترها باید متقارن چیده شوند</text></svg><figcaption>شکل ۱۱-۱: چیدمان دو، سه و چهار بوستر (نمای بالا).</figcaption></figure><ul class=\"ul\"><li>بوسترها باید <b>متقارن</b> چیده شوند و <b>هم‌جرم و هم‌اندازه</b> باشند؛ وگرنه رانش و پسا نامتقارن، پرتابگر را منحرف می‌کند.</li><li>همه بوسترها با یک مقدار آب پر می‌شوند (با استوانه مدرج یا ترازو اندازه بگیرید).</li><li>با چهار بوستر، پرتابگر اصلی معمولاً به بالک‌های کوچک‌تری نیاز دارد، چون بوسترها خودشان سطح عقب را زیاد می‌کنند؛ اما CG و CP را با همه بوسترها دوباره بسنجید و آزمون چرخش را تکرار کنید.</li></ul><h2>ساخت بوستر</h2><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>برای هر بوستر یک بطری PET نوشابه گازدار سالم (معمولاً هم‌اندازه یا کوچک‌تر از بطری اصلی) آماده کنید و آزمون فشار را برای هر کدام جداگانه انجام دهید.</div></li><li><span class=\"sn\">۲</span><div>روی ته هر بوستر (بالای آن در پرواز) یک دماغه سبک و نرم بگذارید تا پسا کم شود.</div></li><li><span class=\"sn\">۳</span><div>سامانه بازیابی هر بوستر را آماده کنید: یک نوار کندکننده یا چتر کوچک، تا سرعت فرود آن کمتر از ۱۰ متر بر ثانیه باشد.</div></li><li><span class=\"sn\">۴</span><div>بخش‌های اتصال (گیره و حلقه) را مطابق بخش بعد بسازید.</div></li></ol><h2>اتصال بوسترها</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 290\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"290\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><rect fill=\"#e8f1fb\" height=\"220\" rx=\"16\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"60\" x=\"315\" y=\"30\"></rect><rect fill=\"#E0A93B\" height=\"14\" width=\"72\" x=\"309\" y=\"100\"></rect><rect fill=\"#E0A93B\" height=\"12\" width=\"72\" x=\"309\" y=\"232\"></rect><rect fill=\"#fff\" height=\"140\" rx=\"12\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"44\" x=\"253\" y=\"110\"></rect><path d=\"M253,114 Q275,70 297,114 Z\" fill=\"#dfe6f0\" stroke=\"#2A9DAE\"></path><line stroke=\"#333\" stroke-width=\"3\" x1=\"297.0\" x2=\"309.0\" y1=\"112.0\" y2=\"107.0\"></line><line stroke=\"#333\" stroke-dasharray=\"3 3\" stroke-width=\"2\" x1=\"297.0\" x2=\"309.0\" y1=\"238.0\" y2=\"238.0\"></line><rect fill=\"#fff\" height=\"140\" rx=\"12\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"44\" x=\"393\" y=\"110\"></rect><path d=\"M393,114 Q415,70 437,114 Z\" fill=\"#dfe6f0\" stroke=\"#2A9DAE\"></path><line stroke=\"#333\" stroke-width=\"3\" x1=\"393.0\" x2=\"381.0\" y1=\"112.0\" y2=\"107.0\"></line><line stroke=\"#333\" stroke-dasharray=\"3 3\" stroke-width=\"2\" x1=\"393.0\" x2=\"381.0\" y1=\"238.0\" y2=\"238.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"465\" y=\"100\">گیره بالایی: بوستر پرتابگر را هل می‌دهد</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"end\" x=\"465\" y=\"120\">و پس از تمام شدن رانش، از گیره سر می‌خورد</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"465\" y=\"248\">حلقه پایینی: فقط هم‌راستا نگه می‌دارد</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"start\" x=\"245\" y=\"30\">اصلی</text></svg><figcaption>شکل ۱۱-۲: اتصال بوستر با گیره بالایی و حلقه پایینی.</figcaption></figure><p>بوستر باید در پرتاب، پرتابگر اصلی را با خود بالا ببرد و پس از تمام شدن رانش، از آن جدا شود. یک طرح ساده و رایج:</p><div class=\"tbl\"><table class=\"kv\"><tr><td>حلقه بالایی (یقه رانش)</td><td>یک حلقه محکم پلاستیکی یا مقوایی دور بدنه پرتابگر اصلی، با یک «شانه» برای هر بوستر. یک میله یا زبانه پلاستیکی روی بوستر زیر این شانه قرار می‌گیرد؛ وقتی بوستر رانش دارد، شانه را به بالا هل می‌دهد و پرتابگر اصلی را با خود می‌برد.</td></tr><tr><td>حلقه پایینی (راهنما)</td><td>یک حلقه دیگر نزدیک دهانه‌ها که بوسترها را فقط هم‌راستا نگه می‌دارد و آن‌ها را محکم نمی‌گیرد.</td></tr><tr><td>جدایش</td><td>وقتی رانش بوستر تمام می‌شود و هنوز رانش اصلی ادامه دارد (یا پسای بوستر بیشتر است)، بوستر عقب می‌ماند، زبانه‌اش از زیر شانه بیرون می‌لغزد و جدا می‌شود. هیچ سازوکار فعالی لازم نیست؛ به این روش «جدایش غیرفعال» می‌گویند.</td></tr></table></div><div class=\"box tip\"><div class=\"box-t\">بوسترها زودتر خاموش شوند</div><div>برای اینکه جدایش غیرفعال کار کند، بوسترها باید زودتر از پرتابگر اصلی خاموش شوند. یک راه ساده: بوسترها را با آب کمتری پر کنید یا بطری اصلی را بزرگ‌تر بگیرید (مثلاً اصلی ۲ لیتری و بوسترها ۱٫۵ لیتری). این را با فیلم آهسته از پرواز بیازمایید.</div></div><div class=\"box warn\"><div class=\"box-t\">جنس اتصال‌ها</div><div>زبانه‌ها و میله‌های اتصال باید سبک و غیرفلزی باشند (پلاستیک، چوب سبک، مقوای محکم). هیچ قطعه‌ای نباید بدنه بطری‌های تحت فشار را سوراخ کند؛ همه اتصال‌ها با حلقه‌ها و نوار چسب انجام می‌شوند.</div></div><h2>آزمون‌ها</h2><ul class=\"ul\"><li>آزمون رهاسازی هم‌زمان روی سکو، بدون فشار، با فیلم آهسته (فصل ۸).</li><li>آزمون جدایش: پرتابگر کامل را با دست نگه دارید و بوستر را با دست دیگر از پایین به عقب بکشید؛ باید آزادانه بلغزد و جدا شود، اما در حالت عادی محکم بماند.</li><li>آزمون پایداری با همه بوسترها (CG، CP و آزمون چرخش).</li><li>نخستین پرواز را با فشار کمتر (مثلاً ۳ بار) انجام دهید.</li></ul><h2>پرتابگر دومرحله‌ای</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 260\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"260\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><g transform=\"rotate(0 250 245)\"><rect fill=\"#e8f1fb\" height=\"85.0\" rx=\"7.7\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"22.0\" x=\"239.0\" y=\"145.0\"></rect><path d=\"M239.0,149.0 Q250.0,111.0 261.0,149.0 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"15.0\" width=\"8.0\" x=\"246.0\" y=\"230.0\"></rect><path d=\"M239.0,210.0 L223.0,237.0 L239.0,230.0 Z\" fill=\"#1B2A4A\"></path><path d=\"M261.0,210.0 L277.0,237.0 L261.0,230.0 Z\" fill=\"#1B2A4A\"></path></g><rect fill=\"#fff\" height=\"70\" rx=\"6\" stroke=\"#2A9DAE\" stroke-width=\"2\" width=\"22\" x=\"239\" y=\"80\"></rect><path d=\"M239,84 Q250,40 261,84 Z\" fill=\"#C0392B\"></path><rect fill=\"#E0A93B\" height=\"10\" width=\"28\" x=\"236\" y=\"148\"></rect><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"280\" y=\"110\">مرحله دوم</text><text fill=\"#9a6b10\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"end\" x=\"280\" y=\"160\">سازوکار اتصال و آزادسازی</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"end\" x=\"280\" y=\"220\">مرحله اول</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"650\" y=\"70\">مرحله اول تا پایان رانش، هر دو را بالا می‌برد.</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"650\" y=\"95\">سپس سازوکار، مرحله دوم را آزاد و</text><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"650\" y=\"120\">نازل آن را باز می‌کند تا روشن شود.</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"normal\" text-anchor=\"start\" x=\"650\" y=\"160\">پیشرفته‌ترین ماژول؛ فقط پس از تسلط بر بوستر</text></svg><figcaption>شکل ۱۱-۳: پرتابگر دومرحله‌ای.</figcaption></figure><p>در پرتابگر دومرحله‌ای، یک بطری دوم با آب و هوای فشرده روی بطری اول سوار می‌شود. وقتی مرحله اول خاموش شد، سازوکاری مرحله دوم را آزاد می‌کند و همزمان نازل آن را باز می‌کند تا مرحله دوم روشن شود. این کار سخت‌ترین ماژول این گرایش است: مرحله دوم باید از روی خود پرتابگر پر از هوا شود، تا لحظه جدایش آب‌بند بماند و در لحظه درست رها شود. مرحله اول هم باید سامانه بازیابی خودش را داشته باشد.</p><div class=\"box why\"><div class=\"box-t\">برای تیم‌های پیشرفته</div><div>سازوکارهای رایج آزادسازی مرحله دوم: یک قفل مکانیکی که با پایان شتاب مرحله اول (کند شدن ناگهانی) باز می‌شود، یا یک تایمر مکانیکی یا الکترونیکی. پیشنهاد می‌شود فقط تیم‌هایی سراغ آن بروند که بوستر و جداسازی کپسول را با موفقیت انجام داده‌اند، و نخستین آزمون‌ها با فشار کم و زیر نظر مربی انجام شود.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>بوسترها در لحظه‌های اول پرواز رانش کل را زیاد می‌کنند و پس از خاموش شدن جدا می‌شوند.</li><li>بوسترها متقارن، هم‌جرم و با آب یکسان پر می‌شوند.</li><li>با یقه رانش و حلقه راهنما، جدایش غیرفعال پس از خاموشی بوستر رخ می‌دهد.</li><li>هر بوستر و مرحله، سامانه بازیابی با سرعت کمتر از ۱۰ متر بر ثانیه می‌خواهد.</li><li>پرتابگر دومرحله‌ای پیشرفته‌ترین ماژول است.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>چرا بوسترها باید متقارن و هم‌جرم باشند؟</li><li>جدایش غیرفعال بوستر چگونه رخ می‌دهد؟</li><li>چرا بوسترها باید زودتر از پرتابگر اصلی خاموش شوند؟ دو راه برای این کار بنویسید.</li><li>یک بطری خالی ۴۵ گرمی بدون هیچ سامانه بازیابی، با سرعتی بیش از ۱۰ متر بر ثانیه فرود می‌آید. چه راه‌حلی پیشنهاد می‌کنید؟</li><li>چرا نخستین پرواز پرتابگر با بوستر باید با فشار کمتر باشد؟</li><li>یکی از سختی‌های پرتابگر دومرحله‌ای را توضیح دهید.</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>اگر ماژول بوستر را انتخاب کرده‌اید، بوسترها و اتصال‌ها را بسازید، آزمون‌های این فصل را انجام دهید و نتیجه را با عکس و فیلم در پرونده ثبت کنید.</div></div>"}, {"t": "سازوکارهای جداسازی و فعال‌سازی", "n": "فصل ۱۲", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>سازوکار خوب جداسازی چه ویژگی‌هایی دارد</li><li>سازوکارهای مکانیکی: دماغه جداشونده، درِ فنری، تایمر مکانیکی</li><li>سازوکارهای الکتریکی: سروو با میکروکنترلر</li><li>آزمون قابلیت اطمینان</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۲ (ماژول)<br>۹۰ دقیقه<br>معیار ۱۱ (۶ امتیاز) و معیار ۶</div></div>\n<p>سازوکار جداسازی، کپسول را از بدنه جدا یا چتر را آزاد می‌کند. شیوه‌نامه هر سازوکاری را که «طراحی سنجیده، اجرای مطمئن و مستندات روشن» داشته باشد می‌پذیرد و تأکید می‌کند: <b>سادگی و قابلیت اطمینان، به اندازه پیچیدگی ارزشمند است.</b></p><h2>سازوکار خوب</h2><ul class=\"ul\"><li><b>در زمان درست</b> عمل کند: نزدیک اوج، نه در پرتاب و نه نزدیک زمین.</li><li><b>در پرتاب</b> با شتاب شدید، خودبه‌خود عمل نکند.</li><li><b>قابل آزمون</b> روی زمین باشد و بتوان آن را ده‌ها بار امتحان کرد.</li><li><b>سبک</b> باشد و به پایداری آسیب نزند.</li><li>پس از عمل، چیزی به چتر گیر نکند و نخ‌ها در هم نپیچند.</li></ul><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#F5F8FC\" height=\"250\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><g transform=\"rotate(0 590 175)\"><rect fill=\"#e8f1fb\" height=\"72.2\" rx=\"6.5\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"18.7\" x=\"580.6\" y=\"90.0\"></rect><path d=\"M580.6,93.4 Q590.0,61.1 599.4,93.4 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"12.8\" width=\"6.8\" x=\"586.6\" y=\"162.2\"></rect><path d=\"M580.6,145.2 L567.0,168.2 L580.6,162.2 Z\" fill=\"#1B2A4A\"></path><path d=\"M599.4,145.2 L613.0,168.2 L599.4,162.2 Z\" fill=\"#1B2A4A\"></path></g><path d=\"M579,60 Q590,30 601,60 Z\" fill=\"#C0392B\" transform=\"translate(18,-25) rotate(25 590 50)\"></path><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"590\" y=\"205\">جدا شدن دماغه در اوج</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"10.5\" font-weight=\"normal\" text-anchor=\"middle\" x=\"590\" y=\"225\">وزن و کندی دماغه</text><g transform=\"rotate(0 425 175)\"><rect fill=\"#e8f1fb\" height=\"72.2\" rx=\"6.5\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"18.7\" x=\"415.6\" y=\"90.0\"></rect><path d=\"M415.6,93.4 Q425.0,61.1 434.4,93.4 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"12.8\" width=\"6.8\" x=\"421.6\" y=\"162.2\"></rect><path d=\"M415.6,145.2 L402.0,168.2 L415.6,162.2 Z\" fill=\"#1B2A4A\"></path><path d=\"M434.4,145.2 L448.0,168.2 L434.4,162.2 Z\" fill=\"#1B2A4A\"></path></g><rect fill=\"#E0A93B\" height=\"30\" transform=\"rotate(30 436 95)\" width=\"6\" x=\"436\" y=\"95\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"425\" y=\"205\">درِ فنری کناری</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"10.5\" font-weight=\"normal\" text-anchor=\"middle\" x=\"425\" y=\"225\">کش یا فنر + ضامن</text><g transform=\"rotate(0 260 175)\"><rect fill=\"#e8f1fb\" height=\"72.2\" rx=\"6.5\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"18.7\" x=\"250.7\" y=\"90.0\"></rect><path d=\"M250.7,93.4 Q260.0,61.1 269.4,93.4 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"12.8\" width=\"6.8\" x=\"256.6\" y=\"162.2\"></rect><path d=\"M250.7,145.2 L237.1,168.2 L250.7,162.2 Z\" fill=\"#1B2A4A\"></path><path d=\"M269.4,145.2 L283.0,168.2 L269.4,162.2 Z\" fill=\"#1B2A4A\"></path></g><circle cx=\"260\" cy=\"110\" fill=\"#fff\" r=\"8\" stroke=\"#1B2A4A\" stroke-width=\"2\"></circle><line stroke=\"#1B2A4A\" stroke-width=\"1.5\" x1=\"260.0\" x2=\"265.0\" y1=\"110.0\" y2=\"105.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"260\" y=\"205\">تایمر مکانیکی</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"10.5\" font-weight=\"normal\" text-anchor=\"middle\" x=\"260\" y=\"225\">تایمر کوکی آزادکننده ضامن</text><g transform=\"rotate(0 95 175)\"><rect fill=\"#e8f1fb\" height=\"72.2\" rx=\"6.5\" stroke=\"#1B2A4A\" stroke-width=\"2\" width=\"18.7\" x=\"85.7\" y=\"90.0\"></rect><path d=\"M85.7,93.4 Q95.0,61.1 104.3,93.4 Z\" fill=\"#C0392B\"></path><rect fill=\"#9fb0c6\" height=\"12.8\" width=\"6.8\" x=\"91.6\" y=\"162.2\"></rect><path d=\"M85.7,145.2 L72.1,168.2 L85.7,162.2 Z\" fill=\"#1B2A4A\"></path><path d=\"M104.3,145.2 L117.9,168.2 L104.3,162.2 Z\" fill=\"#1B2A4A\"></path></g><rect fill=\"#2a6f3a\" height=\"12\" width=\"16\" x=\"87\" y=\"102\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"95\" y=\"205\">سروو با میکروکنترلر</text><text fill=\"#5a6b82\" font-family=\"Vazirmatn\" font-size=\"10.5\" font-weight=\"normal\" text-anchor=\"middle\" x=\"95\" y=\"225\">فرمان تایمر یا حسگر</text></svg><figcaption>شکل ۱۲-۱: چهار سازوکار رایج.</figcaption></figure><h2>۱. دماغه جداشونده در اوج</h2><p>ساده‌ترین روش: چتر درون محفظه زیر دماغه قرار می‌گیرد و دماغه به‌آرامی (بدون چسب) روی محفظه نشسته است. در بالا رفتن، فشار هوا دماغه را سر جایش نگه می‌دارد. در اوج، پرتابگر کند می‌شود و می‌چرخد؛ دماغه که به آن با بند متصل است، از محفظه بیرون می‌افتد و چتر را بیرون می‌کشد. این روش ساده است، اما زمان دقیق آن به چرخش پرتابگر بستگی دارد. با آزمون، سفتی جا افتادن دماغه را تنظیم کنید.</p><h2>۲. درِ فنری کناری</h2><p>چتر در محفظه‌ای با یک در کناری قرار دارد. کش لاستیکی یا فنر در را به بیرون می‌کشد و یک ضامن (مثلاً میله یا نخ) آن را بسته نگه می‌دارد. وقتی ضامن آزاد شود، در باز و چتر بیرون رانده می‌شود. چیزی که ضامن را آزاد می‌کند، می‌تواند تایمر مکانیکی یا سروو باشد.</p><h2>۳. تایمر مکانیکی</h2><p>تایمرهای مکانیکی کوکی کوچک (مانند تایمرهای اسباب‌بازی) پس از چند ثانیه یک اهرم را می‌چرخانند. تایمر را طوری بسازید که در لحظه پرتاب آزاد شود: مثلاً یک نخ از ضامن تایمر به سکو بسته شود و با جدا شدن پرتابگر کشیده شود. زمان را برابر «زمان تا اوج» (از پروازهای آزمایشی یا محاسبه) تنظیم کنید.</p><h2>۴. سروو با میکروکنترلر</h2><p>یک موتور سروو کوچک (مانند SG90) با فرمان یک میکروکنترلر (مانند Arduino Nano یا ESP32) می‌چرخد و ضامن را آزاد می‌کند. فرمان می‌تواند بر پایه زمان (تایمر) یا حسگر (تشخیص اوج با حسگر فشار؛ فصل ۱۳) باشد. برای شروع زمان‌سنجی در لحظه پرتاب، از یک <b>سیم جداشونده</b> استفاده کنید: دو پایه که با یک سیم یا دوشاخه به هم وصل‌اند و با جدا شدن پرتابگر از سکو، اتصال قطع می‌شود.</p><div class=\"code\"><div class=\"code-cap\">برنامه ۱۲-۱: آزادسازی ضامن با تایمر پس از پرتاب</div><pre dir=\"ltr\">#include &lt;Servo.h&gt;\nServo latch;\nconst int LAUNCH_PIN = 2;      // سیم جداشونده: وصل به GND تا لحظه پرتاب\nconst unsigned long DELAY_MS = 2300;   // زمان تا اوج (از آزمون‌ها)\n\nvoid setup() {\n  pinMode(LAUNCH_PIN, INPUT_PULLUP);\n  latch.attach(9);\n  latch.write(10);             // ضامن بسته\n}\n\nvoid loop() {\n  if (digitalRead(LAUNCH_PIN) == HIGH) {   // سیم جدا شد: پرتاب!\n    delay(DELAY_MS);\n    latch.write(100);          // ضامن باز؛ آزاد شدن در یا کپسول\n    while (true) {}            // پایان\n  }\n}</pre></div><div class=\"box warn\"><div class=\"box-t\">الکترونیک ایمن</div><div>شیوه‌نامه می‌خواهد سیم‌کشی محکم و عایق باشد، از اتصال کوتاه محافظت شود، باتری کم‌حجم با محفظه مقاوم باشد و کلید اصلی در دسترس. برد و باتری را در بخش تجهیزات کپسول محکم ببندید؛ شتاب پرتاب حدود ۲۰ برابر گرانش است.</div></div><h2>جداسازی کپسول از بدنه</h2><p>در ماژول «جداسازی کپسول»، کپسول باید از بدنه جدا شود و <b>هر دو مستقل</b> بازیابی شوند: کپسول با چتر خودش و بدنه با نوار کندکننده یا چتر دیگر. یک روش: کپسول روی بدنه با یک ضامن نگه داشته شده است؛ وقتی ضامن آزاد شود، فنر یا کش، کپسول را کمی بالا هل می‌دهد و چتر کپسول که به در یا دماغه بسته است، باز می‌شود. یک بند کوتاه می‌تواند چتر بدنه را هم‌زمان بیرون بکشد.</p><h2>آزمون قابلیت اطمینان</h2><p>سازوکار جداسازی را روی زمین دست‌کم ۲۰ بار امتحان کنید و تعداد موفقیت‌ها را بشمارید. اگر ۱۹ بار از ۲۰ بار درست کار کرد، قابلیت اطمینان آن حدود ۹۵ درصد است. هر شکست را بررسی کنید: گیر کردن، دیر عمل کردن، پیچیدن نخ؟ سپس طرح را اصلاح و دوباره آزمون کنید. آزمون باز شدن چتر یا سازوکار جداسازی، یکی از آزمون‌های زمینی پیشنهادی شیوه‌نامه است.</p><div class=\"ws-h\">کاربرگ ۱۲-۱: آزمون سازوکار جداسازی</div><div class=\"tbl wide\"><table class=\"wt blank\"><tr><th style=\"width:14%\">شماره آزمون</th><th style=\"width:14%\">تاریخ</th><th style=\"width:18%\">زمان عمل (ثانیه)</th><th style=\"width:18%\">نتیجه (موفق/ناموفق)</th><th style=\"width:18%\">علت شکست</th><th style=\"width:18%\">اصلاح</th></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td><td class=\"l\"></td></tr></table></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>سازوکار جداسازی باید در زمان درست، مطمئن و قابل آزمون عمل کند.</li><li>دماغه جداشونده، درِ فنری و تایمر مکانیکی سازوکارهای ساده و مؤثرند.</li><li>سروو با میکروکنترلر و سیم جداشونده، زمان‌بندی دقیق می‌دهد.</li><li>در جداسازی کپسول، کپسول و بدنه هر کدام مستقل بازیابی می‌شوند.</li><li>قابلیت اطمینان را با آزمون‌های تکراری بسنجید.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>سه ویژگی یک سازوکار جداسازی خوب را بنویسید.</li><li>چرا دماغه جداشونده در بالا رفتن جدا نمی‌شود؟</li><li>زمان تا اوج پرتابگری ۲٫۲ ثانیه است. تایمر سازوکار را روی چه زمانی تنظیم می‌کنید؟ چرا شاید کمی بیشتر یا کمتر؟</li><li>سیم جداشونده چه کاری انجام می‌دهد؟</li><li>سازوکاری در ۲۰ آزمون ۱۶ بار موفق بوده است. قابلیت اطمینان آن چقدر است؟ آیا برای پرواز رسمی کافی است؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>سازوکار جداسازی یا فعال‌سازی چتر تیم را انتخاب، ساخت و ۲۰ بار آزمون کنید. کاربرگ ۱۲-۱ را کامل کنید و از چند آزمون فیلم آهسته بگیرید.</div></div>"}, {"t": "ارتفاع‌سنج و مأموریت علمی کپسول (کن‌ست)", "n": "فصل ۱۳", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>سنجش ارتفاع با حسگر فشار هوا</li><li>ثبت داده در پرواز و تشخیص اوج</li><li>طراحی یک مأموریت علمی کوچک برای کپسول</li><li>رسم و تحلیل نمودار ارتفاع-زمان</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۳ (ماژول)<br>۹۰ دقیقه<br>معیارهای ۱۲ و ۱۳ (۴ + ۴ امتیاز)</div></div>\n<p>کپسولی که در حین پرواز داده جمع می‌کند، یک ماهواره کوچک واقعی است. در ماژول «سنجش ارتفاع»، نمودار ارتفاع-زمان را با حسگر ثبت و با پیش‌بینی مقایسه می‌کنید و در ماژول «مأموریت علمی کپسول»، مانند تیم‌های کن‌ست، یک پرسش علمی را با داده‌های پرواز پاسخ می‌دهید.</p><h2>ارتفاع از فشار هوا</h2><p>هرچه بالاتر بروید، هوای کمتری بالای سر شماست و فشار هوا کمتر می‌شود. نزدیک سطح زمین، به ازای هر ۸ تا ۹ متر بالا رفتن، فشار حدود ۱ هکتوپاسکال (یک‌صدم کیلوپاسکال) کم می‌شود. حسگرهای فشار دیجیتال مانند <b>BMP280</b> یا <b>BME280</b> آن‌قدر حساس‌اند که تغییر ارتفاع حدود یک متر را تشخیص می‌دهند.</p><div class=\"fm\" dir=\"ltr\">h = 44330 × (1 − (P ÷ P₀)^0.1903)</div><p>P فشار در هر لحظه و P₀ فشار روی زمین در لحظه پرتاب است. کتابخانه حسگر این محاسبه را انجام می‌دهد؛ کافی است P₀ را پیش از پرتاب اندازه بگیرید و به آن بدهید.</p><div class=\"box tip\"><div class=\"box-t\">سوراخ‌های فشار</div><div>حسگر درون کپسول بسته، فشار بیرون را درست نمی‌سنجد. سه یا چهار سوراخ کوچک (۲ تا ۳ میلی‌متر) با فاصله مساوی دور بخش تجهیزات ایجاد کنید تا فشار درون و بیرون برابر شود. حسگر را با اسفنج نازک از جریان مستقیم هوا و نور خورشید محافظت کنید.</div></div><h2>ثبت داده</h2><div class=\"code\"><div class=\"code-cap\">برنامه ۱۳-۱: ثبت ارتفاع ۲۰ بار در ثانیه و تشخیص گذر از اوج</div><pre dir=\"ltr\">#include &lt;Wire.h&gt;\n#include &lt;Adafruit_BMP280.h&gt;\nAdafruit_BMP280 bmp;\nfloat p0, hmax = 0;\nconst int N = 600;              // ۳۰ ثانیه با ۲۰ نمونه در ثانیه\nfloat alt[N]; int n = 0;\n\nvoid setup() {\n  Serial.begin(115200);\n  bmp.begin(0x76);\n  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL, Adafruit_BMP280::SAMPLING_X2,\n                  Adafruit_BMP280::SAMPLING_X16, Adafruit_BMP280::FILTER_X4,\n                  Adafruit_BMP280::STANDBY_MS_1);\n  delay(500);\n  p0 = bmp.readPressure() / 100.0;   // فشار زمین (هکتوپاسکال)\n}\n\nvoid loop() {\n  if (n &lt; N) {\n    float h = bmp.readAltitude(p0);  // ارتفاع نسبت به سکو\n    alt[n++] = h;\n    if (h &gt; hmax) hmax = h;\n    if (hmax &gt; 5 &amp;&amp; h &lt; hmax - 1.5) { /* اوج گذشته است: فرمان جداسازی */ }\n    delay(50);\n  } else {\n    for (int i = 0; i &lt; N; i++) {     // پس از پرواز: چاپ داده‌ها برای صفحه‌گسترده\n      Serial.print(i * 0.05); Serial.print(\",\"); Serial.println(alt[i]);\n    }\n    while (true) {}\n  }\n}</pre></div><p class=\"hint\">در این برنامه، داده‌ها در حافظه برد نگه داشته می‌شوند و پس از پرواز، با وصل کردن برد به رایانه از نمایشگر سریال خوانده می‌شوند. برای پروازهای طولانی‌تر یا اطمینان بیشتر، داده‌ها را در حافظه فلش (LittleFS در ESP32) یا کارت حافظه ذخیره کنید. برای شروع ثبت در لحظه پرتاب، از سیم جداشونده (فصل ۱۲) استفاده کنید.</p><h2>تشخیص اوج</h2><p>شرط «ارتفاع کنونی دست‌کم ۱٫۵ متر کمتر از بیشینه باشد» نشان می‌دهد پرتابگر از اوج گذشته و در حال پایین آمدن است. چرا ۱٫۵ متر و نه صفر؟ چون داده حسگر نویز دارد و ممکن است یک نمونه به اشتباه کمی پایین‌تر باشد. شرط «بیشینه بیش از ۵ متر» هم جلوی عمل کردن اشتباه روی سکو را می‌گیرد. این شرط را با داده واقعی پروازهای آزمایشی تنظیم کنید.</p><div class=\"box warn\"><div class=\"box-t\">جریان هوا و فشار</div><div>در لحظه پرتاب و هنگام باز شدن چتر، جریان هوای شدید ممکن است فشار درون کپسول را برای لحظه‌ای تغییر دهد و حسگر ارتفاع اشتباه نشان دهد. اگر سازوکار جداسازی را بر پایه حسگر فشار می‌سازید، یک تایمر پشتیبان هم بگذارید: «اگر تا ۴ ثانیه اوج تشخیص داده نشد، جداسازی انجام شود».</div></div><h2>نمودار ارتفاع-زمان</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 640 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect fill=\"#fff\" height=\"270\" rx=\"10\" stroke=\"#d9e2ee\" width=\"640\"></rect><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"225.0\" y2=\"225.0\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"229.0\">0</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"160.9\" y2=\"160.9\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"164.9\">10</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"96.9\" y2=\"96.9\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"100.9\">20</text><line stroke=\"#e6ecf3\" x1=\"70\" x2=\"620\" y1=\"32.8\" y2=\"32.8\"></line><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"end\" x=\"64\" y=\"36.8\">30</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"70.0\" y=\"241\">0</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"148.6\" y=\"241\">2</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"227.1\" y=\"241\">4</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"305.7\" y=\"241\">6</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"384.3\" y=\"241\">8</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"462.9\" y=\"241\">10</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"541.4\" y=\"241\">12</text><text fill=\"#5a6b82\" font-family=\"DejaVu Sans\" font-size=\"11\" text-anchor=\"middle\" x=\"620.0\" y=\"241\">14</text><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"620\" y1=\"225\" y2=\"225\"></line><line stroke=\"#1B2A4A\" x1=\"70\" x2=\"70\" y1=\"20\" y2=\"225\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" x=\"345\" y=\"264\">زمان (ثانیه)</text><text fill=\"#1B2A4A\" font-family=\"BNazanin\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" transform=\"rotate(-90 16 122.5)\" x=\"16\" y=\"122.5\">ارتفاع (متر)</text><polyline fill=\"none\" points=\"70.0,228.7 73.9,206.8 77.9,193.6 81.8,185.5 85.7,170.2 89.6,158.6 93.6,145.0 97.5,132.7 101.4,129.5 105.4,120.5 109.3,103.2 113.2,98.9 117.1,87.8 121.1,88.4 125.0,77.3 128.9,68.6 132.9,68.3 136.8,56.3 140.7,52.7 144.6,58.2 148.6,55.5 152.5,48.0 156.4,42.4 160.4,47.2 164.3,48.5 168.2,47.9 172.1,53.7 176.1,53.8 180.0,53.9 183.9,56.1 187.9,61.8 191.8,65.2 195.7,69.0 199.6,70.5 203.6,76.6 207.5,80.6 211.4,73.6 215.4,77.7 219.3,78.1 223.2,84.1 227.1,77.1 231.1,79.7 235.0,88.6 238.9,87.7 242.9,85.0 246.8,86.4 250.7,85.4 254.6,91.9 258.6,89.0 262.5,91.9 266.4,97.0 270.4,95.3 274.3,93.6 278.2,95.2 282.1,100.0 286.1,100.4 290.0,107.4 293.9,106.6 297.9,102.2 301.8,107.4 305.7,111.1 309.6,108.5 313.6,108.2 317.5,109.8 321.4,114.2 325.4,114.8 329.3,115.4 333.2,113.9 337.1,117.8 341.1,120.4 345.0,120.7 348.9,126.7 352.9,127.8 356.8,122.3 360.7,120.8 364.6,126.0 368.6,129.4 372.5,132.9 376.4,130.8 380.4,127.2 384.3,130.6 388.2,134.3 392.1,132.3 396.1,140.0 400.0,138.4 403.9,135.2 407.9,140.3 411.8,142.8 415.7,146.0 419.6,144.4 423.6,141.5 427.5,152.6 431.4,145.9 435.4,146.8 439.3,147.4 443.2,150.1 447.1,150.7 451.1,155.0 455.0,155.8 458.9,158.5 462.9,163.6 466.8,156.5 470.7,160.9 474.6,165.9 478.6,164.1 482.5,165.6 486.4,168.2 490.4,169.6 494.3,168.9 498.2,169.3 502.1,170.7 506.1,173.5 510.0,179.2 513.9,178.4 517.9,180.3 521.8,177.4 525.7,175.8 529.6,177.7 533.6,179.0 537.5,180.1 541.4,187.1 545.4,182.4 549.3,185.4 553.2,192.8 557.1,194.7 561.1,196.0 565.0,189.7 568.9,196.2 572.9,198.9 576.8,194.9 580.7,199.0 584.6,203.1 588.6,203.5 592.5,201.0 596.4,206.0 600.4,206.2 604.3,203.0 608.2,206.9 612.1,209.5 616.1,209.3 620.0,215.1\" stroke=\"#9fb0c6\" stroke-width=\"2.5\"></polyline><polyline fill=\"none\" points=\"70.0,225.0 73.9,210.4 77.9,196.3 81.8,183.0 85.7,170.2 89.6,158.0 93.6,146.5 97.5,135.6 101.4,125.3 105.4,115.7 109.3,106.7 113.2,98.3 117.1,90.5 121.1,83.3 125.0,76.8 128.9,70.8 132.9,65.6 136.8,60.9 140.7,56.8 144.6,53.4 148.6,50.6 152.5,48.4 156.4,46.9 160.4,45.9 164.3,45.6 168.2,47.1 172.1,48.8 176.1,50.9 180.0,53.3 183.9,56.0 187.9,59.1 191.8,62.4 195.7,66.1 199.6,70.1 203.6,74.5 207.5,75.7 211.4,77.0 215.4,78.3 219.3,79.6 223.2,80.9 227.1,82.1 231.1,83.4 235.0,84.7 238.9,86.0 242.9,87.3 246.8,88.5 250.7,89.8 254.6,91.1 258.6,92.4 262.5,93.7 266.4,95.0 270.4,96.2 274.3,97.5 278.2,98.8 282.1,100.1 286.1,101.4 290.0,102.6 293.9,103.9 297.9,105.2 301.8,106.5 305.7,107.8 309.6,109.0 313.6,110.3 317.5,111.6 321.4,112.9 325.4,114.2 329.3,115.5 333.2,116.7 337.1,118.0 341.1,119.3 345.0,120.6 348.9,121.9 352.9,123.1 356.8,124.4 360.7,125.7 364.6,127.0 368.6,128.3 372.5,129.5 376.4,130.8 380.4,132.1 384.3,133.4 388.2,134.7 392.1,136.0 396.1,137.2 400.0,138.5 403.9,139.8 407.9,141.1 411.8,142.4 415.7,143.6 419.6,144.9 423.6,146.2 427.5,147.5 431.4,148.8 435.4,150.0 439.3,151.3 443.2,152.6 447.1,153.9 451.1,155.2 455.0,156.5 458.9,157.7 462.9,159.0 466.8,160.3 470.7,161.6 474.6,162.9 478.6,164.1 482.5,165.4 486.4,166.7 490.4,168.0 494.3,169.3 498.2,170.5 502.1,171.8 506.1,173.1 510.0,174.4 513.9,175.7 517.9,177.0 521.8,178.2 525.7,179.5 529.6,180.8 533.6,182.1 537.5,183.4 541.4,184.6 545.4,185.9 549.3,187.2 553.2,188.5 557.1,189.8 561.1,191.0 565.0,192.3 568.9,193.6 572.9,194.9 576.8,196.2 580.7,197.5 584.6,198.7 588.6,200.0 592.5,201.3 596.4,202.6 600.4,203.9 604.3,205.1 608.2,206.4 612.1,207.7 616.1,209.0 620.0,210.3\" stroke=\"#2A9DAE\" stroke-width=\"2.5\"></polyline><rect fill=\"#9fb0c6\" height=\"12\" width=\"12\" x=\"470\" y=\"28\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"540\" y=\"38\">داده خام</text><rect fill=\"#2A9DAE\" height=\"12\" width=\"12\" x=\"470\" y=\"48\"></rect><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"540\" y=\"58\">هموارشده</text></svg><figcaption>شکل ۱۳-۱: نمودار ارتفاع-زمان یک پرواز (داده شبیه‌سازی‌شده)؛ داده خام و هموارشده.</figcaption></figure><p>داده‌ها را در صفحه‌گسترده وارد و نمودار بکشید. از روی نمودار این‌ها را بخوانید: ارتفاع اوج، زمان رسیدن به اوج، لحظه باز شدن چتر (تغییر شیب) و سرعت فرود (شیب بخش پایانی نمودار). برای کاهش نویز، <b>میانگین متحرک</b> بگیرید: هر نقطه را با میانگین ۵ نقطه اطرافش جایگزین کنید.</p><div class=\"ex\"><div class=\"ex-t\">مثال ۱۳-۱: سرعت فرود از نمودار</div><p>در شکل ۱۳-۱، ارتفاع در ثانیه ۶ حدود ۱۸ متر و در ثانیه ۱۲ حدود ۶ متر است.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>تغییر ارتفاع</td><td dir=\"ltr\">18 − 6 = 12 m</td></tr><tr><td>مدت</td><td dir=\"ltr\">12 − 6 = 6 s</td></tr><tr><td>سرعت فرود</td><td dir=\"ltr\">12 ÷ 6 = 2 m/s</td></tr></table></div><p>این سرعت از بازه توصیه‌شده (۳ تا ۶ متر بر ثانیه) کمتر است؛ چتر بزرگ‌تر از لازم است و باد می‌تواند کپسول را دور ببرد.</p></div><h2>مأموریت علمی کپسول</h2><p>در کن‌ست، هر تیم یک «مأموریت ثانویه» دارد: یک پرسش علمی که با داده‌های پرواز پاسخ داده می‌شود. نمونه‌هایی در حد پرتابگر آبی:</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:30%\">مأموریت</th><th style=\"width:30%\">حسگر</th><th style=\"width:40%\">پرسش</th></tr><tr><td class=\"l\">شتاب پرتاب</td><td class=\"l\">شتاب‌سنج سه‌محوره (مانند MPU6050 در بازه ±۱۶g)</td><td class=\"l\">بیشینه شتاب پرتاب چند برابر g است؟ با فشار پرتاب چه رابطه‌ای دارد؟</td></tr><tr><td class=\"l\">ضربه فرود</td><td class=\"l\">شتاب‌سنج</td><td class=\"l\">ضربه فرود با و بدون ضربه‌گیر چقدر فرق دارد؟</td></tr><tr><td class=\"l\">نیمرخ دما و رطوبت</td><td class=\"l\">BME280</td><td class=\"l\">دما و رطوبت در ارتفاع ۰ تا ۳۰ متر تغییر محسوسی دارد؟</td></tr><tr><td class=\"l\">تصویربرداری</td><td class=\"l\">دوربین کوچک یا ESP32-CAM</td><td class=\"l\">از اوج، چه منطقه‌ای دیده می‌شود؟ مقیاس تصویر چقدر است؟</td></tr><tr><td class=\"l\">ارسال داده به ایستگاه زمینی</td><td class=\"l\">ESP32 با ارتباط بی‌سیم (مانند ESP-NOW یا LoRa)</td><td class=\"l\">چند درصد بسته‌ها در پرواز به زمین رسیدند؟</td></tr></table></div><div class=\"box out\"><div class=\"box-t\">پیوند با داوری</div><div>معیار «ثبت ارتفاع با حسگر» (۴ امتیاز) ثبت ارتفاع و نزدیکی آن به پیش‌بینی را می‌سنجد و معیار «مأموریت علمی کپسول» (۴ امتیاز) حسگرها، تصویربرداری یا ارسال داده و <b>تحلیل</b> آن را. داده بدون تحلیل امتیاز کامل ندارد: نمودار بکشید، تفسیر کنید و با پیش‌بینی مقایسه کنید.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>فشار هوا نزدیک زمین به ازای هر ۸ تا ۹ متر حدود ۱ هکتوپاسکال کم می‌شود.</li><li>حسگر BMP280 تغییر ارتفاع حدود یک متر را تشخیص می‌دهد؛ کپسول به سوراخ‌های فشار نیاز دارد.</li><li>اوج را با شرط «ارتفاع کمتر از بیشینه منهای حاشیه» تشخیص دهید و تایمر پشتیبان بگذارید.</li><li>از نمودار ارتفاع-زمان، اوج، زمان‌ها و سرعت فرود خوانده می‌شود.</li><li>مأموریت علمی کپسول یک پرسش علمی را با داده پرواز پاسخ می‌دهد.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>اگر فشار در اوج ۳ هکتوپاسکال کمتر از زمین باشد، ارتفاع تقریبی چقدر است؟</li><li>چرا کپسول به سوراخ‌های فشار نیاز دارد؟</li><li>چرا برای تشخیص اوج از حاشیه ۱٫۵ متر استفاده می‌کنیم؟</li><li>در نمودار یک پرواز، ارتفاع از ۲۴ متر در ثانیه ۴ به ۰ در ثانیه ۱۰ رسیده است. سرعت فرود چقدر است؟ در بازه توصیه‌شده است؟</li><li>یک مأموریت علمی برای کپسول تیم خود پیشنهاد کنید: پرسش، حسگر و روش تحلیل.</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>اگر این ماژول را انتخاب کرده‌اید، حسگر فشار را روی بردبورد راه‌اندازی کنید، آن را از پله‌های یک ساختمان بالا و پایین ببرید و نمودار ارتفاع-زمان بکشید. ارتفاع هر طبقه را از نمودار بخوانید.</div></div>"}, {"t": "شبیه‌سازی و پیش‌بینی عملکرد", "n": "فصل ۱۴", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>شبیه‌سازی گام‌به‌گام پرواز آزاد با صفحه‌گسترده</li><li>برآورد ضریب پسا از پرواز واقعی</li><li>تحلیل پایداری با نرم‌افزار OpenRocket</li><li>مقایسه شبیه‌سازی با پرواز</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۴ (ماژول)<br>۹۰ دقیقه<br>معیار ۱۴ (۳ امتیاز) و معیار ۲</div></div>\n<p>مهندسان پیش از ساختن هر موشک، هزاران بار آن را در رایانه پرواز می‌دهند. شبیه‌سازی به شما اجازه می‌دهد پیش از پرتاب بدانید چه اتفاقی خواهد افتاد و پس از پرتاب بفهمید چرا اتفاق دیگری افتاد.</p><h2>ایده شبیه‌سازی گام‌به‌گام</h2><p>در فصل ۶ دیدید که بدون پسا، ارتفاع = v² ÷ 2g است. اما پسا مدام تغییر می‌کند، چون به سرعت بستگی دارد. راه‌حل: زمان را به گام‌های کوچک (مثلاً یک‌دهم ثانیه) تقسیم کنیم و در هر گام فرض کنیم شتاب ثابت است. سپس سرعت و ارتفاع را گام‌به‌گام جلو ببریم. به این روش، روش «اویلر» می‌گویند.</p><div class=\"fm\" dir=\"ltr\">a = −g − (k ÷ m) × v × |v| ,   k = ½ ρ C<sub>d</sub> A</div><div class=\"fm\" dir=\"ltr\">v<sub>بعدی</sub> = v + a × Δt ,   h<sub>بعدی</sub> = h + v × Δt</div><h2>برگه شبیه‌سازی</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:15%\">ستون</th><th style=\"width:25%\">عنوان</th><th style=\"width:60%\">فرمول نمونه (ردیف ۳)</th></tr><tr><td class=\"l\">A</td><td class=\"l\">زمان t (s)</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">=A2+$H$1</bdi></td></tr><tr><td class=\"l\">B</td><td class=\"l\">ارتفاع h (m)</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">=B2+C2*$H$1</bdi></td></tr><tr><td class=\"l\">C</td><td class=\"l\">سرعت v (m/s)</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">=C2+D2*$H$1</bdi></td></tr><tr><td class=\"l\">D</td><td class=\"l\">شتاب a (m/s²)</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">=-9.8-($H$2/$H$3)*C3*ABS(C3)</bdi></td></tr></table></div><p class=\"hint\">در خانه‌های H1 تا H3 به ترتیب Δt (مثلاً ۰٫۱)، k و m را بنویسید. ردیف ۲ شرایط آغاز پرواز آزاد است: t = ۰، h = ارتفاع پایان پیشرانش (تقریباً صفر) و v = سرعت پایان پیشرانش. فرمول‌ها را به پایین بکشید تا سرعت منفی شود؛ ردیفی که سرعت به صفر می‌رسد، اوج است.</p><div class=\"ex\"><div class=\"ex-t\">مثال ۱۴-۱: نتیجه شبیه‌سازی</div><p>m = ۰٫۲۵ کیلوگرم، قطر بدنه ۹ سانتی‌متر (A ≈ ۰٫۰۰۶۴ متر مربع)، C<sub>d</sub> = ۰٫۵، سرعت پایان پیشرانش ۲۵ متر بر ثانیه.</p><div class=\"tbl\"><table class=\"calc\"><tr><td>k</td><td dir=\"ltr\">0.5 × 1.2 × 0.5 × 0.0064 ≈ 0.0019 kg/m</td></tr><tr><td>شتاب در لحظه آغاز</td><td dir=\"ltr\">−9.8 − (0.0019 ÷ 0.25) × 25² ≈ −14.6 m/s²</td></tr><tr><td>اوج شبیه‌سازی (با پسا)</td><td dir=\"ltr\">≈ 27 m در حدود 2.2 s</td></tr><tr><td>اوج بدون پسا</td><td dir=\"ltr\">25² ÷ 19.6 ≈ 32 m</td></tr></table></div><p>پسا حدود ۱۶ درصد از ارتفاع کم کرده است.</p></div><h2>سرعت پایان پیشرانش را از کجا بیاوریم؟</h2><p>ساده‌ترین راه: از یک پرواز آزمایشی. زمان تا اوج را از ویدئو بخوانید و با برگه شبیه‌سازی، سرعت اولیه را آن‌قدر تغییر دهید تا زمان اوج شبیه‌سازی با ویدئو برابر شود. سپس با همین سرعت، برای پروازهای بعدی (مثلاً با کپسول سنگین‌تر یا بالک‌های دیگر) پیش‌بینی کنید.</p><div class=\"box why\"><div class=\"box-t\">برای دوره دوم: شبیه‌سازی کامل پیشرانش</div><div>می‌توانید مرحله پیشرانش را هم شبیه‌سازی کنید: در هر گام، فشار هوا را از قانون بویل (حجم هوا = حجم بطری − حجم آب باقی‌مانده)، سرعت خروج آب را از v = √(2P ÷ ρ)، جرم آب خارج‌شده را از ρ × A × v × Δt و رانش را از جرم خروجی × سرعت خروج حساب کنید. گام زمانی باید بسیار کوچک (مثلاً یک‌هزارم ثانیه) باشد، چون پیشرانش کمتر از نیم ثانیه طول می‌کشد.</div></div><h2>برآورد ضریب پسا</h2><p>ضریب پسای پرتابگر شما را هیچ کتابی نمی‌داند؛ اما می‌توانید آن را از پرواز به دست آورید. اگر ارتفاع اوج را با زاویه‌سنج یا ارتفاع‌سنج و زمان اوج را از ویدئو داشته باشید، سرعت اولیه و C<sub>d</sub> را در برگه آن‌قدر تغییر دهید تا هر دو عدد با پرواز جور شوند. C<sub>d</sub> پرتابگرهای آبی معمولاً بین ۰٫۳ و ۰٫۸ است.</p><h2>OpenRocket برای پایداری</h2><p>نرم‌افزار رایگان <b>OpenRocket</b> برای موشک‌های مدل ساخته شده است. موتور آبی را مستقیم شبیه‌سازی نمی‌کند، اما برای تحلیل پایداری عالی است:</p><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>یک موشک تازه بسازید و قطعات را اضافه کنید: دماغه (شکل و طول)، لوله بدنه (قطر بطری)، بالک‌ها (شکل، تعداد و ابعاد).</div></li><li><span class=\"sn\">۲</span><div>جرم هر قطعه را با جرم اندازه‌گیری‌شده جایگزین کنید (Override mass) یا یک «جرم نقطه‌ای» برای آب و کپسول اضافه کنید.</div></li><li><span class=\"sn\">۳</span><div>نرم‌افزار جای CG (دایره آبی) و CP (دایره قرمز) و حاشیه پایداری را بر حسب کالیبر (برابر قطر بدنه) نشان می‌دهد.</div></li><li><span class=\"sn\">۴</span><div>اندازه بالک‌ها یا جای وزنه را تغییر دهید و اثر آن را بر پایداری ببینید.</div></li><li><span class=\"sn\">۵</span><div>نتیجه را با روش مقوا و آزمون چرخش (فصل ۵) مقایسه کنید.</div></li></ol><h2>مقایسه با پرواز</h2><div class=\"tbl wide\"><table class=\"wt\"><tr><th style=\"width:30%\">کمیت</th><th style=\"width:20%\">پیش‌بینی</th><th style=\"width:20%\">اندازه‌گیری</th><th style=\"width:15%\">اختلاف</th><th style=\"width:15%\">علت احتمالی</th></tr><tr><td class=\"l\">ارتفاع اوج (m)</td><td class=\"l\">۲۷</td><td class=\"l\">۲۴</td><td class=\"l\">۱۱٪</td><td class=\"l\">باد؛ C<sub>d</sub></td></tr><tr><td class=\"l\">زمان تا اوج (s)</td><td class=\"l\">۲٫۲</td><td class=\"l\">۲٫۱</td><td class=\"l\">۵٪</td><td class=\"l\"></td></tr><tr><td class=\"l\">زمان فرود کپسول (s)</td><td class=\"l\">۵٫۰</td><td class=\"l\">۶٫۲</td><td class=\"l\">۲۴٪</td><td class=\"l\">چتر بزرگ‌تر</td></tr></table></div><p>در پرونده مأموریت، این جدول را با نمودار شبیه‌سازی و نمودار پرواز (در صورت داشتن ارتفاع‌سنج) روی یک شکل بیاورید و اختلاف‌ها را تحلیل کنید.</p><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>شبیه‌سازی گام‌به‌گام (اویلر) اثر پسای متغیر را حساب می‌کند.</li><li>پسا: k = ½ρC<sub>d</sub>A و شتاب a = −g − (k/m)v|v|.</li><li>سرعت پایان پیشرانش و C<sub>d</sub> را با جور کردن شبیه‌سازی با پرواز واقعی پیدا کنید.</li><li>OpenRocket جای CG و CP و حاشیه پایداری را نشان می‌دهد.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>چرا نمی‌توان ارتفاع با پسا را با یک فرمول ساده مانند v² ÷ 2g حساب کرد؟</li><li>k را برای پرتابگری با قطر ۱۰ سانتی‌متر و C<sub>d</sub> = ۰٫۶ حساب کنید (ρ = ۱٫۲).</li><li>در یک گام شبیه‌سازی، v = ۲۰، a = −۱۳ و Δt = ۰٫۱ است. سرعت و ارتفاع گام بعد (با h = ۵) چقدر است؟</li><li>چگونه از یک پرواز واقعی، C<sub>d</sub> پرتابگر را برآورد می‌کنید؟</li><li>OpenRocket کدام کار را برای پرتابگر آبی به‌خوبی انجام می‌دهد و کدام را نه؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>برگه شبیه‌سازی را در صفحه‌گسترده بسازید، با داده یک پرواز آزمایشی تنظیم کنید و برای پرواز رسمی، ارتفاع و زمان اوج را پیش‌بینی کنید.</div></div>"}, {"t": "آزمون‌های زمینی، روز پرتاب و ایمنی", "n": "فصل ۱۵", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>برنامه آزمون‌های زمینی و پروازهای آزمایشی</li><li>آرایش میدان پرتاب و فاصله‌های ایمنی</li><li>فهرست بررسی و شمارش معکوس روز پرتاب</li><li>پرواز رسمی و ویدئوی پیوسته</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۵<br>۹۰ دقیقه<br>معیار ۳ (۱۱ امتیاز) و الزامات ایمنی</div></div>\n<p>هیچ مأموریت فضایی بدون آزمون پرواز نمی‌کند. «آزمون و بهبود» ۱۱ امتیاز دارد و نشان می‌دهد تیم شما مانند مهندسان واقعی کار کرده است: آزموده، شکست خورده، علت را یافته و بهتر کرده است. روز پرتاب هم با یک فهرست بررسی منظم، ایمن و موفق می‌گذرد.</p><h2>آزمون‌های زمینی</h2><p>شیوه‌نامه دست‌کم <b>سه آزمون زمینی مستند</b> می‌خواهد. برنامه پیشنهادی:</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:28%\">آزمون</th><th style=\"width:42%\">چه چیزی را می‌سنجد</th><th style=\"width:30%\">فصل</th></tr><tr><td class=\"l\">آزمون فشار با بطری پر از آب</td><td class=\"l\">استحکام بطری‌ها و سکو تا ۵ بار؛ نشتی</td><td class=\"l\">فصل‌های ۴ و ۸</td></tr><tr><td class=\"l\">آزمون رهاسازی کپسول</td><td class=\"l\">محافظت از تخم‌مرغ در برخورد</td><td class=\"l\">فصل ۹</td></tr><tr><td class=\"l\">آزمون چتر (رهاسازی از بلندی)</td><td class=\"l\">باز شدن چتر و سرعت فرود</td><td class=\"l\">فصل ۱۰</td></tr><tr><td class=\"l\">آزمون سازوکار جداسازی</td><td class=\"l\">قابلیت اطمینان در ۲۰ تکرار</td><td class=\"l\">فصل ۱۲</td></tr><tr><td class=\"l\">آزمون پایداری (CG/CP و چرخش)</td><td class=\"l\">پایداری پرواز</td><td class=\"l\">فصل ۵</td></tr><tr><td class=\"l\">آزمون رهاساز سکو</td><td class=\"l\">آزادسازی مطمئن و هم‌زمان</td><td class=\"l\">فصل ۸</td></tr></table></div><p>هر آزمون را با این ساختار ثبت کنید: هدف، روش، نتیجه (با عدد و عکس)، و اصلاحی که پس از آن انجام دادید.</p><h2>پروازهای آزمایشی</h2><ul class=\"ul\"><li>نخستین پرواز را با فشار کم (۲ تا ۳ بار)، بدون تخم‌مرغ و با وزنه هم‌جرم انجام دهید.</li><li>در هر پرواز فقط یک چیز را تغییر دهید (مثلاً مقدار آب یا اندازه بالک) تا بفهمید کدام تغییر چه اثری داشت.</li><li>از هر پرواز فیلم بگیرید و کاربرگ ثبت پرواز را کامل کنید، حتی پروازهای ناموفق. پروازهای ناموفق و اصلاحات پس از آن، ارزشمندترین بخش پرونده‌اند.</li><li>وقتی همه زیرسامانه‌ها با وزنه کار کردند، با تخم‌مرغ خام پرواز کنید.</li></ul><h2>میدان پرتاب</h2><figure class=\"f\"><svg class=\"ill\" viewbox=\"0 0 690 300\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"rg\" markerheight=\"10\" markerwidth=\"10\" orient=\"auto\" refx=\"8\" refy=\"3\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#1B2A4A\"></path></marker></defs><rect fill=\"#eef6e8\" height=\"300\" rx=\"12\" stroke=\"#d9e2ee\" width=\"690\"></rect><circle cx=\"520\" cy=\"150\" fill=\"#FDECEA\" opacity=\".7\" r=\"120\" stroke=\"#C0392B\" stroke-dasharray=\"6 5\"></circle><circle cx=\"520\" cy=\"150\" fill=\"#1B2A4A\" r=\"10\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"132\">سکو</text><circle cx=\"435\" cy=\"150\" fill=\"#2A9DAE\" r=\"9\"></circle><text fill=\"#2A9DAE\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"435\" y=\"176\">اپراتور</text><line stroke=\"#a0522d\" stroke-width=\"2\" x1=\"508.0\" x2=\"445.0\" y1=\"150.0\" y2=\"150.0\"></line><text fill=\"#a0522d\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"middle\" x=\"478\" y=\"142\">≥ ۵ متر</text><circle cx=\"150\" cy=\"140\" fill=\"#5a6b82\" r=\"8\"></circle><circle cx=\"185\" cy=\"160\" fill=\"#5a6b82\" r=\"8\"></circle><circle cx=\"220\" cy=\"140\" fill=\"#5a6b82\" r=\"8\"></circle><circle cx=\"255\" cy=\"160\" fill=\"#5a6b82\" r=\"8\"></circle><circle cx=\"290\" cy=\"140\" fill=\"#5a6b82\" r=\"8\"></circle><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"220\" y=\"200\">تماشاگران پشت اپراتور</text><line stroke=\"#1B2A4A\" stroke-dasharray=\"4 4\" stroke-width=\"1.5\" x1=\"420.0\" x2=\"420.0\" y1=\"60.0\" y2=\"240.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11.5\" font-weight=\"bold\" text-anchor=\"start\" x=\"413\" y=\"70\">≥ ۱۰ متر از سکو</text><text fill=\"#C0392B\" font-family=\"Vazirmatn\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" x=\"520\" y=\"290\">منطقه ممنوع هنگام فشار</text><line marker-end=\"url(#rg)\" stroke=\"#1B2A4A\" stroke-width=\"2\" x1=\"660.0\" x2=\"610.0\" y1=\"40.0\" y2=\"60.0\"></line><text fill=\"#1B2A4A\" font-family=\"Vazirmatn\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"start\" x=\"665\" y=\"35\">جهت باد</text></svg><figcaption>شکل ۱۵-۱: آرایش میدان پرتاب و فاصله‌های ایمنی.</figcaption></figure><div class=\"box warn\"><div class=\"box-t\">الزامات ایمنی</div><div><ul class=\"ul\"><li>فضای باز و خلوت، دور از خیابان، ساختمان، درخت بلند و سیم برق.</li><li>زاویه پرتاب نزدیک به قائم و رو به دور از افراد؛ در باد، کمی رو به باد.</li><li>پر کردن هوا و رهاسازی از دست‌کم ۱٫۵ متر با رهاساز از راه دور (توصیه این کتاب: ۵ متر)؛ تماشاگران دست‌کم ۱۰ متر دورتر و پشت اپراتور (الزام ستاره‌دار).</li><li>عینک ایمنی برای اپراتورها.</li><li>باد ملایم؛ در باد شدید پرتاب نکنید.</li><li>شمارش معکوس بلند؛ همه پیش از پرتاب آماده و ساکت باشند.</li><li>همه پرتاب‌ها زیر نظر مربی.</li></ul></div></div><h2>نقش‌ها در روز پرتاب</h2><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:24%\">نقش</th><th style=\"width:76%\">وظیفه</th></tr><tr><td class=\"l\">مدیر پرتاب (مربی یا سرگروه)</td><td class=\"l\">تأیید ایمنی میدان، اعلام آماده‌باش و شمارش معکوس، دستور لغو در صورت خطر</td></tr><tr><td class=\"l\">اپراتور سکو</td><td class=\"l\">پر کردن هوا، کنترل فشارسنج، برداشتن ضامن و کشیدن طناب رهاساز</td></tr><tr><td class=\"l\">فیلم‌بردار</td><td class=\"l\">ویدئوی پیوسته پرواز رسمی از پر کردن هوا تا باز کردن کپسول</td></tr><tr><td class=\"l\">ناظران ارتفاع</td><td class=\"l\">اندازه‌گیری زاویه اوج از فاصله معلوم</td></tr><tr><td class=\"l\">تیم بازیابی</td><td class=\"l\">دنبال کردن کپسول و قطعات و جمع‌آوری آن‌ها پس از اعلام پایان پرواز</td></tr></table></div><h2>فهرست بررسی روز پرتاب</h2><ul class=\"check\"><li>بطری‌ها سالم و آزمون‌شده‌اند؛ بالک‌ها و دماغه محکم‌اند.</li><li>سکو مهار شده، رهاساز آزموده شده و ضامن در جای خود است.</li><li>فشارسنج، شیر یک‌طرفه و شیر تخلیه کار می‌کنند.</li><li>چتر درست تا شده و سازوکار جداسازی مسلح شده است.</li><li>تخم‌مرغ در کپسول و در کپسول مهار شده است.</li><li>باتری‌ها شارژ و الکترونیک روشن است (در صورت وجود).</li><li>مقدار آب و فشار پرتاب در کاربرگ ثبت شده است.</li><li>ارتفاع پیش‌بینی‌شده نوشته شده است.</li><li>فیلم‌بردار، ناظران و تماشاگران در جای خود هستند.</li><li>وضعیت باد بررسی شده است.</li></ul><h2>شمارش معکوس</h2><ol class=\"steps\"><li><span class=\"sn\">۱</span><div>«آماده‌باش برای پر کردن»: همه پشت خط ۱۰ متری؛ اپراتور کنار شیر و پمپ در فاصله ۵ متری.</div></li><li><span class=\"sn\">۲</span><div>پر کردن هوا تا فشار تعیین‌شده؛ اپراتور فشار را با صدای بلند اعلام می‌کند.</div></li><li><span class=\"sn\">۳</span><div>«ضامن برداشته شد»: اپراتور از فاصله دور ضامن را با نوار رنگی می‌کشد (یا ضامن از راه دور طراحی شده است).</div></li><li><span class=\"sn\">۴</span><div>«شمارش معکوس: پنج، چهار، سه، دو، یک، پرتاب!» و کشیدن طناب رهاساز.</div></li><li><span class=\"sn\">۵</span><div>همه پرتابگر را تا فرود نگاه می‌کنند؛ پس از اعلام «پایان پرواز»، تیم بازیابی وارد میدان می‌شود.</div></li></ol><div class=\"box warn\"><div class=\"box-t\">اگر پرتابگر رها نشد</div><div>به پرتابگر نزدیک نشوید. با شیر تخلیه فشار را کاملاً خالی کنید، صبر کنید تا فشارسنج صفر شود و سپس با اجازه مدیر پرتاب، علت را بررسی کنید.</div></div><h2>پرواز رسمی</h2><p>تیم یکی از پروازهای خود را به‌عنوان <b>پرواز رسمی</b> معرفی می‌کند. این پرواز باید در حضور مربی یا نماینده پژوهش‌سرا انجام و با <b>یک ویدئوی پیوسته و بدون تدوین</b> ثبت شود: از پر کردن هوا تا فرود، باز کردن کپسول و نمایش تخم‌مرغ سالم. کاربرگ ثبت پرواز (پیوست ۲ این کتاب، همان کاربرگ پیوست ث شیوه‌نامه) توسط ناظر امضا می‌شود. نبود یا ناواضح بودن این ویدئو موجب حذف اثر از داوری می‌شود؛ امتیاز ردیف‌های ۴ تا ۱۲ جدول داوری بر پایه همین ویدئو و کاربرگ ثبت پرواز، و امتیاز ردیف‌های ۱۳ و ۱۴ بر پایه پرونده مأموریت و فایل‌های داده داده می‌شود. ویدئوی پرواز رسمی حداکثر ۸ دقیقه، MP4 و حداکثر ۱۲۰ مگابایت است.</p><div class=\"box tip\"><div class=\"box-t\">فیلم‌برداری پرواز رسمی</div><div>دوربین را روی سه‌پایه بگذارید و از فاصله‌ای فیلم بگیرید که سکو و آسمان بالای آن در کادر باشد. فیلم‌بردار باید پس از پرتاب، پرتابگر و کپسول را دنبال کند و بدون قطع ضبط، تا محل فرود برود و باز کردن کپسول را نشان دهد. یک دوربین دوم ثابت (مثلاً تلفن همراه دیگر) برای تحلیل زمان‌ها بسیار مفید است.</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>دست‌کم سه آزمون زمینی مستند با هدف، روش، نتیجه و اصلاح لازم است.</li><li>پروازهای آزمایشی را با فشار کم شروع کنید و در هر پرواز یک چیز را تغییر دهید.</li><li>فاصله‌های ۵ و ۱۰ متری، عینک ایمنی و نظارت مربی الزامی است.</li><li>فهرست بررسی و شمارش معکوس منظم، روز پرتاب را ایمن می‌کند.</li><li>پرواز رسمی با ویدئوی پیوسته و کاربرگ امضاشده ثبت می‌شود.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>سه آزمون زمینی که برای مأموریت تیم خود انجام می‌دهید، نام ببرید.</li><li>چرا در هر پرواز آزمایشی فقط یک چیز را تغییر می‌دهیم؟</li><li>فاصله‌های ایمنی اپراتور و تماشاگران چقدر است؟</li><li>اگر رهاساز گیر کند، چه می‌کنید؟</li><li>ویدئوی پرواز رسمی باید از کجا تا کجا را بدون قطع نشان دهد؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>یک روز پرتاب تمرینی برگزار کنید: نقش‌ها را تقسیم کنید، فهرست بررسی را اجرا کنید و دست‌کم دو پرواز آزمایشی با وزنه انجام دهید. کاربرگ ثبت پرواز را برای هر پرواز کامل کنید.</div></div>"}, {"t": "تحلیل پس از پرواز، پرونده مأموریت و فیلم", "n": "فصل ۱۶", "h": "\n\n<div class=\"ch-meta\"><div class=\"goals\"><div class=\"gt\">در این فصل یاد می‌گیرید</div><ul class=\"ul\"><li>تحلیل موفقیت یا شکست هر مرحله</li><li>ساختار پرونده مأموریت (حداکثر ۲۰ صفحه)</li><li>فیلم گزارش مأموریت ۵ تا ۸ دقیقه‌ای</li><li>مستندات ارسالی، مصاحبه و خودارزیابی</li></ul></div>\n<div class=\"sess\"><b>برای معلم</b><br>جلسه ۱۶<br>۹۰ دقیقه<br>معیارهای ۱۵ و ۱۶ (۹ امتیاز)</div></div>\n<p>مأموریت با فرود کپسول تمام نمی‌شود. در آژانس‌های فضایی، پس از هر پرواز، جلسه «تحلیل پس از پرواز» برگزار می‌شود: چه چیزی خوب کار کرد؟ چه چیزی نه؟ چرا؟ دفعه بعد چه می‌کنیم؟ این تحلیل، آخرین بخش پرونده مأموریت شماست.</p><h2>تحلیل پس از پرواز</h2><div class=\"tbl wide\"><table class=\"wt\"><tr><th style=\"width:22%\">مرحله</th><th style=\"width:22%\">پیش‌بینی</th><th style=\"width:22%\">نتیجه</th><th style=\"width:12%\">موفق؟</th><th style=\"width:22%\">علت و درس‌آموخته</th></tr><tr><td class=\"l\">پرتاب</td><td class=\"l\">پرواز راست</td><td class=\"l\">انحراف ۱۰ درجه به سمت باد</td><td class=\"l\">✓</td><td class=\"l\">باد ۲ متر بر ثانیه؛ پایداری خوب</td></tr><tr><td class=\"l\">جدایش بوسترها</td><td class=\"l\">در ۰٫۳ ثانیه</td><td class=\"l\">یک بوستر دیرتر جدا شد</td><td class=\"l\">✗</td><td class=\"l\">اصطکاک زبانه؛ صاف کردن شانه</td></tr><tr><td class=\"l\">اوج</td><td class=\"l\">۲۷ متر</td><td class=\"l\">۲۴ متر</td><td class=\"l\">✓</td><td class=\"l\">اختلاف ۱۱ درصد</td></tr><tr><td class=\"l\">جدایش کپسول</td><td class=\"l\">۲٫۲ ثانیه</td><td class=\"l\">۲٫۴ ثانیه</td><td class=\"l\">✓</td><td class=\"l\"></td></tr><tr><td class=\"l\">چتر</td><td class=\"l\">سرعت ۴ m/s</td><td class=\"l\">سرعت ۳٫۵ m/s</td><td class=\"l\">✓</td><td class=\"l\"></td></tr><tr><td class=\"l\">محموله</td><td class=\"l\">سالم</td><td class=\"l\">سالم</td><td class=\"l\">✓</td><td class=\"l\"></td></tr></table></div><div class=\"box tip\"><div class=\"box-t\">شکست، شکست نیست</div><div>یک پرواز ناموفق که علتش را یافته و اصلاح کرده‌اید، در پرونده مأموریت از یک پرواز موفق بی‌توضیح ارزشمندتر است. هر شکست را با عکس، توضیح علت و اصلاح انجام‌شده ثبت کنید.</div></div><h2>پرونده مأموریت</h2><p>پرونده مأموریت در قالب PDF و حداکثر ۲۰ صفحه است و پنج بخش دارد:</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:26%\">بخش</th><th style=\"width:54%\">محتوا</th><th style=\"width:20%\">صفحه</th></tr><tr><td class=\"l\">۱. تعریف مأموریت</td><td class=\"l\">هدف، ماژول‌های انتخابی، الزامات، معیارهای موفقیت، معماری سامانه، نقش‌ها</td><td class=\"l\">۲ تا ۳</td></tr><tr><td class=\"l\">۲. طراحی</td><td class=\"l\">طرح اجزا، بودجه جرم، محاسبات (پایداری، اندازه چتر، برآورد ارتفاع)، شبیه‌سازی</td><td class=\"l\">۴ تا ۵</td></tr><tr><td class=\"l\">۳. آزمون‌های زمینی</td><td class=\"l\">دست‌کم سه آزمون: هدف، روش، نتیجه، اصلاح</td><td class=\"l\">۳ تا ۴</td></tr><tr><td class=\"l\">۴. پروازها</td><td class=\"l\">گزارش همه پروازهای آزمایشی و رسمی و اصلاحات پس از هر پرواز</td><td class=\"l\">۳ تا ۴</td></tr><tr><td class=\"l\">۵. تحلیل پس از پرواز</td><td class=\"l\">مقایسه پیش‌بینی با نتیجه، علت موفقیت یا شکست هر مرحله، درس‌آموخته‌ها</td><td class=\"l\">۲ تا ۳</td></tr></table></div><ul class=\"ul\"><li>عکس‌های واقعی ساخت و آزمون، بهترین شاهد کار شما هستند.</li><li>محاسبات را با رابطه، جای‌گذاری و یکا بنویسید.</li><li>هر جدول و نمودار شماره، عنوان و یکا داشته باشد.</li><li>نام نرم‌افزارها و ابزارهای هوش مصنوعی استفاده‌شده را بنویسید و پرامپت‌ها را پیوست کنید.</li></ul><h2>فیلم گزارش مأموریت</h2><p>فیلم ۵ تا ۸ دقیقه‌ای (MP4، حداکثر ۱۲۰ مگابایت) شامل طراحی، ساخت، آزمون‌ها، پرواز و تحلیل است و همه اعضا در ارائه سهم دارند. این فیلم با ویدئوی پیوسته پرواز رسمی فرق دارد: فیلم گزارش تدوین‌شده و روایی است.</p><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:30%\">بخش فیلم</th><th style=\"width:20%\">زمان پیشنهادی</th><th style=\"width:50%\">محتوا</th></tr><tr><td class=\"l\">معرفی تیم و مأموریت</td><td class=\"l\">۰٫۵ تا ۱ دقیقه</td><td class=\"l\">اعضا، هدف، ماژول‌ها</td></tr><tr><td class=\"l\">طراحی و محاسبات</td><td class=\"l\">۱ تا ۱٫۵ دقیقه</td><td class=\"l\">نمودار معماری، پایداری، چتر</td></tr><tr><td class=\"l\">ساخت</td><td class=\"l\">۱ دقیقه</td><td class=\"l\">پرتابگر، کپسول، سکو</td></tr><tr><td class=\"l\">آزمون‌ها</td><td class=\"l\">۱ تا ۱٫۵ دقیقه</td><td class=\"l\">آزمون فشار، رهاسازی، جداسازی</td></tr><tr><td class=\"l\">پرواز</td><td class=\"l\">۱ دقیقه</td><td class=\"l\">بهترین تصاویر پروازها؛ فیلم آهسته جدایش‌ها</td></tr><tr><td class=\"l\">تحلیل</td><td class=\"l\">۱ دقیقه</td><td class=\"l\">پیش‌بینی و نتیجه، درس‌آموخته‌ها</td></tr></table></div><h2>مستندات ارسالی</h2><ul class=\"check\"><li>نمون‌برگ ۱ (توضیحات ۱: چکیده مأموریت؛ ۲: ماژول‌های تکمیلی؛ ۳: نوآوری‌ها)</li><li>پرونده مأموریت PDF (حداکثر ۲۰ صفحه)</li><li>فیلم گزارش مأموریت ۵ تا ۸ دقیقه‌ای (MP4، حداکثر ۱۲۰ مگابایت)</li><li>ویدئوی پیوسته پرواز رسمی بدون تدوین (حداکثر ۸ دقیقه، MP4، حداکثر ۱۲۰ مگابایت)</li><li>کاربرگ ثبت پرواز رسمی با امضای مربی یا نماینده پژوهش‌سرا</li><li>فایل داده‌های حسگرها و متن برنامه‌ها (در صورت استفاده)</li><li>پرامپت‌های هوش مصنوعی (در صورت استفاده)</li><li>کارنامه سفر یادگیری آسمان‌نما با کد QR برای هر عضو (اختیاری) و عکس پرسنلی هر عضو با نام کد ملی او</li><li>همه درون پوشه‌ای با نام کد تیم و به‌صورت فشرده (ZIP)</li></ul><h2>مصاحبه و پرتاب زنده</h2><p>در مرحله دوم استانی و کشوری، داوران با همه اعضا هم‌زمان مصاحبه می‌کنند و در برگزاری حضوری ممکن است <b>پرتاب زنده</b> درخواست کنند. پرتابگر و سکو را سالم نگه دارید. نمونه پرسش‌ها: «حاشیه پایداری پرتابگرتان چقدر است و چگونه اندازه گرفتید؟»، «اندازه چتر را چگونه حساب کردید؟»، «بزرگ‌ترین شکست شما چه بود و چگونه آن را حل کردید؟»، «اگر یک بوستر رها نشود چه اتفاقی می‌افتد؟».</p><p>زمان ثبت‌نام، ارسال اثر و هر مرحله داوری در تقویم اجرایی جشنواره (پیوست الف شیوه‌نامه) آمده است. اعتراض به نتیجه داوری فقط در بازه اعلام‌شده (هم‌زمان با مرحله دوم استانی و کشوری) و از مسیر تعیین‌شده، با دلیل و مستند ثبت می‌شود (بند «چ» بخش اول شیوه‌نامه).</p><h2>خودارزیابی با جدول داوری</h2><div class=\"ws-h\">کاربرگ ۱۶-۱: خودارزیابی تیم</div><div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:56%\">معیار</th><th style=\"width:10%\">امتیاز</th><th style=\"width:22%\">شاهد ما</th><th style=\"width:12%\">خودارزیابی</th></tr><tr><td class=\"l\">۱. تعریف مأموریت</td><td class=\"l\">۷</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۲. طراحی و محاسبات</td><td class=\"l\">۹</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۳. آزمون و بهبود</td><td class=\"l\">۱۱</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۴. پرتابگر</td><td class=\"l\">۷</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۵. سکوی پرتاب</td><td class=\"l\">۶</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۶. سامانه بازیابی</td><td class=\"l\">۱۰</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۷. سلامت محموله</td><td class=\"l\">۹</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۸. سنجش عملکرد</td><td class=\"l\">۴</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۹ تا ۱۴. ماژول‌های تکمیلی (حداکثر ۱۸): بوستر ۷، جداسازی بوسترها یا مراحل ۵، جداسازی کپسول ۶، ثبت ارتفاع با حسگر ۴، مأموریت علمی ۴، شبیه‌سازی ۳</td><td class=\"l\">۱۸</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۱۵. پرونده مأموریت و فیلم</td><td class=\"l\">۵</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۱۶. تسلط و کار تیمی</td><td class=\"l\">۴</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\">۱۷. سفر یادگیری آسمان‌نما</td><td class=\"l\">۱۰</td><td class=\"l\"></td><td class=\"l\"></td></tr><tr><td class=\"l\"><b>جمع</b></td><td class=\"l\"><b>۱۰۰</b></td><td class=\"l\"></td><td class=\"l\"></td></tr></table></div><div class=\"box why\"><div class=\"box-t\">سخن پایانی</div><div>شما در این مسیر، همان کارهایی را انجام دادید که مهندسان هوافضا انجام می‌دهند: تعریف مأموریت، محاسبه، ساخت، آزمون، شکست، اصلاح و پرواز. شاید روزی یکی از شما پرتابگری را طراحی کند که ماهواره‌ای واقعی را به مدار می‌برد. سه، دو، یک، پرتاب!</div></div><div class=\"summary\"><div class=\"st\">خلاصه فصل</div><ul class=\"ul\"><li>تحلیل پس از پرواز، پیش‌بینی و نتیجه هر مرحله را مقایسه و علت‌ها را بررسی می‌کند.</li><li>پرونده مأموریت پنج بخش دارد و حداکثر ۲۰ صفحه است.</li><li>فیلم گزارش ۵ تا ۸ دقیقه و تدوین‌شده است؛ ویدئوی پرواز رسمی پیوسته و بدون تدوین.</li><li>مستندات کامل درون پوشه‌ای با نام کد تیم، به‌صورت فشرده (ZIP)؛ برای مصاحبه و پرتاب زنده آماده باشید.</li></ul></div><div class=\"questions\"><div class=\"qt\">پرسش‌ها و تمرین‌ها</div><ol class=\"qs\"><li>پنج بخش پرونده مأموریت را نام ببرید.</li><li>تفاوت فیلم گزارش مأموریت و ویدئوی پرواز رسمی چیست؟</li><li>چرا گزارش پروازهای ناموفق در پرونده ارزشمند است؟</li><li>در یک پرواز، چتر باز نشد اما تخم‌مرغ سالم ماند. در تحلیل پس از پرواز چه می‌نویسید؟</li><li>سقف امتیاز ماژول‌ها چقدر است؟ تیمی که بوستر (۷)، جداسازی کپسول (۶)، سنجش ارتفاع (۴) و شبیه‌سازی (۳) را کامل انجام دهد، چه امتیازی از این بخش می‌گیرد؟</li></ol></div><div class=\"box out\"><div class=\"box-t\">فعالیت عملی پروژه</div><div>پیش‌نویس پرونده مأموریت را بنویسید، کاربرگ خودارزیابی را کامل کنید و برنامه فیلم‌برداری فیلم گزارش را تهیه کنید.</div></div>"}, {"t": "راهنمای پاسخ برای معلم", "n": "پیوست ۱", "h": "<p>پاسخ پرسش‌های محاسباتی و نکته‌های کلیدی پرسش‌های مفهومی. عددها گرد شده‌اند. پرسش‌هایی که پاسخ آن‌ها به طرح هر تیم وابسته است، «پاسخ باز» دارند؛ در این موارد استدلال و هماهنگی با مأموریت تیم را ارزیابی کنید.</p><h3>فصل ۱: یک مأموریت فضایی از آغاز تا پایان</h3><ol class=\"qs ans\"><li>پرتاب، جدایش بوسترها، جدایش مراحل، جدا شدن پوشش دماغه، رساندن محموله، انجام مأموریت و ارسال داده، بازگشت و فرود.</li><li>مخزن خالی و موتورش وزن مرده‌اند؛ دور ریختن آن‌ها موشک را سبک‌تر می‌کند تا با سوخت باقی‌مانده سرعت بیشتری بگیرد.</li><li>بوستر در کنار بدنه و هم‌زمان با آن کار می‌کند؛ مراحل روی هم‌اند و یکی پس از دیگری کار می‌کنند.</li><li>سپر حرارتی و چترها، موتورهای فرود نرم پیش از برخورد و صندلی‌های ضربه‌گیر.</li><li>نقش سرنشین یا محموله حساس؛ چون شکننده است و سالم ماندن یا شکستنش موفقیت را آشکارا نشان می‌دهد.</li><li>چون هدف، اجرای ایمن و هماهنگ مأموریت و بازگشت سالم محموله است، نه رقابت ارتفاع که ایمنی را کم می‌کند؛ ارتفاع اوج فقط تا ۳ امتیاز در ردیف ۴ دارد.</li></ol><h3>فصل ۲: تعریف مأموریت و مهندسی سامانه</h3><ol class=\"qs ans\"><li>هدف کلی است؛ معیار موفقیت عددی یا قابل مشاهده است. نمونه: هدف «بازگرداندن سالم تخم‌مرغ»؛ معیار «سرعت فرود بین ۳ و ۶ متر بر ثانیه».</li><li>«ب»؛ عدد مشخص دارد و قابل بررسی است.</li><li>پاسخ باز؛ نمونه: «چتر پیش از نیمه راه فرود کاملاً باز شود»؛ «درِ کپسول در شتاب پرتاب باز نشود».</li><li>تا حتی اگر بخشی کار نکرد، بتوان موفقیت بخش‌های دیگر را دقیق گزارش کرد.</li><li>بوستر و جداسازی کپسول با سازوکار مکانیکی؛ در صورت تمایل شبیه‌سازی صفحه‌گسترده.</li></ol><h3>فصل ۳: فیزیک پرواز موشک</h3><ol class=\"qs ans\"><li>۰٫۰۶ × ۹٫۸ ≈ ۰٫۵۹ نیوتن.</li><li>پاسخ باز با سه مثال درست از لختی، شتاب و کنش-واکنش.</li><li>چگالی هوا بسیار کم است و جرم کمی در هر ثانیه بیرون رانده می‌شود؛ رانش ناچیز است.</li><li>در اوج؛ سرعت کمترین است و چتر با کمترین ضربه باز می‌شود.</li><li>۴ برابر.</li><li>نیروی کل ۱۰۰ − ۴٫۹ ≈ ۹۵ نیوتن؛ شتاب ≈ ۱۹۰ متر بر مجذور ثانیه.</li></ol><h3>فصل ۴: فشار، هوای فشرده و ایمنی محفظه</h3><ol class=\"qs ans\"><li>۳٫۵ × ۱۴٫۵ ≈ ۵۱ PSI و ۳۵۰ کیلوپاسکال.</li><li>حدود ۵٫۵ بار.</li><li>آب تراکم‌پذیر نیست و انرژی کمی ذخیره می‌کند؛ اگر بطری بترکد، خطر کمی دارد.</li><li>هوا ۱٫۳ لیتر در ۵ بار مطلق ⟵ ۲ لیتر: ۵ × ۱٫۳ ÷ ۲ = ۳٫۲۵ بار مطلق، یعنی حدود ۲٫۲۵ بار نسبی.</li><li>خراش یا فرورفتگی، سفید شدن پلاستیک، تماس با گرما یا چسب حلال‌دار.</li><li>برای نگه‌داشتن گاز تحت فشار طراحی نشده و دیواره آن ضعیف‌تر است.</li></ol><h3>فصل ۵: پایداری پرواز: مرکز جرم و مرکز فشار</h3><ol class=\"qs ans\"><li>وزن بیشتر در جلو و پرها در عقب؛ پرها هر انحراف را اصلاح می‌کنند.</li><li>حاشیه ۱۰ سانتی‌متر ≈ ۱٫۱ برابر قطر؛ پایدار است.</li><li>آب در عقب (کنار نازل) است و CG را به عقب می‌برد؛ حالت با آب بحرانی‌تر است.</li><li>وزنه در دماغه؛ بالک‌های بزرگ‌تر یا عقب‌تر.</li><li>پرتابگر را می‌چرخاند و مسیر پیش‌بینی‌ناپذیر و خطرناک می‌شود.</li><li>CG را جلو می‌برد و پایداری را بیشتر می‌کند، اما جرم و چتر لازم بیشتر می‌شود.</li></ol><h3>فصل ۶: پیش‌بینی و اندازه‌گیری ارتفاع و زمان پرواز</h3><ol class=\"qs ans\"><li>h ≈ ۱۸² ÷ ۱۹٫۶ ≈ ۱۶٫۵ متر؛ t ≈ ۱٫۸ ثانیه.</li><li>۲۵ × ۱ + ۱٫۵ = ۲۶٫۵ متر.</li><li>۴٫۹ × ۴ ≈ ۱۹٫۶ متر؛ پسا را نادیده گرفته‌ایم.</li><li>تا جابه‌جایی پرتابگر به سوی ناظر یا دور از او، زاویه را خطادار نکند.</li><li>۲۱ ÷ ۶ = ۳٫۵ متر بر ثانیه؛ بله.</li><li>|۲۱ − ۲۵| ÷ ۲۵ × ۱۰۰ = ۱۶ درصد.</li></ol><h3>فصل ۷: ساخت پرتابگر</h3><ol class=\"qs ans\"><li>گرما و حلال‌ها پلاستیک PET را ضعیف می‌کنند و ممکن است بطری زیر فشار بترکد.</li><li>۲۸ ÷ ۳ ≈ ۹٫۳ سانتی‌متر؛ ۲۸ ÷ ۴ = ۷ سانتی‌متر.</li><li>تا بالک خم نشود و در برابر هوا محکم بماند.</li><li>تا به سکو و رهاساز گیر نکند.</li><li>بطری سالم؛ دماغه نرم؛ بالک بدون لبه تیز و نبود قطعه فلزی بیرونی.</li></ol><h3>فصل ۸: ساخت سکوی پرتاب</h3><ol class=\"qs ans\"><li>پایداری و استحکام، فشارسنج، ضامن ایمنی و رهاساز از راه دور.</li><li>سر بست‌ها لبه گردن بطری را می‌گیرند و غلاف آن‌ها را جمع نگه می‌دارد؛ با کشیدن غلاف، بست‌ها باز و بطری آزاد می‌شود.</li><li>چون نزدیک شدن به پرتابگر تحت فشار ممنوع است؛ تخلیه باید از راه دور انجام شود.</li><li>۵ + ۴ + حدود ۰٫۵ تا ۱ = حدود ۹٫۵ تا ۱۰ سانتی‌متر.</li><li>تا فشار همه بطری‌ها یکسان باشد.</li><li>رانش نامتقارن، پرتابگر را منحرف یا ناپایدار می‌کند.</li></ol><h3>فصل ۹: کپسول مأموریت و محافظت از تخم‌مرغ</h3><ol class=\"qs ans\"><li>√(۲ × ۹٫۸ × ۱٫۲۵) ≈ ۴٫۹ متر بر ثانیه.</li><li>a = ۲۵ ÷ ۰٫۱ = ۲۵۰ متر بر مجذور ثانیه ≈ ۲۵ g.</li><li>دو سر تخم‌مرغ مقاوم‌ترین بخش‌اند.</li><li>هدف، طراحی مهندسی کپسول است؛ پوشاندن تخم‌مرغ آن را دور می‌زند.</li><li>در پیچی؛ میله‌های قفل‌کننده؛ کش لاستیکی روی قلاب.</li></ol><h3>فصل ۱۰: سامانه بازیابی و چتر نجات</h3><ol class=\"qs ans\"><li>سرعتی که در آن پسا برابر وزن است؛ پس از آن نیروی کل صفر و سرعت ثابت است.</li><li>A ≈ ۲ × ۰٫۲۵ × ۹٫۸ ÷ (۱٫۲ × ۰٫۸ × ۲۵) ≈ ۰٫۲۰ متر مربع؛ D ≈ ۰٫۵۱ متر.</li><li>نصف می‌شود.</li><li>هوا را آرام بیرون می‌دهد و از تاب خوردن شدید چتر جلوگیری می‌کند.</li><li>نیروی پسا در سرعت زیاد بسیار بزرگ است و چتر یا نخ‌ها پاره می‌شوند.</li><li>(۳۰ − ۶) ÷ ۵ = ۴٫۸ ثانیه.</li></ol><h3>فصل ۱۱: ماژول بوستر و پرتابگر چندمرحله‌ای</h3><ol class=\"qs ans\"><li>رانش و پسای نامتقارن پرتابگر را منحرف می‌کند.</li><li>پس از خاموشی بوستر، بوستر عقب می‌ماند و زبانه‌اش از زیر شانه یقه رانش می‌لغزد.</li><li>تا عقب بمانند و جدا شوند؛ آب کمتر در بوسترها یا بطری اصلی بزرگ‌تر.</li><li>نوار کندکننده، چتر کوچک یا مهار با بند به بدنه.</li><li>برای آزمودن ایمن اتصال‌ها و پایداری با انرژی کمتر.</li><li>آب‌بندی مرحله دوم تا لحظه جدایش، زمان‌بندی آزادسازی و پر کردن هوای آن.</li></ol><h3>فصل ۱۲: سازوکارهای جداسازی و فعال‌سازی</h3><ol class=\"qs ans\"><li>عمل در زمان درست، ایمن در برابر شتاب پرتاب، قابل آزمون؛ سبک.</li><li>فشار هوای روبه‌رو آن را سر جایش نگه می‌دارد.</li><li>حدود ۲٫۲ ثانیه؛ کمی بعد از اوج بهتر از کمی قبل از آن است، چون سرعت کم است.</li><li>لحظه جدا شدن پرتابگر از سکو را به میکروکنترلر اعلام و زمان‌سنجی را آغاز می‌کند.</li><li>۱۶ ÷ ۲۰ = ۸۰ درصد؛ نه، باید علت شکست‌ها یافته و طرح اصلاح شود.</li></ol><h3>فصل ۱۳: ارتفاع‌سنج و مأموریت علمی کپسول (کن‌ست)</h3><ol class=\"qs ans\"><li>حدود ۲۵ تا ۲۷ متر.</li><li>تا فشار درون کپسول با بیرون برابر شود.</li><li>برای اینکه نویز حسگر، اوج را به اشتباه اعلام نکند.</li><li>۲۴ ÷ ۶ = ۴ متر بر ثانیه؛ بله.</li><li>پاسخ باز.</li></ol><h3>فصل ۱۴: شبیه‌سازی و پیش‌بینی عملکرد</h3><ol class=\"qs ans\"><li>پسا با سرعت تغییر می‌کند و فرمول ساده آن را در نظر نمی‌گیرد.</li><li>k = ۰٫۵ × ۱٫۲ × ۰٫۶ × π × ۰٫۰۵² ≈ ۰٫۰۰۲۸ کیلوگرم بر متر.</li><li>v = ۲۰ − ۱٫۳ = ۱۸٫۷ متر بر ثانیه؛ h = ۵ + ۲ = ۷ متر.</li><li>سرعت اولیه و C<sub>d</sub> را تغییر می‌دهیم تا ارتفاع و زمان اوج شبیه‌سازی با پرواز جور شود.</li><li>پایداری (CG و CP) را خوب نشان می‌دهد؛ رانش آبی را شبیه‌سازی نمی‌کند.</li></ol><h3>فصل ۱۵: آزمون‌های زمینی، روز پرتاب و ایمنی</h3><ol class=\"qs ans\"><li>پاسخ باز؛ نمونه: آزمون فشار، رهاسازی کپسول، آزمون چتر.</li><li>تا اثر هر تغییر جداگانه معلوم شود.</li><li>اپراتور دست‌کم ۱٫۵ متر طبق شیوه‌نامه (توصیه این کتاب ۵ متر)؛ تماشاگران دست‌کم ۱۰ متر و پشت اپراتور.</li><li>نزدیک نمی‌شویم؛ با شیر تخلیه فشار را خالی می‌کنیم و پس از صفر شدن فشارسنج، با اجازه مدیر پرتاب بررسی می‌کنیم.</li><li>از پر کردن هوا تا فرود، باز کردن کپسول و نمایش تخم‌مرغ سالم.</li></ol><h3>فصل ۱۶: تحلیل پس از پرواز، پرونده مأموریت و فیلم</h3><ol class=\"qs ans\"><li>تعریف مأموریت، طراحی، آزمون‌های زمینی، پروازها، تحلیل پس از پرواز.</li><li>فیلم گزارش تدوین‌شده و روایی است؛ ویدئوی پرواز رسمی پیوسته و بدون تدوین است.</li><li>نشان می‌دهد تیم آزموده، علت را یافته و بهبود داده است.</li><li>پاسخ باز؛ علت باز نشدن چتر، نقش ضربه‌گیر در سالم ماندن و اصلاح پیشنهادی.</li><li>سقف ماژول‌ها ۱۸ امتیاز است؛ ۷ + ۶ + ۴ + ۳ = ۲۰، اما بیش از سقف حساب نمی‌شود؛ پس ۱۸ امتیاز.</li></ol>"}, {"t": "کاربرگ ثبت پرواز", "n": "پیوست ۲", "h": "<p>این کاربرگ برای پرواز رسمی، توسط مربی یا نماینده پژوهش‌سرا امضا می‌شود. برای پروازهای آزمایشی هم از همین کاربرگ (بدون امضا) استفاده کنید.</p><div class=\"tbl\"><table class=\"wh\"><tr><td>نام تیم / کد اثر:</td><td>تاریخ و مکان پرتاب:</td></tr><tr><td>فشار پرتاب (بار):</td><td>حجم آب (میلی‌لیتر):</td></tr><tr><td>جرم پرتابگر (گرم):</td><td>وضعیت باد:</td></tr><tr><td>ارتفاع پیش‌بینی‌شده (متر):</td><td>ارتفاع ثبت‌شده (متر):</td></tr><tr><td>روش سنجش ارتفاع:</td><td>زمان کل پرواز (ثانیه):</td></tr><tr><td>زمان فرود کپسول (ثانیه):</td><td>ماژول‌های اجراشده:</td></tr><tr><td>جداسازی بوستر/مرحله: موفق ☐ ناموفق ☐ ندارد ☐</td><td>جداسازی کپسول: موفق ☐ ناموفق ☐ ندارد ☐</td></tr><tr><td>بازیابی (باز شدن چتر/سامانه): موفق ☐ ناموفق ☐</td><td>وضعیت تخم‌مرغ: سالم ☐ آسیب‌دیده ☐</td></tr><tr><td colspan=\"2\" style=\"height:30mm\">شرح کوتاه پرواز و رویدادهای غیرمنتظره:</td></tr><tr><td>نام و امضای سرگروه:</td><td>نام و امضای مربی / نماینده پژوهش‌سرا:</td></tr></table></div>"}, {"t": "فهرست قطعات و ابزار", "n": "پیوست ۳", "h": "<div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:20%\">بخش</th><th style=\"width:50%\">قطعه</th><th style=\"width:30%\">نکته</th></tr><tr><td class=\"l\">پرتابگر</td><td class=\"l\">بطری PET نوشابه گازدار ۱٫۵ یا ۲ لیتری سالم (چند عدد)</td><td class=\"l\">برای بوسترها هم</td></tr><tr><td class=\"l\">پرتابگر</td><td class=\"l\">کارتن‌پلاست یا فوم سخت برای بالک‌ها</td><td class=\"l\"></td></tr><tr><td class=\"l\">پرتابگر</td><td class=\"l\">توپ نرم یا فوم برای دماغه</td><td class=\"l\"></td></tr><tr><td class=\"l\">کپسول</td><td class=\"l\">ظرف سبک پلاستیکی یا لوله مقوایی، فوم، اسفنج، کش، نی</td><td class=\"l\"></td></tr><tr><td class=\"l\">بازیابی</td><td class=\"l\">پارچه نایلونی سبک یا کیسه زباله ضخیم، نخ محکم، قلاب گردان، نوار رنگی</td><td class=\"l\"></td></tr><tr><td class=\"l\">سکو</td><td class=\"l\">تخته پایه، لوله و اتصالات PVC، چسب PVC، اورینگ، بست کمربندی</td><td class=\"l\"></td></tr><tr><td class=\"l\">سکو</td><td class=\"l\">والو، شیر یک‌طرفه، شیر تخلیه، فشارسنج ۰ تا ۱۰ بار، شلنگ ≥ ۵ متر، طناب ≥ ۵ متر</td><td class=\"l\">فشارسنج سالم الزامی</td></tr><tr><td class=\"l\">سکو</td><td class=\"l\">پمپ دوچرخه با فشارسنج</td><td class=\"l\"></td></tr><tr><td class=\"l\">ایمنی</td><td class=\"l\">عینک ایمنی، حفاظ آزمون فشار، نوار رنگی برای ضامن</td><td class=\"l\">الزامی</td></tr><tr><td class=\"l\">سنجش</td><td class=\"l\">نقاله، نی، نخ و وزنه برای زاویه‌سنج؛ متر نواری؛ زمان‌سنج</td><td class=\"l\"></td></tr><tr><td class=\"l\">ماژول الکترونیک</td><td class=\"l\">Arduino Nano یا ESP32، حسگر BMP280 یا BME280، سروو SG90، باتری کوچک با محفظه، کلید</td><td class=\"l\">اختیاری</td></tr><tr><td class=\"l\">ابزار</td><td class=\"l\">قیچی، کاتر (زیر نظر بزرگ‌تر)، نوار چسب پهن، چسب حرارتی، ترازوی آشپزخانه، ماژیک</td><td class=\"l\"></td></tr></table></div>"}, {"t": "واژه‌نامه", "n": "پیوست ۴", "h": "<div class=\"tbl\"><table class=\"wt gl\"><tr><th style=\"width:22%\">واژه</th><th style=\"width:28%\">معادل انگلیسی</th><th style=\"width:50%\">معنا</th></tr><tr><td class=\"l\">اوج</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Apogee</bdi></td><td class=\"l\">بالاترین نقطه مسیر پرواز</td></tr><tr><td class=\"l\">بالک</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Fin</bdi></td><td class=\"l\">سطح کوچک در عقب پرتابگر برای پایداری</td></tr><tr><td class=\"l\">بوستر</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Booster</bdi></td><td class=\"l\">محفظه یا موتور جانبی که هم‌زمان با پرتابگر اصلی کار می‌کند</td></tr><tr><td class=\"l\">پسا</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Drag</bdi></td><td class=\"l\">نیروی مقاومت هوا</td></tr><tr><td class=\"l\">پایداری</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Stability</bdi></td><td class=\"l\">تمایل پرتابگر به حفظ مسیر با دماغه رو به جلو</td></tr><tr><td class=\"l\">تله‌متری</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Telemetry</bdi></td><td class=\"l\">داده‌های ارسالی از پرنده به ایستگاه زمینی</td></tr><tr><td class=\"l\">جدایش</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Separation</bdi></td><td class=\"l\">جدا شدن بخشی از پرتابگر در پرواز</td></tr><tr><td class=\"l\">حاشیه پایداری</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Stability margin</bdi></td><td class=\"l\">فاصله CG تا CP بر حسب قطر بدنه</td></tr><tr><td class=\"l\">دماغه</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Nose cone</bdi></td><td class=\"l\">بخش جلویی پرتابگر</td></tr><tr><td class=\"l\">رانش</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Thrust</bdi></td><td class=\"l\">نیروی رو به جلویی که پیشران تولید می‌کند</td></tr><tr><td class=\"l\">رهاساز</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Release mechanism</bdi></td><td class=\"l\">سازوکار آزاد کردن پرتابگر از سکو</td></tr><tr><td class=\"l\">سرعت حد</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Terminal velocity</bdi></td><td class=\"l\">سرعتی که در آن پسا برابر وزن است</td></tr><tr><td class=\"l\">سکوی پرتاب</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Launch pad</bdi></td><td class=\"l\">سازه نگه‌دارنده و رهاکننده پرتابگر</td></tr><tr><td class=\"l\">شیر یک‌طرفه</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Check valve</bdi></td><td class=\"l\">شیری که هوا را فقط در یک جهت عبور می‌دهد</td></tr><tr><td class=\"l\">ضامن ایمنی</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Safety pin</bdi></td><td class=\"l\">قفل جلوگیری از رهاسازی تصادفی</td></tr><tr><td class=\"l\">فشار نسبی</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Gauge pressure</bdi></td><td class=\"l\">فشار اضافه بر فشار هوای بیرون</td></tr><tr><td class=\"l\">کپسول</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Capsule</bdi></td><td class=\"l\">محفظه حمل و محافظت از محموله</td></tr><tr><td class=\"l\">کن‌ست</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">CanSat</bdi></td><td class=\"l\">ماهواره کوچک به اندازه قوطی نوشابه</td></tr><tr><td class=\"l\">محموله</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Payload</bdi></td><td class=\"l\">آنچه پرتابگر برای رساندن آن ساخته شده است</td></tr><tr><td class=\"l\">مرحله</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Stage</bdi></td><td class=\"l\">بخشی از پرتابگر که روی بخش دیگر سوار است و پس از آن کار می‌کند</td></tr><tr><td class=\"l\">مرکز جرم</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Center of gravity (CG)</bdi></td><td class=\"l\">نقطه تعادل جرم پرتابگر</td></tr><tr><td class=\"l\">مرکز فشار</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Center of pressure (CP)</bdi></td><td class=\"l\">نقطه اثر برآیند نیروی هوا</td></tr><tr><td class=\"l\">نازل</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Nozzle</bdi></td><td class=\"l\">دهانه خروج پیشران</td></tr><tr><td class=\"l\">نوار کندکننده</td><td class=\"l\"><bdi class=\"en\" dir=\"ltr\">Streamer</bdi></td><td class=\"l\">نوار بلند برای کند کردن فرود قطعات سبک</td></tr></table></div>"}, {"t": "منابع برای مطالعه بیشتر", "n": "پیوست ۵", "h": "<div class=\"tbl\"><table class=\"wt\"><tr><th style=\"width:46%\">منبع</th><th style=\"width:54%\">درباره</th></tr><tr><td class=\"l\">فصل ۴ («مأموریت فضایی») از بخش دوم شیوه‌نامه هشتمین دوره مسابقات نجوم و فناوری‌های فضایی</td><td class=\"l\">الزامات، ایمنی، مستندات و جدول داوری</td></tr><tr><td class=\"l\">ESA Education: CanSat</td><td class=\"l\">مسابقه کن‌ست آژانس فضایی اروپا و راهنمای ساخت ماهواره قوطی‌شکل</td></tr><tr><td class=\"l\">NASA Glenn Research Center: Beginner's Guide to Rockets</td><td class=\"l\">آموزش ساده فیزیک موشک، پایداری و پرتابگر آبی</td></tr><tr><td class=\"l\">نرم‌افزار OpenRocket (رایگان)</td><td class=\"l\">طراحی و تحلیل پایداری موشک‌های مدل</td></tr><tr><td class=\"l\">نرم‌افزار Tracker (رایگان)</td><td class=\"l\">تحلیل حرکت در ویدئو</td></tr><tr><td class=\"l\">Arduino Documentation و کتابخانه‌های Adafruit BMP280 و Servo</td><td class=\"l\">برنامه‌نویسی ارتفاع‌سنج و سازوکار جداسازی</td></tr></table></div><p class=\"hint\">نشانی‌ها: <bdi class=\"url\" dir=\"ltr\">esa.int/Education/CanSat</bdi> ، <bdi class=\"url\" dir=\"ltr\">grc.nasa.gov/www/k-12/rocket</bdi> ، <bdi class=\"url\" dir=\"ltr\">openrocket.info</bdi> ، <bdi class=\"url\" dir=\"ltr\">physlets.org/tracker</bdi> ، <bdi class=\"url\" dir=\"ltr\">docs.arduino.cc</bdi></p>"}], "ver": "new"});
